Ceviri.ekle("vi","olay",{
"OLAYLAR_EK5:1180-05-28:0":{"b": ["Kilij Arslan II lấy Dorylaion (Eskişehir) và Kütahya từ Byzantium", "3ddee6c2"], "d": ["Sau Myriokephalon (1176), các pháo đài Dorylaion và Kütahya của Byzantium trong nội địa Anatolia đã rơi vào tay Kilij Arslan II năm Hijri 576/1180, vào những năm cuối đời của Manuel hoặc sau khi ông qua đời.", "4358e7d4"]},
"OLAYLAR_EK5:1276-06-15:0":{"b": ["Mehmed Bey dòng Karaman được cử làm subaşı Ermenek và nắm quyền cai quản İç İl", "6d62be11"], "d": ["Mehmed Bey dòng Karaman được cử làm subaşı Ermenek năm Hijri 675 (1276) và đưa İç İl vào quyền cai quản của mình; Ermenek trở thành trung tâm đầu tiên của dòng Karaman, dòng sẽ tiến về Konya vào năm sau.", "dc2f3a25"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Ertuğrul Gazi qua đời và Osman Bey nắm quyền tiểu quốc — di sản Söğüt và Domaniç", "395fb9fa"], "d": ["Theo TDV, Ertuğrul Gazi mất năm 680 (1281-82); bài viết cũng ghi nhận có người đưa ra các năm 1288 và 1289. Từ cha mình, Osman Bey không thừa kế một thành phố chinh phục được, mà là hai phần đất do sultan Seljuk cấp cho Ertuğrul, người được ông đặt ở tuyến đầu xa nhất của vùng biên: đất trú đông (yurtluk) tại Söğüt và đồng cỏ mùa hè (yaylak) tại Domaniç. Nghĩa là tiểu quốc này không khởi nghiệp bằng một di sản chinh phạt mà bằng hai phần đồng cỏ được cấp; trên bản đồ, hai nơi này được thể hiện là 'thừa kế' chứ không phải 'chinh phục'.", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Kinh Chiều Sicilia — triều đại Anjou mất đảo Sicilia", "547db635"], "d": ["Cuộc nổi dậy bùng nổ tại Palermo vào giờ kinh chiều ngày Thứ Hai Phục Sinh, chống lại sự cai trị của Charles I xứ Anjou, đã tách đảo Sicilia khỏi triều đại Anjou. Vương quốc Sicilia bị chia làm hai: hòn đảo ngả về Aragon, còn triều đại Anjou trụ lại trong vương quốc trên đại lục lấy Naples làm trung tâm. Các lãnh địa hải ngoại của triều đại này ở Adriatic và Địa Trung Hải cũng vẫn thuộc vương quốc ấy: Corfu, nằm trong tay họ từ năm 1267, và Durrës, mà họ nắm giữ từ những năm 1270, tiếp tục là bộ phận của Vương quốc Naples; các pháo đài Vlorë, Kanina và Himara trên bờ biển Albania cũng ở lại với vương quốc lấy Naples làm trung tâm (viên chỉ huy Vlorë là John of Taxis đã chống cự quân Byzantine suốt năm 1282; Durrës, Vlorë và Kanina rất có thể về tay Byzantine vào đầu năm 1285). Còn Malta mãi đến năm 1284 mới rơi vào tay người Aragon.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Tập kích Kulacahisar — hành động quân sự đầu tiên của Osman Bey", "79b00b14"], "d": ["Mục Osman I của TDV: 'Ông cướp phá rồi phóng hỏa đồn nhỏ Kulaca gần İnegöl (684/1285).' Đây là hành động quân sự đầu tiên của Osman Bey có thể xác định niên đại trong các nguồn. Không có khu định cư nào bị chiếm giữ lâu dài, đồn chỉ bị cướp phá và đốt; vì vậy đây là một cuộc đột kích biên giới điển hình hơn là một cuộc chinh phục. Sự kiện này được coi là điểm khởi đầu hoạt động quân sự của tiểu quốc.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Chinh phục Karacahisar — thành phố đầu tiên giành được và quyền làm chủ Eskişehir", "178ae619"], "d": ["Mục Osman I của TDV: năm 687 (1288), Osman Bey 'chinh phục Karacahisar và làm chủ Eskişehir'. Đây là thành phố thực sự đầu tiên tiểu quốc giành được, và theo truyền thuyết, nhờ thành công này Osman Bey được nâng lên hàng thủ lĩnh sanjak ở vùng biên; tương truyền bài khutbah thứ Sáu đầu tiên nhân danh ông được đọc tại Karacahisar và vị qadi đầu tiên được bổ nhiệm đến đây. Mục Eskişehir của TDV cho biết truyền thống Ottoman đưa ra năm 1291 nhưng tính xác thực của niên đại này đáng ngờ.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Acre rơi vào tay người Mamluk — quân Thập tự bị quét khỏi bờ biển Syria: Sidon và Beirut", "3ca7a464"], "d": ["Acre, trung tâm lâu năm của Vương quốc Thập tự chinh Jerusalem, bị sultan Mamluk al-Ashraf Khalil chinh phục, và quyền thống trị của quân Thập tự ở Palestine chấm dứt. Các hiệp sĩ Đền Thánh rút khỏi Acre đã ẩn náu ở Sidon; khi quân Mamluk áp sát, họ bỏ pháo đài trên biển, chạy sang Síp, và ngay mùa hè đó thành phố về tay người Mamluk. Beirut, trong tay quân Thập tự từ năm 1197, cũng bị tổng trấn Damascus là Sanjar al-Shuja'i chiếm năm 1291. Như vậy, sự hiện diện kéo dài hai thế kỷ của quân Thập tự đã bị xóa khỏi bờ biển Syria-Palestine.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Chinh phục Bilecik và Yarhisar bằng cuộc tập kích ban đêm", "f461b0af"], "d": ["Mục Bilecik của TDV: 'Tuy các tekfur (lãnh chúa Byzantine) trong vùng, trong đó có tekfur Bilecik, đã âm mưu ám sát Osman Gazi, nhưng âm mưu bị phát giác, quân Ottoman bất ngờ tập kích và chinh phục Yarhisar cùng Bilecik (1299).' Hai pháo đài bị chiếm trong cùng một chiến dịch, trong cùng một đêm tập kích. Năm này là bước ngoặt được coi là năm khai lập Nhà nước Ottoman. Các nơi khác được sáp nhập vào cùng ngày: İnegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Trận Koyunhisar (Bapheus) — chiến thắng lớn đầu tiên trước quân đội Byzantine", "584a9512"], "d": ["Mục Osman I của TDV: ngày 27 tháng 7 năm 1302, tại Bapheus (Koyunhisar), Osman Bey giao chiến và đánh bại quân đội Byzantine. Chiến thắng này là bước ngoặt đưa Osman Bey từ một thủ lĩnh biên giới khu vực lên vị thế người sáng lập triều đại. Sau trận đánh, đồng bằng Bursa nằm dưới sự kiểm soát của Ottoman và việc phong tỏa Iznik bắt đầu.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Chiến thắng Dimbos, sau đó chiếm Kite và Ulubat", "e168ab64"], "d": ["Mục Osman I của TDV: năm 702 (1303), liên minh của các tekfur Bursa, Kestel, Kite và Adranos bị đánh tan tại đèo Dimbos; quân địch vừa đánh vừa lùi vào con đèo hẹp và tekfur Kestel tử trận trên chiến trường. Ngay sau chiến thắng, các pháo đài Kite và Ulubat bị chiếm, cắt đứt đường liên lạc trên bộ của Bursa và siết chặt vòng phong tỏa. Orhan còn trẻ cũng tham gia trận này.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Chiến dịch Sakarya: chiếm Leblebicihisar, Lefke, Mekece và Geyve", "a51ba4d3"], "d": ["Mục Osman I của TDV cho biết trình tự chiến dịch Sakarya năm 704 (1304): 'Khi ông đến đồn Leblebüci, tekfur quy phục... ông đến Lefke... tới Mekece... đi đến Geyve và chiếm đồn mà ông thấy bỏ trống.' Lefke là cửa ngõ của thung lũng Sakarya mở về Bilecik. Chỉ riêng chiến dịch này đã đưa chuỗi pháo đài dọc thung lũng vào tay Ottoman, khép kín sườn phía đông của lưu vực Iznik.", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Chios rơi vào sự kiểm soát của dòng họ Zaccaria người Genoa", "9eebe4de"], "d": ["Trước mối đe dọa của dòng Aydın, hoàng đế Byzantium cầu viện Benedetto Zaccaria người Genoa; đảo rơi vào sự kiểm soát của ông (trên danh nghĩa là chư hầu của Byzantium). Quyền thống trị của Zaccaria kéo dài đến năm 1329.", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Samos trở thành sở hữu của người Genoa ở Chios (Zaccaria)", "0e6f51e3"], "d": ["Dòng họ Zaccaria người Genoa, sau khi kiểm soát Chios, đã sáp nhập cả Samos gần như bỏ trống vào tài sản của mình (TDV: 1304–1329).", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Chinh phục các pháo đài ở đèo Geyve: Karaçepüş, Karatigin và Absu", "76907c78"], "d": ["Mục Orhan của TDV: trong chiến dịch Sakarya năm 705 (1305), Orhan 'chinh phục các pháo đài Karaçepüş (Katoikia), Karatigin trước Iznik và Absu (Hypsu, tại đèo Geyve)'. Ba pháo đài này chặn lối đi giữa thung lũng Sakarya và lưu vực Iznik, cắt đứt hoàn toàn viện binh đường bộ cho Iznik. Gazi Abdurrahman được bố trí tại Karaçepüş và Absu ở đèo Geyve; từ đây, thành phố chỉ còn có thể bị hạ bằng cái đói.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Chiến dịch Adranos (Orhaneli) — chiến dịch cuối cùng của Osman Bey", "4811546c"], "d": ["Mục Orhan của TDV ghi chiến dịch đánh pháo đài Adranos vào mùa thu năm 1323 là chiến dịch cuối cùng của Osman Bey. Tekfur Adranos là thành viên liên minh tekfur được lập để chống Ottoman tại Dimbos hai mươi năm trước; chiến dịch này đồng nghĩa với việc thanh toán món nợ cũ ấy. Không rõ ngày chính xác pháo đài bị chinh phục; cuộc hành quân do Orhan Bey tiến hành.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Osman Gazi qua đời và Orhan Bey nắm quyền tiểu quốc", "021487cd"], "d": ["Osman Gazi, người đặt tên cho tiểu quốc, qua đời năm 724 (1324), theo chứng cứ của các văn bản hiến sản (waqf) của Asporça Hatun và Mekece. Con trai ông là Orhan, người đã cầm quân trong các chiến dịch từ năm 1305, lên đứng đầu tiểu quốc sau khi cha mất mà không có bất cứ cuộc tranh ngôi nào. Việc thế hệ sáng lập chuyển giao ngọn cờ không chút xáo trộn cho thấy triều đại đã bình thản vượt qua thử thách lớn đầu tiên trên con đường từ tiểu quốc vùng biên đến một nhà nước.", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["Chios được lấy từ Zaccaria và gắn vào Byzantium", "f6741b26"], "d": ["Hoàng đế Andronikos III đưa Zaccaria rời khỏi đảo và gắn đảo vào Byzantium với Benedetto III làm tổng đốc. Đảo sẽ bị Simone Vignosi người Genoa chiếm đóng năm 1346.", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Samos từ Zaccaria trở về Byzantium (theo chuỗi của Chios)", "08034974"], "d": ["Khi lãnh địa Zaccaria sụp đổ (Chios được gắn vào Byzantium năm 1329), quyền sở hữu của người Genoa ở Samos cũng chấm dứt.", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Trận Pelekanon (Maltepe) và việc chiếm toàn bộ vùng Kocaeli", "389e7bd4"], "d": ["Mục Orhan của TDV: ngày đầu của trận đánh, Orhan Gazi phái một toán ba trăm người để dụ quân đội Byzantine về phía mình; ngày thứ hai, khi các đơn vị do Pazarlu chỉ huy xuống đồng bằng, trận chiến lan rộng, và khi hoàng đế bị trúng tên, quân đội Byzantine rơi vào hoảng loạn. Kết cục rất dứt khoát: 'Orhan chiếm toàn bộ Kocaeli; sau chiến thắng, người Iznik không còn chút hy vọng nào.' Các thị trấn ven biển từ Hereke đến Üsküdar thuộc quyền Ottoman, Gebze được lập làm trung tâm vùng. Đây là đạo quân đế quốc Byzantine cuối cùng đến để cứu Istanbul.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Thành lập madrasa Ottoman đầu tiên ở Iznik", "c85fb625"], "d": ["Ngay sau khi lấy Iznik, Orhan Bey bổ nhiệm Çandarlı Kara Halil làm qadi tại đây, chuyển một vương cung thánh đường thành thánh đường Hồi giáo, cho dựng bên cạnh một imaret (cơ sở bố thí) và một madrasa, mở đầu việc kiến thiết thành phố. Theo mục Dawud al-Qaysari của TDV, việc xây madrasa hoàn tất năm 1336, và Orhan Gazi mời Dawud al-Qaysari làm giáo thụ với lương mỗi ngày 30 akçe. Madrasa này là bước đi mang tính thiết chế đầu tiên của đời sống học thuật Ottoman; bên cạnh sức mạnh chinh phạt, tiểu quốc đã thêm vào một truyền thống học thuật. Việc một kinh đô Byzantine chiếm được bằng chinh phạt biến thành trung tâm học thuật Hồi giáo là dấu hiệu cụ thể đầu tiên cho tham vọng của Ottoman muốn trở thành một nhà nước định cư.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Byzantine phải nộp cống — cuộc vây hãm Izmit và hiệp ước", "0c1ec8d3"], "d": ["Mục Orhan của TDV: mùa hè năm 733 (1333), Orhan vây Izmit bằng một đạo quân lớn và máy bắn đá, hoàng đế chấp nhận thỏa hiệp. Để ông bỏ vây, Byzantine đồng ý nộp cho Orhan mỗi năm 12.000 đồng vàng (hyperpyron); 'như vậy, trong mắt emir Ottoman, Byzantine đã rơi vào địa vị một nước nộp cống'. Đổi lại, Orhan sẽ là bạn của hoàng đế và không tấn công các thành phố lệ thuộc Byzantine. Việc một tiểu quốc vùng biên buộc Đông La Mã nộp thuế cống là lời tuyên cáo cho thấy cán cân quyền lực đã xoay chuyển đến mức nào.", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Samothrace từ người Venice chuyển sang dòng họ Gattilusio người Genoa", "c499ed5f"], "d": ["Dòng họ Gattilusio người Genoa đã đẩy người Venice, vốn nắm đảo từ năm 1204, ra khỏi đảo.", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Sáp nhập tiểu quốc Karesi: Balıkesir, Bergama, Biga, Edremit và Erdek", "c7cb0511"], "d": ["Mục Orhan của TDV (İnalcık) đặt việc sáp nhập vào năm 735 (1334-35): sau khi Demirhan Bey qua đời, các gazi Karesi và Hacı İlbey mời Dursun Bey lên ngôi và cầu viện Orhan. Orhan trước hết tiến đánh Balıkesir; khi Dursun Bey, đang trên đường đến hòa đàm, chết vì một mũi tên bắn ra từ pháo đài Bergama, toàn bộ tiểu quốc được sáp nhập vào đất Ottoman. Trong cùng chiến dịch, Kirmasti và Mihaliç quy phục, Gölyazı bị chiếm và Ulubat, trước đó được để lại theo lời ân xá, bị chiếm hẳn. Orhan cử Süleyman Pasha cai quản sanjak Karesi và lấy Biga làm trung tâm biên trấn — nhờ đó có được đội ngũ thạo đi biển cho việc vượt sang Rumelia. Lưu ý: mục Karesioğulları của TDV lại ghi năm 746 (1345) cho cùng sự kiện; bộ bách khoa tự mâu thuẫn. Các nơi khác được sáp nhập vào cùng ngày: Çanakkale.", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Samos trở thành sở hữu của công ty Maona ở Chios", "01628b2f"], "d": ["Với việc Simone Vignosi người Genoa chiếm Chios và giao quyền quản lý cho công ty Maona, Samos cũng trở thành sở hữu của người Genoa ở Chios (Maona) (TDV: 1346–1475).", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Nhượng ước đầu tiên của Orhan Gazi cho người Genoa", "e64cb196"], "d": ["Thỏa thuận với người Genoa trong cuộc chiến Venezia-Genoa, sau trận hải chiến ở eo Bosphorus tháng 2 năm 1352, Orhan Gazi phái 1000 cung thủ đến phòng thủ Pera và cung cấp 60.000 đồng vàng cho việc chuyên chở quân lính; đổi lại, ông ban cho người Genoa nhượng ước (capitulation) đầu tiên. Toàn văn hiệp ước không còn lưu đến ngày nay. Đây là thỏa thuận chính thức đầu tiên của Ottoman với một cường quốc hải dương châu Âu, và sẽ được gia hạn ba mươi lăm năm sau, năm 1387.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Chiếm Gallipoli — đầu cầu lâu dài ở Rumelia", "ba51a160"], "d": ["Quen thuộc vùng quanh Gallipoli từ khi làm đồng minh của Kantakouzenos trong những năm 1349-1352, người Ottoman chiếm thành này năm 1354; trận động đất lớn làm sập tường thành đã tạo ra cơ hội. Đầu cầu chật hẹp ở Çimpe như vậy trở thành một căn cứ thực thụ ở bờ Rumelia của eo biển, và cánh cửa vào Thrace mở toang. Gallipoli bị mất năm 1366 trong cuộc Thập tự chinh Savoy, và chỉ dứt khoát thuộc chủ quyền Ottoman sau lần chinh phục thứ hai năm 1376. Các nơi khác được sáp nhập vào cùng ngày: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Süleyman Pasha, người chinh phục Rumelia, qua đời", "2dc98228"], "d": ["Süleyman Pasha, con trai trưởng của Orhan Bey và kiến trúc sư của các cuộc chinh phục Rumelia, qua đời vì ngã ngựa trong một cuộc đi săn vào mùa thu năm 1357 — mốc được chấp nhận nhiều nhất trong số các năm mà nguồn đưa ra: 758 (1357), 759 và 760 (1359). Cái chết của vị hoàng tử, người đã thiết lập sự hiện diện lâu dài của Ottoman ở Rumelia qua các cuộc vượt biển 1352-1354, đã nhường thứ tự kế vị cho em ông là Murad. Lăng mộ Süleyman Pasha, được an táng tại Bolayır, vẫn là di tích hoàng tộc Ottoman cổ nhất ở châu Âu.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Luật Pençik — đặt nền móng cho Quân đoàn Janissary", "e5877c2d"], "d": ["Sau các cuộc chinh phục Rumelia, theo lời khuyên của học giả Kara Rüstem người Karaman, chế độ pençik được áp dụng, quy định một phần năm tù binh chiến tranh, hoặc giá trị bằng tiền tương ứng, phải được trích cho nhà nước. Từ việc nuôi dạy những người được chọn trong số tù binh này trong các gia đình người Thổ rồi tuyển vào quân đội đã hình thành hạt nhân của một lực lượng bộ binh thường trực trực thuộc sultan — Quân đoàn Janissary. Việc một tiểu quốc vùng biên dựa trên kỵ binh bộ lạc biến thành nhà nước có quân đội trung ương bắt đầu từ quy định này.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Tiến xuống Tây Thrace: chinh phục Komotini", "9ef69221"], "d": ["Sau khi lấy Edirne, các lực lượng biên trấn hướng về phía tây sông Maritsa, dưới quyền chỉ huy của Gazi Evrenos Bey, đã chiếm Komotini, trung tâm của Tây Thrace. Thành phố trở thành đại bản doanh tiền phương, từ đó Evrenos Bey đưa các cuộc đột kích vào Macedonia. Nhờ vậy, phần Thrace trải đến bờ biển Aegea nằm dưới sự kiểm soát của Ottoman và con đường đến Thessaloniki được mở ra.", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["Varna về tay Công quốc Dobruja và trở thành kinh đô", "2bfe73f9"], "d": ["Trong quá trình tan rã của Đế quốc Bulgaria, Varna bên bờ Biển Đen được sáp nhập vào Công quốc Dobruja do Dobrotitsa lập ra và trở thành kinh đô của tiểu quốc này.", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["Phía tây Plovdiv: sáp nhập Tatar Pazardzhik và Ihtiman", "1664d0e1"], "d": ["Sau khi lấy Plovdiv năm 1372, Tatar Pazardzhik ở đầu trên thung lũng Maritsa và Ihtiman, nơi án ngữ con đèo mở sang Sofia, được đặt dưới quyền cai quản của Ottoman. Tuyến này, vốn nằm trong tay các lãnh chúa địa phương đã thành chư hầu sau trận Chernomen, được chuyển sang cai trị trực tiếp, khiến lộ trình Plovdiv-Sofia thông suốt. Bước tiến này là sự chuẩn bị cho con đường dẫn đến việc chinh phục Sofia mười hai năm sau.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Cuộc nổi loạn của Savcı Bey — hoàng tử và thái tử Byzantine cùng làm phản", "75198c33"], "d": ["Savcı Bey, con trai Murad I, và Andronikos Palaiologos, con trai hoàng đế Byzantine Ioannes V, đã đồng thời nổi dậy chống cha mình tại Bursa và Istanbul vào đầu tháng 5 năm 1373. Liên minh kết hợp người thừa kế của hai triều đại này nhanh chóng bị dập tắt; Savcı Bey bị bắt, bị chọc mù mắt rồi bị hành quyết. Niên đại 787 (1385) mà truyền thống Ottoman đưa ra cho cuộc nổi loạn là sai; sự kiện rơi vào ngay sau những năm Byzantine trở thành chư hầu của Ottoman và cho thấy hai triều đình đã đan xen đến mức nào.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Thung lũng Struma và Mesta: sáp nhập Kyustendil, Petrich, Nevrokop và Drama", "8c0980c4"], "d": ["Các thung lũng Struma và Mesta, nằm trong tay các lãnh chúa Serbia và Bulgaria địa phương đã bắt đầu nộp cống cho Ottoman sau chiến thắng Chernomen, được đặt dưới quyền cai trị trực tiếp của Ottoman nhờ bước tiến của các bey biên trấn. Với việc sáp nhập Kyustendil, Petrich, Nevrokop và Drama, nửa phía đông Macedonia được mở ra, còn Thessaloniki và Serres lọt vào vòng vây. Sự bành trướng của Rumelia về phía tây nam trên bản đồ là kết quả của cuộc hành quân này.", "a50a02ad"]},
"OLAYLAR_EK5:1381-03-28:0":{"b": ["Tiểu quốc Eretna cáo chung và Nhà nước Kadi Burhan al-Din ra đời", "60dcaf57"], "d": ["Nhà Eretna, hình thành từ chức tổng đốc của Ilkhan năm 1335 và cai trị Trung Anatolia lấy Sivas cùng Kayseri làm trung tâm suốt bốn mươi sáu năm, đã tan rã vì tranh chấp trong cung. Kadi Burhan al-Din, làm vizier từ tháng 5 năm 1378, sau khi loại bỏ các đối thủ Kılıcarslan và Hacı Şadgeldi, đã tự xưng sultan vào mùa thu năm 1381, chấm dứt tiểu quốc và lập nên nhà nước mang tên mình. Như vậy láng giềng phía đông của Ottoman đã đổi chủ; từ đó, tuyến Sivas-Kayseri nằm trong tay Kadi Burhan al-Din suốt mười bảy năm.", "f5b2be0c"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Timur chiếm Herat: triều đại Kart cáo chung và Khorasan về tay nhà Timur", "15f6019e"], "d": ["Năm 1380, Khorasan bị xé lẻ bởi cuộc tranh đấu giữa người Sarbadar, nhà Kart và nhà Muzaffar. Sau khi phái con trai Miran Shah đến vùng này, Timur đích thân tiến đánh Herat, vây hãm một thời gian rồi tiếp nhận thành phố từ tay vua Kart là Ghiyath al-Din Pir Ali. Cuộc nổi dậy bùng lên sau khi ông rời đi bị Miran Shah dìm trong máu, và triều đại Kart cai trị Herat từ năm 1255 bị chấm dứt. Từ thời điểm này, toàn bộ Khorasan từ Mashhad đến Nishapur thuộc quyền cai quản của nhà Timur.", "6ae06d43"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Tiến vào nội địa Macedonia: chinh phục Monastir (Bitola) và Ohrid", "63bb7838"], "d": ["Monastir trên đường Via Egnatia và Ohrid bên bờ hồ thuộc quyền cai quản của Ottoman trong các cuộc đột kích hướng về Albania. Cả hai đều là điểm then chốt trên con đường ra biển Adriatic; Ohrid còn là tòa tổng giám mục Chính thống giáo lâu đời nhất vùng Balkan. TDV ghi nhận không có thông tin chắc chắn về ngày chinh phục Ohrid, và người ta đưa ra các mốc 787 (1385) cùng 797 (1395), sau cái chết của Kraljević Marko; ở đây lấy năm 1385 làm căn cứ. Trong các thế kỷ sau, Monastir sẽ trở thành một trong những trung tâm quân sự quan trọng nhất của Rumelia.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Trận Savra — mở cánh cửa vào Albania", "dda6671b"], "d": ["Đáp lời cầu viện của lãnh chúa Albania Karlo Thopia đang bị dòng Balšić dồn ép, quân Ottoman đánh tan quân đội của Balša II trên đồng bằng Savra; Balša tử trận. Cuộc chiến mà người Ottoman tham gia theo lời mời của một lãnh chúa bản địa đã đem lại cho họ ảnh hưởng lâu dài đầu tiên trên vùng đất Albania trải đến bờ biển Adriatic. Chính sách biến mối bất hòa giữa các lãnh chúa trong vùng thành thời cơ này sẽ là phương pháp bất biến của các cuộc chinh phục Balkan suốt thế kỷ tiếp theo.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["'Chiến dịch ba năm' của Timur: chiếm Azerbaijan và miền bắc Iran", "2a98ec51"], "d": ["Chứng kiến tận mắt tình trạng chia cắt của Iran trong các chiến dịch ở Khorasan, năm 788 (1386) Timur tiến quân về phía tây. Trong cuộc hành quân 1386-1388 được gọi là 'chiến dịch ba năm', ông đi qua Mazandaran, Luristan và Gruzia để sang Azerbaijan và đến tận Karabakh; Tabriz, Ardabil, Urmia và Nakhchivan thuộc quyền cai quản của nhà Timur. Việc ông chiếm miền bắc Iran và Azerbaijan cũng mở đầu một cuộc tranh chấp lâu dài với Kim Trướng Hãn quốc, giống như trước kia giữa ulus Jochi và người Ilkhan.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Trận Frenkyazısı và cuộc vây hãm Konya — chiến dịch Karaman đầu tiên", "af4e5d77"], "d": ["Alaeddin Ali Bey dòng Karaman, tuy là con rể, lại bất bình trước đà bành trướng của Ottoman ở Tây Anatolia; Murad I đích thân xuất quân đánh ông. Trong trận đánh tại nơi gọi là Frenk Yazısı, quân đội Ottoman được huấn luyện và dày dạn kinh nghiệm đã đánh bại quân Karaman. Sau đó, pháo đài Konya bị vây, nhưng nhờ Alaeddin Bey được tha tội, tiểu quốc không bị xóa bỏ hẳn. Chiến dịch này là màn mở đầu của cuộc thanh toán dai dẳng giữa Ottoman và Karaman kéo dài một thế kỷ, chỉ kết thúc bằng việc sáp nhập dứt khoát năm 1468.", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["Muş chuyển từ chính quyền Qara Qoyunlu sang quyền cai quản của Timur (789/1387)", "ed2e7a11"], "d": ["Muş, chuyển sang chính quyền Qara Qoyunlu sau thời kỳ Mông Cổ, năm 789 (1387) rơi vào quyền cai quản của Timur, người nắm được lãnh thổ Qara Qoyunlu. Trên bản đồ, Muş được ghi chuyển từ Qara Qoyunlu sang nhà Timur trong năm này.", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Lập xưởng đóng tàu Gallipoli — hải quân Ottoman ra đời", "47546241"], "d": ["Xưởng đóng tàu được tổ chức đầu tiên của Nhà nước Ottoman do Bayezid Tia Chớp lập tại Gallipoli năm 1390, trên nền xưởng tàu còn lại từ thời Byzantine. Kế thừa truyền thống đi biển của các tiểu quốc Tây Anatolia, Ottoman lần đầu tiên trở thành một thế lực hải dương tự đóng tàu cho mình. Nằm ở điểm then chốt của eo Dardanelles, xưởng tàu này làm căn cứ chính của hạm đội Ottoman suốt một thế kỷ rưỡi, từ việc vây hãm Istanbul đến các chiến dịch ở biển Aegea.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Xứ Hamid sáp nhập vào Ottoman: Isparta, Burdur, Uluborlu, Eğirdir", "e3da7de5"], "d": ["Trước việc Alaeddin Bey dòng Karaman tấn công xứ Hamid và lời kêu ca của dân chúng, Bayezid Tia Chớp xuất quân, chiếm toàn bộ phần đất còn lại của nhà Hamid và giao quyền cai quản cho con trai là İsa Çelebi.", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Triều đại Muzaffar cáo chung: Shah Mansur bại trận trước Shiraz", "5fd14eb8"], "d": ["Shah Mansur, vị quân vương hùng mạnh cuối cùng của nhà Muzaffar, dòng họ cai trị Yazd, Fars, Isfahan và Kerman từ năm 1318, đã liên kết với họ hàng để chống Timur. Trong trận đánh gần Shiraz, một emir của ông chạy sang phía đối phương khiến ông mất phần lớn quân lực; ông bại trận và bị giết. Timur sau đó còn cho giết mọi thành viên của dòng họ, nên quyền thống trị của nhà Muzaffar chấm dứt, Fars và Kerman được sáp nhập vào lãnh thổ nhà Timur.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Amasya được sáp nhập vào đất Ottoman", "fe2860cf"], "d": ["Bị vây hãm trong chiến dịch Trung Anatolia của Bayezid Tia Chớp, emir Amasya giao thành cho người Ottoman, và Bayezid vào thành năm 1393. Sultan giao quyền cai quản nơi này cho con trai là Mehmed Çelebi; với tư cách sanjak của hoàng tử, từ đó Amasya trở thành một trong những lò đào tạo quan trọng nhất của hoàng tộc Ottoman. Các khu định cư khác bị mất vào cùng ngày: Ladik (Amasya), Merzifon, Osmancık, Çorum. Lựa chọn này sẽ có tính quyết định trong Thời kỳ Đứt quãng sau này: Çelebi Mehmed chính từ căn cứ Amasya tiến hành cuộc tranh đấu thống nhất lại đất nước.", "bc5eb00d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Timur chiếm Baghdad — người Jalayirid chạy sang Anatolia", "4d5602b3"], "d": ["Sau một cuộc vây hãm kéo dài, Timur chiếm Baghdad; chủ nhân thành phố là sultan Jalayirid Ahmed chạy sang phía tây, nương náu trước tiên nơi người Mamluk, rồi tại triều đình Ottoman. Như vậy, đà bành trướng về phía tây của Timur lần đầu tiên chạm trực tiếp vào vùng ảnh hưởng của Ottoman. Mắt xích đầu tiên trong mối thù giữa hai quân vương bắt đầu từ đây.", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["Chiếm Varna bên bờ Biển Đen", "a84b2abf"], "d": ["Trong lúc vùng đất của Đế quốc Bulgaria giữa sông Danube và Biển Đen bị ép dần, Varna, hải cảng lớn nhất ven biển, thuộc quyền cai quản của Ottoman. Việc chiếm cảng mở đường tiến về Dobruja và đem lại cho Ottoman bến cảng lớn đầu tiên ở bờ tây Biển Đen. Năm mươi mốt năm sau, Varna cũng sẽ là sân khấu của chiến thắng năm 1444, nơi quân Thập tự chinh bị tiêu diệt.", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["Vùng Nevşehir và Ürgüp từ dòng Karaman chuyển vào tay Ottoman", "06ff59e8"], "d": ["Trong các chiến dịch của Bayezid Sấm Sét chống dòng Karaman, vùng Nevşehir (Muşkara) và Ürgüp chuyển sang quyền cai quản của Ottoman năm Hijri 800/1398; sau trận Ankara năm 1402, Timur trả vùng này cho dòng Karaman.", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Nhà nước Kadi Burhan al-Din sụp đổ", "b13391e3"], "d": ["Bị quân vương Aq Qoyunlu là Kara Yülük Osman Bey bắt làm tù binh, Kadi Burhan al-Din đề nghị được thả để đổi lấy việc giao nộp Sivas, nhưng dân thành kháng cự và sultan bị hành quyết ngay trước tường thành. Các thân hào Sivas đưa con trai ông là Alaeddin Ali Çelebi lên đứng đầu, nhưng trước sức ép của Aq Qoyunlu, họ xin Bayezid Tia Chớp viện trợ; quân Ottoman do Süleyman Çelebi chỉ huy đã đánh bại Kara Yülük và làm chủ thành phố. Như vậy Nhà nước Kadi Burhan al-Din đi vào lịch sử, còn Sivas, Tokat, Niksar và Kayseri được sáp nhập vào đất Ottoman. Các nơi khác được sáp nhập vào cùng ngày: Kırşehir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Thách thức của Timur: yêu cầu giao nộp những kẻ đào tẩu bị bác bỏ", "33790bc8"], "d": ["Trước sức ép của Timur, sultan Jalayirid Ahmed và thủ lĩnh Qara Qoyunlu là Qara Yusuf chạy sang đất Ottoman; Timur đòi giao nộp hai kẻ đào tẩu này, Bayezid Tia Chớp (Yıldırım) từ chối. Từ đó, hai quân vương bắt đầu trao đổi những bức thư đầy lời lăng mạ nặng nề. Nền tảng tư tưởng của cuộc chiến đã được dựng lên qua những thư từ này, khi chưa một người lính nào chuyển quân.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Bệnh viện Yıldırım ở Bursa — bệnh viện Ottoman đầu tiên", "5f0dc59a"], "d": ["Trong những năm cho xây Đại Thánh đường (Ulu Cami) nguy nga ở Bursa, Bayezid Tia Chớp còn ban cho thành phố một dar al-shifa (nhà chữa bệnh); đó là mắt xích dành cho y học trong chương trình công trình từ thiện rộng lớn gồm imaret, madrasa, lữ quán và cầu. Công trình này, bệnh viện đầu tiên do nhà nước lập, còn đảm nhận vai trò trường y đào tạo thầy thuốc, định hình khuôn mẫu cho các cơ sở y tế Ottoman. Hoàn thành chỉ hai năm trước thảm họa Ankara, công trình là một trong những mắt xích cuối cùng trong ý tưởng của Bayezid muốn biến Bursa thành kinh đô một đế quốc.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Timur san phẳng Sivas", "f4d79de6"], "d": ["Tiến đến Sivas với sự dẫn đường của Kara Yülük Osman Bey thuộc Aq Qoyunlu và Mutahharten, emir Erzincan, Timur vây thành mười tám ngày; sau khi tiếp nhận thành đầu hàng với lời hứa không đổ máu của ai, ông tiến hành một cuộc thảm sát lớn, cho dồn những người phòng thủ xuống hào rồi lấp đất chôn sống họ. Các công trình quan trọng của thành, trước hết là tường thành, bị phá hủy, và Sivas suy sụp về dân số. Đây là đòn lớn đầu tiên Timur giáng xuống đất Ottoman, hai năm trước trận Ankara.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Bayezid Tia Chớp giành lại Erzincan và Kemah", "7047ca08"], "d": ["Nhân lúc Timur đang viễn chinh Syria, Bayezid đoạt Erzincan và Kemah từ tay Mutahharten, emir Erzincan lệ thuộc Timur. Dù đã không can thiệp khi Sivas bị tàn phá, nước đi này đồng nghĩa với việc thách thức trực tiếp vùng ảnh hưởng của Timur ở Đông Anatolia. Từ đó, quan hệ giữa hai quân vương không còn cứu vãn được.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Tối hậu thư Timur gửi từ Tabriz — bốn điều kiện", "3e1ac50e"], "d": ["Qua sứ giả phái từ Tabriz, Timur nêu bốn điều kiện: trả Kemah cho Mutahharten, hoàn lại đất đã lấy của các bey Anatolia cho chủ cũ, gửi một hoàng tử Ottoman làm con tin và chấp nhận mũ và đai làm dấu hiệu thần phục, và giao nộp Qara Yusuf. Bayezid không chấp nhận điều nào; bất chấp lời thúc ép của các đại thần và sự trung gian của Mutahharten, đàm phán đổ vỡ. Timur quyết giải quyết dứt điểm vấn đề Anatolia trước khi viễn chinh Trung Hoa.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Tiểu quốc Saruhan được tái lập — Manisa tách khỏi Ottoman", "ac747b05"], "d": ["Ba tuần sau thảm bại tại Ankara, với sự hậu thuẫn của Timur, Orhan Bey lên đứng đầu tiểu quốc và xứ Saruhan lại độc lập. Vùng đất lấy Manisa làm trung tâm biến khỏi bản đồ Ottoman mười hai năm sau khi bị Ottoman sáp nhập năm 1390. Đây là một trong những lần áp dụng đầu tiên, có niên đại xác định chắc chắn, của chính sách phục hồi các tiểu quốc của Timur.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Emir Süleyman mang quốc khố chạy sang Rumelia", "0a2b7363"], "d": ["Mang theo quốc khố ở Bursa, văn khố, gia đình và các em, Emir Süleyman xuống thuyền ở Gemlik sang Güzelcehisar (Anadoluhisarı), từ đó đến Gallipoli rồi tuyên bố lên ngôi tại Edirne. Việc chuyển văn khố và quốc khố sang Rumelia mở đầu cho sự dịch chuyển trọng tâm của Ottoman sang vùng Balkan trong suốt một thế hệ. Trên bản đồ, từ ngày này Rumelia được tô bằng màu riêng của Emir Süleyman.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Timur tái lập các tiểu quốc Anatolia — sự thống nhất của người Thổ tan rã", "15187774"], "d": ["Sau chiến thắng Ankara, Timur trả lại đất cũ cho các bey đi theo ông. Xứ Karaman cùng Kayseri, Kırşehir, Sivrihisar và Beyşehir được trao cho các bey Karamanid là Mehmed và Ali; Kütahya và xứ Germiyan cho Yakub Bey II dòng Germiyan; Çankırı và Kalecik, ngoài tuyến Kastamonu-Sinop, cho İsfendiyar Bey dòng Candarid. Các xứ Aydın, Menteşe và Teke cũng trở về với các triều đại cũ. Sự thống nhất người Thổ ở Anatolia mà Bayezid dựng nên trong mười năm tan rã chỉ trong một mùa hè; trên bản đồ, các tiểu quốc này lại hiện ra bằng màu riêng. Các khu định cư khác đổi chủ trong cùng quá trình: Aksaray, Denizli, Ereğli (Konya), Ermenek, Ilgın, Karapınar, Kayseri, Konya, Kırşehir, Kütahya, Sivrihisar, Söke.", "0c3d6fbf"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Timur chiếm Izmir từ tay các Hiệp sĩ Thánh Gioan", "66dd1dd4"], "d": ["Tiến sang phía tây qua Kütahya, Denizli, Aydın, Ayasuluk và Tire, Timur vây và chiếm Izmir ven biển, nơi đã nằm trong tay người Cơ đốc từ năm 1344. Chỉ trong thời gian ngắn, Timur chiếm được pháo đài mà Bayezid suốt nhiều năm không lấy nổi; sau khi đoạt cả các pháo đài lân cận, ông để xứ Aydın cho chủ cũ rồi quay về phía đông. Từ đó thành phố thuộc quyền cai quản của Cüneyd Bey dòng Aydın.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["İsa Çelebi chiếm Bursa — phần đất Anatolia ra đời", "955128c1"], "d": ["İsa Çelebi, người rút về vùng Karesi sau thảm bại Ankara, đã chiếm Bursa khi Timur đang ở Izmir. Ông tuyên bố lên ngôi tại cố đô bị quân Timur cướp phá và thiêu đốt, cho đúc tiền mang tên mình; đến tháng 1 năm 1403, ông được thừa nhận ở Anatolia với danh hiệu 'quân vương của người Thổ'. Trên bản đồ, phần đất này, trải dọc bờ biển châu Á của biển Marmara, hiện bằng màu riêng của İsa Çelebi.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Timur rút khỏi Anatolia", "93a98839"], "d": ["Nhận được tin Bayezid Tia Chớp qua đời tại Akşehir, Timur coi như đã xong việc ở Anatolia và hướng về phía đông. Ở lại phía sau ông là các tiểu quốc đã tuyên bố thần phục và các hoàng tử Ottoman đánh lẫn nhau; một số thành phố như Sivas được để trong tay các emir lệ thuộc Timur kiểu như Mezid Bey. Timur không bao giờ trở lại Anatolia, nhưng cục diện phân mảnh mà ông tạo ra kéo dài mười năm.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Emir Süleyman sang Anatolia: Bursa về tay ông", "9b27aa5f"], "d": ["Nghe tin İsa Çelebi thất bại, Emir Süleyman cùng Çandarlı Ali Pasha đem một đạo quân hùng mạnh sang Anatolia và chiếm Bursa; ghi chép tháng 3 năm 1404 cho thấy Ereğli bên Biển Đen cũng thuộc quyền ông. Chẳng bao lâu Süleyman làm chủ cả Rumelia lẫn phần lớn Anatolia, và Çelebi Mehmed không chống đỡ nổi. Các khu định cư khác chuyển từ Çelebi Mehmed sang Emir Süleyman trong cùng quá trình: Akyazı, Anadolu Hisarı, Absu (Hypsu), Adranos (Orhaneli), Akhisar (Pamukova), Armutlu, pháo đài Aydos, Ayvalık, Balıkesir, Behramkale (Assos), Bergama, Beykoz, Biga. Trên bản đồ, từ ngày này cho đến khi Çelebi Mehmed chiếm lại Bursa (1410), cả hai bờ hiện cùng một màu, thuộc phần của Emir Süleyman.", "0fc7e1b4"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Trận đồng bằng Yenişehir — Çelebi Mehmed rút về Amasya", "f1568288"], "d": ["Sau khi mất Bursa và Ankara, Çelebi Mehmed bại trận trước Emir Süleyman tại đồng bằng Yenişehir, mất mọi thành quả ở Tây Anatolia và lui về căn cứ Tokat-Amasya. Sau thất bại này, ông tránh đụng độ trực tiếp và hướng đến việc củng cố quyền lực trong nội địa Anatolia. Giai đoạn im lìm dài nhất của Thời kỳ Đứt quãng (Fetret) bắt đầu như thế.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Emir Süleyman chiếm Ankara từ tay Çelebi Mehmed", "d6a2acd6"], "d": ["Năm 1406, Emir Süleyman vây Ankara, vốn còn trong tay Çelebi Mehmed sau khi Timur rút khỏi Anatolia. Quan giữ thành là Yakub Bey cầm cự một thời gian, nhưng rồi trao pháo đài cho Süleyman do mưu kế của đại tể tướng Çandarlı Ali Pasha. Vì thế, Çelebi Mehmed thỏa thuận với Mehmed Bey dòng Karaman và hành động chống Süleyman.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Çelebi Mehmed giành lại Sivas từ tay Mezid Bey thuộc phe Timur", "90079b0c"], "d": ["Sau cuộc xâm lược của Timur, quyền cai quản Sivas được để cho Mezid Bey, người lệ thuộc Timur. Çelebi Mehmed đang ở Amasya phái tướng Bayezid Pasha đi lấy thành, và sau một cuộc kháng cự quyết liệt, Sivas lần thứ hai về tay hoàng tộc Ottoman. Như vậy, sáu năm sau trận Ankara, phần đất của Mehmed ở phía đông đã chạm đến đường biên cũ.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Triều đại Artuqid cáo chung: Mardin được giao cho Qara Qoyunlu", "15b06f33"], "d": ["Nhà Artuqid, chi lâu đời nhất của triều đại, cai trị Mardin từ năm 1106, không đứng vững trước sức ép của Aq Qoyunlu. Hiểu rằng không thể giữ được thành, vua Ahmed thỏa thuận với quân vương Qara Qoyunlu là Qara Yusuf và giao Mardin cho ông. Quyền thống trị hơn ba thế kỷ của nhà Artuqid như vậy chấm dứt; Mardin cùng vùng phụ cận trở thành sân khấu tranh đấu giữa Qara Qoyunlu và Aq Qoyunlu cho đến khi về tay Ottoman một thế kỷ sau.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Trận Yambol — Musa Çelebi tiến vào Edirne", "8f978408"], "d": ["Đi qua Wallachia sang Rumelia, Musa Çelebi nhờ sự hỗ trợ của Wallachia và Serbia đã đánh tan lực lượng của Emir Süleyman tại Yambol và tiến vào Edirne. Lần đầu tiên trong Thời kỳ Đứt quãng, Rumelia tuột khỏi tay Emir Süleyman. Tuy nhiên, quyền thống trị của Musa không lâu bền; bốn tháng sau, ông bại trận tại Kosmidion và phải lui vào sâu trong vùng Balkan.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Trận İnceğiz — thất bại đầu tiên của Çelebi Mehmed ở Rumelia", "3c35cd43"], "d": ["Sang Rumelia bằng thuyền của Byzantine, Çelebi Mehmed giao chiến với Musa Çelebi tại İnceğiz; với bảy nghìn lính Janissary dưới quyền, Musa đánh bại Mehmed, buộc Mehmed phải quay về Anatolia. Thất bại này khiến Mehmed chuyển từ giao chiến trực diện sang chiến lược lôi kéo các bey biên trấn Rumelia và lãnh địa despot Serbia về phía mình. Nền tảng cho chiến thắng Çamurlu chín tháng sau được chuẩn bị bằng đường ngoại giao này.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Vây hãm Konya và hiệp ước với nhà Karaman — thu hồi xứ Hamid, xứ Said, Beyşehir, Seydişehir và Akşehir", "0996257e"], "d": ["Để chống nhà Karaman, vốn đã tấn công đất Ottoman và vây, đốt Bursa trong Thời kỳ Đứt quãng, Çelebi Mehmed tổ chức một chiến dịch lớn và vây Konya vào tháng Muharram năm 818. Mehmed Bey II dòng Karaman buộc phải cầu hòa; theo hiệp ước, xứ Hamid (vùng Isparta) và xứ Said lại được sáp nhập vào đất Ottoman, Beyşehir, Seydişehir và Akşehir cũng được trả lại; Sivrihisar mà năm 1402 Timur trao cho nhà Karaman cũng trở về với Ottoman. Chiến dịch này, mốc khởi đầu việc hàn gắn sự thống nhất Anatolia tan rã sau trận Ankara, là một trong những lý do cụ thể khiến Çelebi Mehmed được coi là 'người sáng lập thứ hai'.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Lấy Izmir từ tay Cüneyd Bey dòng Aydın", "2377ca51"], "d": ["Izmir, trung tâm của Cüneyd Bey dòng Aydın, người liên tục đổi phe giữa các hoàng tử suốt Thời kỳ Đứt quãng, đã bị Çelebi Mehmed chiếm sau mười ngày vây hãm; Cüneyd được tha tội và được cử làm thủ lĩnh sanjak Nicopolis. Thành phố mà năm 1402 Timur đã trả cho nhà Aydın như vậy trở về Ottoman sau mười ba năm. Năm 1422, Cüneyd sẽ chiếm lại thành, và vấn đề chỉ được Murad II giải quyết dứt điểm vào những năm 1424-1426.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Torlak Kemal bị hành quyết — Saruhan dứt khoát thuộc Ottoman", "8a09dbf1"], "d": ["Torlak Kemal, người lãnh đạo nhánh Tây Anatolia của phong trào Sheikh Bedreddin, bị đánh bại tại vùng Manisa và bị hành quyết. Từ đó, vùng Saruhan dứt khoát nằm dưới sự kiểm soát của Ottoman, còn tiểu quốc mà Timur phục hồi năm 1402 đi vào lịch sử. Những tàn dư chính trị cuối cùng của Thời kỳ Đứt quãng ở Tây Anatolia như vậy đã bị quét sạch.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Chinh phục Vlorë, Berat và Kanina", "1e1949b8"], "d": ["Năm 1417, người Ottoman đặt Vlorë bên bờ Adriatic, cùng với thành phố Berat ở nội địa và pháo đài Kanina, dưới quyền thống trị của mình. Một năm sau, nỗ lực chiếm lại thành của Venezia thất bại, một tổ chức sanjak được lập tại đây và quyền uy Ottoman trở nên lâu dài. Việc chiếm Vlorë lần đầu tiên đem lại cho Ottoman một hải cảng trực tiếp trên biển Adriatic, tạo cho họ bàn đạp vượt biển hướng đến Ý.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Thu hồi Trung Anatolia: Kayseri và Kırşehir", "204eacb3"], "d": ["Các thành phố Trung Anatolia rơi vào tay nhà Karaman trong Thời kỳ Đứt quãng đã trở về dưới quyền cai quản của Ottoman trong các chiến dịch mà Çelebi Mehmed tiến hành để chấn hưng nhà nước. Với việc sáp nhập Kayseri và Kırşehir, phần lớn lưu vực sông Kızılırmak mất trong trận Ankara đã được thu hồi. Bước tiến này tiếp nối chính sách hướng về phía đông, khởi đầu với cuộc vây hãm Konya bốn năm trước.", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["Người Mamluk giao Kayseri cho Nasir al-Din Muhammad dòng Dulkadir", "aad4b00c"], "d": ["Quân đội Mamluk xuất chinh chống Mehmed Bey dòng Karaman đã chiếm đóng Kayseri; viên chỉ huy Mamluk giao thành cùng vùng phụ cận cho Nasir al-Din Muhammad dòng Dulkadir rồi trở về nước.", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["Mehmed I qua đời và Murad II lên ngôi", "98acac77"], "d": ["Mehmed I, người chấm dứt Thời kỳ Đứt quãng và một lần nữa tập hợp đất nước Ottoman vào một mối, qua đời tại Edirne ngày 25 tháng 6 năm 1421, và con trai ông là Murad lên ngôi tại Bursa. Theo sự sắp đặt với Byzantium trước khi ông mất, các con trai nhỏ của ông sẽ được gửi sang chỗ hoàng đế làm con tin, còn hoàng đế sẽ không thả Mustafa Çelebi, kẻ đòi ngôi mà ông ta đang giữ; Murad II đã từ chối gửi các em sang cho hoàng đế.", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Xóa sổ hẳn nhà Teke: chiếm Antalya", "e65565b2"], "d": ["Tiểu quốc Teke, được Timur phục hồi sau trận Ankara, chấm dứt khi quân Ottoman dưới quyền Hamza Bey vây Antalya; nhân vật quan trọng cuối cùng của tiểu quốc là Osman Çelebi bị loại bỏ. Như vậy, xứ Teke bên bờ Địa Trung Hải, sau hai mươi mốt năm tách rời, đã dứt khoát sáp nhập vào Ottoman. Tiểu quốc này, một chi nhánh tách ra từ nhà Hamid, đã cai trị Antalya từ năm 1321.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Turahan Bey viễn chinh Morea và phá tường thành Hexamilion", "c6c2706d"], "d": ["Do Byzantine ủng hộ Mustafa Çelebi, kẻ tranh ngôi đối địch, Murad II phái Turahan Bey đánh Morea. Turahan Bey phá tường Hexamilion chắn ngang suốt eo đất Corinth, tiến vào bán đảo và gây tàn phá lớn. Hòa bình đạt được với điều kiện không xây lại tường thành và phải nộp cống hằng năm; lãnh địa despot Morea nhờ vậy bị đặt trong tình trạng không phòng vệ về quân sự, nền tảng cho cuộc chinh phục chung cuộc năm 1460 được chuẩn bị từ ba mươi bảy năm trước.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Các tu viện trên núi Athos đặt dưới sự bảo hộ của Ottoman", "562de5ea"], "d": ["Trong những năm Thessaloniki bị vây hãm, cộng hòa tu viện Athos trên nhánh phía đông của bán đảo Chalkidiki đã đến xin Murad II bảo hộ và chấp nhận chủ quyền Ottoman. Quyền sở hữu tài sản và quyền thờ phụng của các tu sĩ được bảo đảm; các tu viện được tự chủ trong công việc nội bộ, đổi lại phải nộp thuế. Trật tự này trở thành ví dụ bền lâu nhất về quan hệ bảo hộ mà Ottoman thiết lập với các thiết chế Chính thống giáo, và kéo dài năm thế kỷ.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Sáp nhập tiểu quốc Taceddin: Niksar", "370ffd47"], "d": ["Trước sức ép của beylerbey Amasya là Yörgüç Pasha, Husam al-Din Hasan Bey dòng Taceddin đã giao nộp chìa khóa xứ sở của mình, lấy Niksar làm trung tâm, vào năm 830 (1427); ông được ban một sanjak ở Rumelia. Tiểu quốc được lập vào nửa sau thế kỷ 14, có lúc cương giới trải đến Kelkit, Amasya, Samsun, Ordu và Giresun, như vậy đã cáo chung. Cùng năm, đất của nhà Hacıemiroğulları cũng được lập sổ địa bạ và sáp nhập vào sanjak Canik; thời đại của các tiểu quốc ở vùng giữa bờ Biển Đen khép lại.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["Belgrade được giao cho Hungary — Hiệp ước Tata", "62481183"], "d": ["Sau khi despot Serbia Stefan Lazarević qua đời, theo Hiệp ước Tata ký giữa vua Hungary Sigismund và người thừa kế của ông là Georg Branković, pháo đài Belgrade được giao cho Hungary. Pháo đài nằm tại nơi hợp lưu sông Danube và sông Sava, cho đến lúc đó nằm trong tay Công quốc despot Serbia, và đối với Ottoman là ổ khóa của cánh cửa mở vào Trung Âu. Cuộc chuyển giao này đã biến Belgrade thành chướng ngại cứng rắn nhất trước đà tiến của Ottoman suốt một trăm năm: các cuộc vây hãm năm 1440 và 1456 đều thất bại, pháo đài chỉ thất thủ năm 1521.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardin từ tay quan trấn thủ Qara Qoyunlu chuyển sang Kara Yülük Osman Bey của Aq Qoyunlu", "d82bc97f"], "d": ["Người Qara Qoyunlu cai quản Mardin, do Qara Yusuf chiếm năm 1409, bằng các tổng trấn; Emir Nasir, người được để lại trấn giữ, đã giao thành cho Kara Yülük Osman Bey của Aq Qoyunlu vào năm 835 (1432). Chính quyền Aq Qoyunlu kéo dài đến đầu thế kỷ 16.", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["Nhà Karaman đoạt Kayseri từ nhà Dulkadir", "2b09e8e8"], "d": ["Nhờ chiến thắng trước nhà Dulkadir, bey Karaman đã sáp nhập Kayseri, Ürgüp, Develi Karahisarı và Uçhisar vào lãnh thổ của mình.", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Sự biến Buçuktepe — cuộc nổi dậy đầu tiên của Janissary và sự trở lại ngai vàng của Murad II", "6388dda1"], "d": ["Sự biến Buçuktepe bùng phát ở Edirne, cuộc nổi dậy đầu tiên của lính Janissary mà lịch sử biết đến, khởi đầu từ yêu sách tăng thêm nửa akçe lương và kết thúc bằng việc phế truất Mehmed II còn trẻ. Ngày 8 tháng Safar năm 850, Murad II vội vã lên đường từ Manisa và bắt đầu thời trị vì thứ hai. Sự kiện này là dấu hiệu đầu tiên cho thấy đội cận vệ kapıkulu đã trở thành một thế lực có tiếng nói đối với ngai vàng, và hun đúc nên sự đề phòng suốt đời của Sultan Chinh phục đối với lính Janissary.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Sáp nhập vùng duyên hải Epirus: Arta và Preveza", "796f7ecf"], "d": ["Mười chín năm sau khi Ioannina đầu hàng năm 1430, Arta và Preveza trên dải ven biển của lãnh địa despot Epirus cũng thuộc quyền cai quản của Ottoman. Nhờ vậy, vịnh Ambracia mở ra biển Ionia được kiểm soát và đường liên lạc ra biển của Ioannina được hoàn chỉnh. Preveza là điểm then chốt của vùng vịnh mà chín mươi năm sau sẽ gắn tên mình với chiến thắng đi vào lịch sử của Barbaros.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Murad II qua đời và Mehmed II lên ngôi lần thứ hai", "8f8256ad"], "d": ["Ngã bệnh sau đám cưới của con trai, Murad II qua đời ở Edirne ngày 1 tháng Muharram năm 855 (3 tháng 2 năm 1451). Mehmed II mười chín tuổi lên ngôi Ottoman lần thứ hai ngày 16 tháng Muharram năm 855 (18 tháng 2 năm 1451) — lần này là lâu dài. Sự trở lại của vị quân vương trẻ, người năm năm trước bị phế truất tại Buçuktepe, là khởi đầu của một triều đại mà hai năm sau được đăng quang bằng việc chinh phục Istanbul và biến tiểu quốc Ottoman thành một đế quốc tầm thế giới.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Cuộc vây hãm Kaffa đầu tiên của liên quân Ottoman - Crimea", "e346d163"], "d": ["Sau khi thỏa thuận với Sultan Chinh phục Mehmed II vào tháng 6 năm 1454, khan Crimea là Hacı Giray đem 7000 kỵ binh vây Kaffa từ phía bộ; một hạm đội Ottoman gồm năm sáu chục chiến thuyền galley cũng dàn trận ngoài khơi. Kaffa của người Genoa nộp cống để được giải vây, và cuộc chinh phục dứt khoát phải chờ thêm hai mươi mốt năm, đến năm 1475. Cuộc hành quân chung đầu tiên này là ví dụ đầu tiên của sự hợp tác quân sự Ottoman - Crimea, sau này sẽ lặp lại trong cuộc chinh phục dứt khoát Kaffa.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Chiếm các đảo ở bắc Aegea: Bozcaada (Tenedos), İmroz (Imbros) và Thasos", "76575895"], "d": ["Ngay sau khi chinh phục Istanbul, để bảo đảm đường biển cho kinh đô mới, Sultan Chinh phục Mehmed II hướng đến các đảo ở cửa eo Dardanelles mở ra biển Aegea; Tenedos và Imbros được lấy từ tay Byzantine, còn Thasos từ gia tộc Gattilusio gốc Genoa. Các đảo khóa chặt hai bờ eo biển này từ đó trở thành mắt xích đầu tiên trong tuyến tiếp tế và phòng thủ Istanbul. Do sự can thiệp của hạm đội Giáo hoàng và Venezia, quyền chủ quyền chao đảo một thời gian và chỉ được xác lập chắc chắn năm 1459.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Chinh phục Kosovo: chiếm Pristina và Novi Pazar", "d7ed2345"], "d": ["Quân đội Ottoman tiến đánh lãnh địa despot Serbia đã chiếm Pristina trên cánh đồng Kosovo và Novi Pazar, trung tâm vùng Raška; trong cùng chiến dịch, Novo Brdo, nổi tiếng với các mỏ bạc, cũng bị chiếm. Nửa phía nam Serbia như vậy được đặt dưới quyền cai trị trực tiếp của Ottoman, còn chính quyền despot ở Smederevo bị cắt khỏi vùng đất trung tâm. Cuộc chinh phục này là bước quyết định trên con đường dẫn đến việc sáp nhập toàn bộ Serbia bốn năm sau.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["Peć (İpek) thuộc quyền cai quản của Ottoman — một trong các trung tâm của sanjak Dukagjin", "19511588"], "d": ["Ngay sau chiến dịch Serbia năm 1455 của Sultan Chinh phục Mehmed II, Peć, trung tâm của tòa thượng phụ Serbia, thuộc quyền cai quản của Ottoman; trong các nguồn Ottoman không có ghi chép nào về sự chuyển giao này. Theo thời gian, thị trấn trở thành một thị trấn Hồi giáo nhỏ và là một trong những nơi cư trú của sanjak-bey trong sanjak Dukagjin.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Chinh phục Enez và Samothrace — hoàn tất dải ven biển Tây Thrace", "106e723b"], "d": ["Enez, nơi sông Maritsa đổ ra biển, bị lấy từ tay gia tộc Gattilusio gốc Genoa vốn nắm giữ suốt tám mươi năm; đảo Samothrace phụ thuộc vào đây cũng bị chiếm trong cùng chiến dịch. Khi Enez thất thủ, dải ven biển Tây Thrace trở thành đất Ottoman liền một mạch từ Thessaloniki đến Gallipoli. Gia tộc Gattilusio chỉ còn giữ Lesbos (Midilli); đảo này cũng sẽ bị chiếm sáu năm sau.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Cuộc vây hãm Belgrade thất bại", "3d53a604"], "d": ["Sau khi chinh phục Istanbul, Sultan Chinh phục Mehmed II vây Belgrade, được coi là ổ khóa của Trung Âu; nhưng viện binh mà János Hunyadi đưa đến qua đường sông Danube và những người tình nguyện do nhà thuyết giáo Thập tự Capistrano tập hợp đã ngăn pháo đài thất thủ. Dù tỏ rõ lòng dũng cảm cá nhân trước thành, sultan bị thương và buộc phải rút lui. Thất bại này đóng biên giới Hungary trước bước tiến của Ottoman suốt sáu mươi lăm năm; mãi đến năm 1521, Süleyman Lập pháp mới lấy được Belgrade.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Chinh phục miền bắc Morea: Patras (Balyabadra)", "c08a8509"], "d": ["Cùng những năm sáp nhập Serbia, lực lượng của Sultan Chinh phục Mehmed II hướng đến lãnh địa despot Morea và chiếm Patras ở tây bắc bán đảo. Cảng này án ngữ cửa vịnh Corinth và là chìa khóa để vào Morea bằng đường bộ; việc chiếm được nó đặt nền móng cho cuộc chinh phục chung cuộc hai năm sau. Đây là bến cảng lớn cuối cùng mà các despot Byzantine dùng để liên lạc với thế giới Latin.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Chiếm vùng duyên hải Tây Biển Đen: Amasra", "f43608fc"], "d": ["Amasra, thuộc địa kiên cố của người Genoa ở Tây Biển Đen, đã đầu hàng không kháng cự trước sức ép phối hợp của hạm đội và bộ binh của Sultan Chinh phục Mehmed II. Cảng này trên bờ biển Bartın-Zonguldak tồn tại như một túi đất Latin nằm giữa đất nhà Candarid và đất Ottoman; khi chiếm được nó, bờ biển được liền một dải. Amasra thất thủ là bước đầu tiên của cuộc đại viễn chinh Biển Đen hai năm sau (1461) nhằm vào Sinop và Trebizond.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Chinh phục đảo Lesbos (Midilli)", "fe17aeba"], "d": ["Vào tháng Dhu'l-Hijja năm 866, quân đội Ottoman do Sultan Chinh phục Mehmed II chỉ huy, sau một cuộc vây hãm ngắn mà dữ dội, đã chiếm Lesbos từ tay gia tộc Gattilusio gốc Genoa và sáp nhập đảo. Việc hòn đảo lớn nhất bắc Aegea thất thủ cũng xóa bỏ căn cứ quan trọng cuối cùng của người Genoa trong vùng. Nhờ gần bờ biển Anatolia, từ đó hòn đảo làm tiền đồn cho hạm đội Ottoman, đồng thời đi vào lịch sử hàng hải như nơi anh em Barbarossa trưởng thành.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Cuộc chiến tranh Ottoman - Venezia kéo dài mười sáu năm bắt đầu", "563ddb68"], "d": ["Để chặn bước tiến của Ottoman ở Morea và Aegea, người Venezia liên minh với giới cầm quyền Karaman và Aq Qoyunlu rồi phát động chiến tranh năm 1463. Chiến lược bao vây này, với Uzun Hasan ở phía đông, Venezia ở phía tây và Karaman ở giữa, buộc Sultan Chinh phục phải chiến đấu cùng lúc trên nhiều mặt trận. Cuộc tranh đấu mười sáu năm bao trùm mọi chiến dịch lớn của thời kỳ, từ trận Otlukbeli đến các cuộc viễn chinh Albania, và chỉ kết thúc bằng Hiệp ước Istanbul năm 1479.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Chinh phục phần lớn Herzegovina: Trebinje và Mostar", "f54c0100"], "d": ["Đất đai của Công tước Herzegovina là Stjepan Vukčić Kosača, người lập chính quyền riêng tách khỏi Bosnia, ba năm sau khi Vương quốc Bosnia sụp đổ phần lớn đã thuộc quyền cai quản của Ottoman: ở phía nam, Trebinje bị chiếm năm 1466 \"cùng với gần như toàn bộ vùng Herzegovina\". Mostar, được hình thành quanh hai đồn nhỏ ở cầu sông Neretva, hẳn cũng bị chiếm ít lâu trước khi Blagaj, trung tâm Herzegovina, bị chinh phục trong những năm 1466-1468; trong sổ địa bạ tóm lược Bosnia năm 1468-1469, nơi này được ghi với tên \"Pháo đài có cầu\" (Köprülü Hisar). Cuộc chinh phục Herzegovina, với các pháo đài còn lại của công quốc, hoàn tất năm 1483.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["Chiến dịch Albania lần thứ hai — Sultan Chinh phục đích thân tiến đánh Skanderbeg", "9cdd2bfa"], "d": ["Để bẻ gãy cuộc kháng chiến hơn một phần tư thế kỷ của Skanderbeg, Sultan Chinh phục Mehmed II đã tổ chức và đích thân chỉ huy các chiến dịch lớn trong những năm 1466-1467. Quân đội Ottoman vây Krujë (Akçahisar) và xây pháo đài Elbasan để kiểm soát vùng này. Chiến dịch bẻ gãy sức mạnh kháng chiến Albania nhưng không hạ được pháo đài; sự thần phục hoàn toàn của vùng phải đến mười năm sau khi Skanderbeg qua đời.", "00e75aca"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["Quân tiên phong Aq Qoyunlu lấy pháo đài Bingöl từ Qara Qoyunlu", "51b94cbc"], "d": ["Trong những tuần cuối của chiến dịch Jahan Shah tiến hành chống Uzun Hasan, quân tiên phong Aq Qoyunlu chiếm pháo đài Bingöl; khi Jahan Shah bị giết ngày 10 tháng 11 năm 1467, quyền thống trị của Qara Qoyunlu trong vùng chấm dứt.", "c150063d"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Nhà nước Qara Qoyunlu sụp đổ: Jahan Shah bị giết", "30bc6358"], "d": ["Quân vương Qara Qoyunlu Jahan Shah, đang trên đường trở về từ chiến dịch đánh Uzun Hasan vì mùa đông ập đến, bị tập kích và bị giết khi đang chạy trốn giữa Bingöl và Kiğı. Sau đòn này, nhà nước không gượng dậy được; vị quân vương cuối cùng Hasan Ali bị Uğurlu Mehmed, con trai Uzun Hasan, bắt và giết năm 1469. Quyền thống trị gần một thế kỷ của Qara Qoyunlu ở Đông Anatolia, Azerbaijan và Iraq như vậy chuyển sang tay Aq Qoyunlu.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Skanderbeg qua đời — cuộc kháng chiến Albania lụi tàn", "9158c35f"], "d": ["Skanderbeg, người được đào tạo trong triều đình Ottoman nhưng nổi dậy sau thất bại Zlatitsa năm 1444 và kháng cự ở Albania hơn một phần tư thế kỷ, qua đời tại Lezhë, nơi ông lánh nạn. Cuộc kháng chiến nhiều lần cầm chân quân đội Ottoman dưới thời Murad II và Sultan Chinh phục đã mất sự lãnh đạo trung tâm sau cái chết của ông. Khi mặt trận Albania được Giáo hoàng và Venezia nuôi dưỡng sụp đổ, trong vòng mười năm người Ottoman chiếm Krujë và Shkodër, dứt khoát sáp nhập vùng này vào lãnh thổ.", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["Chính quyền Ottoman được thiết lập tại Kayseri: Gedik Ahmed Pasha chấm dứt dòng Karaman", "33cf35fc"], "d": ["Khi Gedik Ahmed Pasha chấm dứt công quốc Karaman năm 1474, Kayseri đi vào quyền cai quản của Ottoman; trong suốt thế kỷ 15, thành phố đã đổi chủ giữa các dòng Dulkadir, Ramazan và Karaman. Dưới sự cai trị của Ottoman, Kayseri trở thành trung tâm sanjak của tỉnh beylerbeylik Karaman.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["Samos bị bỏ hoang: quyền sở hữu của người Genoa (Maona) chấm dứt", "5bdc380c"], "d": ["Theo TDV, đảo bị bỏ hoang sau năm 1475; năm 1479, Sultan Mehmed II Chinh phục chinh phục đảo và cho xây pháo đài.", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Thất bại Vaslui (Rahova) ở Moldavia", "a1a74bf7"], "d": ["Voivode Moldavia Stephen Đại đế dụ quân Ottoman do beylerbey Rumelia là Hadım Süleyman Pasha chỉ huy vào vùng đầm lầy và giáng cho họ một thất bại nặng nề. Là một trong những thất bại trên bộ nặng nhất thời Sultan Chinh phục, trận thua này gây tiếng vang lớn ở châu Âu và đem lại danh tiếng cho Stephen trong thế giới Thập tự. Năm sau, sultan sẽ đích thân xuất chinh để trả đũa.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Chiến thắng Valea Albă (Akdere) — chiến dịch Moldavia", "45a66791"], "d": ["Đích thân xuất chinh để trả thù thất bại Vaslui năm trước, Sultan Chinh phục Mehmed II dùng quân đội Ottoman đánh tan tác các đơn vị Moldavia tại Valea Albă rồi tiến vào Suceava, trung tâm của công quốc. Nhưng các pháo đài không bị chiếm; do thiếu lương thực, dịch hạch bùng phát trong lính Janissary và sự chuẩn bị của Hungary, quân đội phải rút lui. Sự thần phục dứt khoát của Moldavia chỉ đạt được trong những năm sau, cùng với việc chiếm Kiliya và Akkerman năm 1484.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Chinh phục Krujë (Akçahisar) và hoàn tất Albania", "559a79b4"], "d": ["Mười năm sau khi Skanderbeg qua đời, năm 1478, với việc chiếm Krujë, Drivast, Lezhë và Žabljak, cuộc chinh phục Albania phần lớn đã hoàn tất. Việc pháo đài Krujë, từng kháng cự quân đội Ottoman nhiều năm và là biểu tượng cuộc kháng chiến của Skanderbeg, thất thủ đồng nghĩa với sự cáo chung của liên minh Venezia - Albania trong vùng. Shkodër còn lại sẽ được nhượng cho Ottoman theo Hiệp ước Istanbul ký năm sau.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Sáp nhập bán đảo Taman", "4ef917b8"], "d": ["Sau khi lấy Kaffa và Kerch năm 1475, hạm đội mà Sultan Chinh phục Mehmed II phái đến bờ biển Kavkaz đã chiếm Anapa, Kopa cùng với Matrega (Tamatarkhan) của người Genoa trên bán đảo Taman. Như vậy, cả hai bờ eo biển đều được kiểm soát và lối vào biển Azov hoàn toàn nằm trong tầm khống chế. Taman, cửa ngõ vào Bắc Kavkaz, được sáp nhập vào sanjak Kaffa.", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["Samos đi vào quyền cai quản của Ottoman (Sultan Chinh phục)", "c877bc14"], "d": ["Sultan Mehmed II Chinh phục chinh phục Samos, cho xây một pháo đài và tổ chức lại việc kiểm kê; pháo đài bị Bayezid II cho phá năm 1483 vì lý do chính trị.", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Cuộc vây hãm Rhodes thất bại", "35a85c28"], "d": ["Theo lệnh Sultan Chinh phục Mehmed II, hạm đội 160 chiếc do Mesih Pasha chỉ huy đã vây Rhodes vào mùa xuân năm 885 (1480), và hòn đảo bị phong tỏa suốt ba tháng. Các Hiệp sĩ Thánh Gioan dưới sự lãnh đạo của Đại Thống lĩnh Pierre d'Aubusson kháng cự mãnh liệt bất chấp tổn thất nặng nề; sau khi cuộc tổng công kích cuối cùng ngày 20 tháng Jumada I năm 885 cũng bị đẩy lui, hạm đội rút đi ngày 3 tháng 8. Sau thất bại này, tường thành được xây mới hoàn toàn, trở thành công sự kiên cố nhất châu Âu, và mãi đến năm 1522 Süleyman Lập pháp mới lấy được đảo.", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["Nikaria (Ikaria) thuộc quyền cai quản của Hiệp sĩ Thánh Gioan ở Rhodes", "5cbc2669"], "d": ["Nikaria, nằm giữa Samos và Chios, từ năm 1481 đến 1521 thuộc quyền cai quản của Hiệp sĩ Thánh Gioan ở Rhodes.", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Trận Yenişehir — Cem Sultan bại trận", "c35abee2"], "d": ["Sau khi Sultan Chinh phục qua đời, hai anh em hành động tranh ngôi đã đối đầu trên đồng bằng Yenişehir, và Cem Sultan thất bại dứt khoát. Hoàng tử, người đã trị vì mười tám ngày ở Bursa và cho đọc khutbah nhân danh mình, sau thất bại buộc phải lánh trước tiên đến Konya, rồi sang đất Mamluk. Yenişehir mở đầu cuộc khủng hoảng triều đại dai dẳng nhất lịch sử Ottoman: vấn đề Cem sẽ làm tê liệt chính sách đối ngoại Ottoman trước châu Âu suốt mười bốn năm.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Sáp nhập Herzegovina", "bf247891"], "d": ["Đất đai của Công quốc Herzegovina, còn tồn tại sau khi Bosnia bị chinh phục năm 1463, lần lượt từng giai đoạn thuộc quyền cai quản của Ottoman: Trebinje và Mostar đã bị chiếm năm 1466, sanjak Herzegovina được lập năm 1470, còn những vùng đất cuối cùng của công quốc ven Adriatic cùng với Herceg Novi bị chinh phục đầu năm 1482 và sáp nhập vào sanjak. Như vậy, vùng núi phía sau bờ biển Adriatic hoàn toàn thuộc Ottoman, và Bosnia cùng Herzegovina trở thành một địa bàn hành chính thống nhất. Con trai của vị công tước cuối cùng, người vào cung đình Ottoman, chính là Hersekzade Ahmed Pasha, sau này thăng đến chức đại tể tướng.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["Để Zakynthos (Zaklise) cho Venice đổi lấy cống nạp hằng năm", "268a691a"], "d": ["Zakynthos, một trong các đảo Ionia lấy từ dòng họ Tocco vào cuối thời Sultan Chinh phục, được để lại cho Venice trong khi vị sultan mới, đang bận với vấn đề Cem Sultan, tìm kiếm sự yên ổn ở phía tây. Đảo được giao cho một chính quyền Venice công nhận quyền bá chủ của Ottoman và nộp cống hằng năm năm trăm ducat. Như vậy trên biển Ionia, quyền cai quản trực tiếp của Ottoman chỉ còn ở Lefkada (Ayamavra).", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Cem Sultan lánh nạn đến Rhodes", "2228d6da"], "d": ["Sau khi nỗ lực vây Konya cũng không thành, Cem Sultan cùng khoảng ba chục người trốn khỏi Anatolia, đến Rhodes và được các Hiệp sĩ Thánh Gioan đón tiếp theo nghi lễ. Nhưng sự làm khách chẳng bao lâu biến thành giam cầm; hoàng tử được chuyển giao trước tiên cho Pháp, rồi cho Giáo hoàng, trở thành con bài trong tay chính trường châu Âu. Bayezid II phải trả một khoản tiền hằng năm để người em bị giữ lại, và các động thái quân sự của Ottoman hướng về phương Tây bị đình lại cho đến khi Cem qua đời.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Chiến tranh Ottoman - Mamluk bùng nổ (mặt trận Cilicia)", "3fe3f0c7"], "d": ["Cuộc tranh giành ảnh hưởng đối với nhà Dulkadir và mối hiềm thù còn lại từ việc Cem Sultan lánh sang đất Mamluk đã khơi mào năm 1485 một cuộc chiến kéo dài sáu năm giữa hai cường quốc Sunni lớn. Trong các trận giao tranh ở Cilicia quanh Adana và Tarsus, không bên nào giành được ưu thế; quân đội Ottoman hứng mấy đòn nặng. Cuộc chiến này là giai đoạn đầu của sự rạn vỡ trong quan hệ Ottoman - Mamluk, mở màn cho quá trình ba mươi năm sau kết thúc bằng các chiến dịch Marj Dabiq và Ridaniya của Selim I (Yavuz).", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Hòa bình Ottoman - Mamluk — Tunis làm trung gian", "60dd6719"], "d": ["Trong cuộc chiến Ottoman - Mamluk khởi đầu năm 1485, không bên nào giành được thắng lợi dứt khoát; nhờ sự trung gian của quân vương Hafsid xứ Tunis là Osman, hai bên đạt thỏa thuận năm 1491. Hiệp ước đưa đường biên giới phần lớn trở lại như trước chiến tranh, và cuộc thanh toán giữa hai quốc gia Hồi giáo được hoãn lại một thế hệ. Sáu năm tranh đấu hao mòn là một trong những lý do chính khiến Bayezid II theo đuổi chính sách đối ngoại thận trọng và chú trọng chấn chỉnh nội bộ thay vì hướng sang phía đông.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Ottoman đón nhận người Do Thái Sephardi bị trục xuất khỏi Tây Ban Nha", "5c2b5c24"], "d": ["Sau khi Granada thất thủ, một bộ phận người Do Thái chạy trốn sự bức hại của tòa án dị giáo ở Tây Ban Nha đã lánh sang đất Ottoman và được định cư tại nhiều thành phố. Dưới sự cai quản của Ottoman, các cộng đồng Sephardi này có được sự tự do chưa từng thấy trước đó: được định cư nơi mình muốn, sống theo đức tin, mở cơ sở giáo dục và xây hội đường mới. Cuộc di cư này, với kiến thức in ấn, y học và tài chính mà họ mang theo, đã biến đổi đời sống kinh tế của Thessaloniki và Istanbul, trở thành ví dụ được bàn đến nhiều nhất ở châu Âu về trật tự khoan dung Ottoman.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Cem Sultan qua đời — chấm dứt mười bốn năm làm con tin", "f6588b70"], "d": ["Bị Giáo hoàng chuyển giao cho vua Pháp Charles VIII, Cem Sultan, sau khi rời Rome ngày 27 tháng 1 năm 1495, qua đời tại nơi gọi là Castel Capuana; các nguồn ghi nhận có thể ông bị giới thân cận Giáo hoàng đầu độc. Cái chết của hoàng tử, người suốt mười bốn năm bị các quốc gia châu Âu nắm giữ như con bài đe dọa Ottoman, cuối cùng đã cởi trói cho Bayezid II. Quả vậy, từ đó sultan sẽ tuyên chiến với Venezia và đưa hạm đội đến chiến thắng lớn đầu tiên.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Hải chiến thắng lợi Sapienza (Zonchio) — thành công lớn đầu tiên của hạm đội ở Địa Trung Hải", "9754aaef"], "d": ["Được rảnh tay nhờ vấn đề Cem đã kết thúc, năm 1499 Bayezid II tuyên chiến với Venezia; hạm đội Ottoman đánh bại hạm đội Venezia ngoài khơi Sapienza (Zonchio), giành thắng lợi hải chiến lớn đầu tiên ở Địa Trung Hải. Với chiến thắng này, hạm đội đã tuyên bố rằng từ nay mình có thể đương đầu với Venezia trên biển.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["Mất Cephalonia và Ithaca", "60f0f687"], "d": ["Bị chấn động bởi việc Methoni và Koroni bị chiếm, Venice liên kết với Tây Ban Nha mở cuộc phản công và vây hãm Cephalonia, nằm trong tay Ottoman từ năm 1479. Sau bốn mươi bảy ngày kháng cự, pháo đài thất thủ, đảo cùng với Ithaca thuộc về Venice và suốt ba trăm năm không trở lại quyền cai quản của Ottoman. Tổn thất này tạo ra thế cân bằng trong đó những gì giành được ở Morea phải trả lại ở biển Ionia.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Kim Trướng Hãn quốc sụp đổ và Crimea trỗi dậy", "0d1dc515"], "d": ["Vị quân vương cuối cùng Sheikh Ahmed Khan (1481-1502) không cứu được đất nước khỏi cơn khủng hoảng mà nó rơi vào, và năm 1502 Kim Trướng Hãn quốc đi vào lịch sử bởi đòn giáng của khan Crimea Mengli Giray. Do tranh ngôi và chia cắt, trên đất cũ của Kim Trướng đã xuất hiện các hãn quốc Crimea, Kazan, Nogai, Astrakhan và Sibir. Thắng lợi này của Crimea dưới sự bảo hộ của Ottoman khiến ảnh hưởng Ottoman ở phía bắc Biển Đen trở nên không thể tranh cãi, còn khoảng trống hình thành trong vùng sẽ được Moskva lấp đầy trong thế kỷ sau.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Chiến tranh Ottoman - Venezia kết thúc và hòa bình", "125b1526"], "d": ["Cuộc chiến bắt đầu năm 1499, làm Venezia chao đảo với việc mất Sapienza, Lepanto, Modon và Koroni, kết thúc bằng hòa bình năm 1502. Mất những căn cứ quan trọng nhất ở Morea, Venezia phải công nhận ưu thế của Ottoman để đổi lấy việc giữ đặc quyền thương mại ở Đông Địa Trung Hải. Thời trị vì vốn được coi là thận trọng của Bayezid II, qua cuộc chiến này, lần đầu tiên đã nâng Ottoman lên vị thế một cường quốc hải dương đáng gờm ở Địa Trung Hải.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Cuộc nổi dậy của Şahkulu — cuộc khởi nghĩa Qizilbash lan từ vùng Teke đến Sivas", "3beadca7"], "d": ["Şahkulu Baba Tekeli, người công khai nổi loạn năm 1510 dưới ảnh hưởng của sự tuyên truyền Safavid ở Anatolia, đã đột kích khu chợ Antalya vào tháng 3 năm 1511 và đánh bại quân Ottoman ở Kütahya cùng vùng phụ cận vào tháng 4. Trong trận đụng độ cuối cùng với đại tể tướng Hadım Ali Pasha gần Sivas, cả hai bên đều tổn thất nặng; cả đại tể tướng lẫn thủ lĩnh nổi loạn đều thiệt mạng. Cuộc khởi nghĩa làm lung lay quyền uy của nhà nước ở Anatolia này đã phơi bày khoảng trống quyền lực trong những năm cuối đời Bayezid II và trở thành lý lẽ mạnh nhất cho bước tiến đến ngai vàng của hoàng tử Selim.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Bayezid II thoái vị và Sultan Selim I (Yavuz) lên ngôi", "c4cfab69"], "d": ["Trước sức ép của hoàng tử Selim, người có lính Janissary hậu thuẫn trong cuộc tranh ngôi với các anh em, ngày 24 tháng 4 năm 1512 Bayezid II thoái vị, và ngay hôm đó Selim I lên ngôi, trở thành quân vương Ottoman thứ chín. Vị sultan già qua đời trên đường đến Didymoteicho, nơi ông sinh ra, tại làng Abalar gần Çorlu, ngày 25 tháng Rabi' I năm 918 (10 tháng 6 năm 1512). Thay cho triều đại ba mươi mốt năm thận trọng và hướng nội là thời đại của Yavuz, người trong tám năm sẽ nhân đôi lãnh thổ đế quốc.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["Chinh phục pháo đài Sinj", "83271ea5"], "d": ["Lực lượng tập kích akinji của Ottoman ở biên giới Bosnia đã chiếm từ Vương quốc Hungary pháo đài Sinj vươn vào nội địa Dalmatia. Đây là mắt xích sớm của tuyến biên giới Dalmatia, tuyến sẽ được mở rộng chín năm sau với việc Gazi Hüsrev Bey chinh phục Knin và vùng phụ cận; pháo đài sẽ rơi vào tay Venice năm 1686.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Trận Yenişehir và việc loại bỏ hoàng tử Ahmed", "e2ed15dd"], "d": ["Sultan Selim I đánh bại người anh là hoàng tử Ahmed, đối thủ mạnh nhất tranh ngôi, trên đồng bằng Yenişehir gần Bursa, bắt làm tù binh rồi loại bỏ. Như vậy cuộc tranh chấp huynh đệ kéo dài từ năm 1511 khép lại, sự chia rẽ nội bộ ở Anatolia chấm dứt. Selim, sau khi củng cố hậu phương, giành được sự tự do để hướng đến vấn đề Safavid.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Sultan Selim I vào Tabriz", "dad2e227"], "d": ["Sau chiến thắng Chaldiran, quân đội Ottoman vào kinh đô Safavid là Tabriz, và khutbah trong thành được đọc nhân danh sultan. Selim ở lại một tuần và cho chuyển một bộ phận nghệ nhân và học giả Tabriz về Istanbul; cuộc chuyển cư này sẽ ảnh hưởng sâu sắc đến nghệ thuật cung đình Ottoman. Tuy thành phố bị bỏ lại khi mùa đông gần kề và lính Janissary bất mãn, ưu thế Safavid ở phương Đông đã bị bẻ gãy. Những nơi trên bản đồ chuyển sang Ottoman vào ngày này không liền kề nhau, và điều đó đúng: Tabriz là một cuộc chiếm đóng quân sự chín ngày; đồng bằng Erzincan đầu hàng không giao chiến trong chiến dịch, còn pháo đài Kemah ở giữa đồng bằng vẫn kháng cự thuộc Safavid đến ngày 19 tháng 5 năm 1515; Siirt được Khalil Bey, vua Hasankeyf thoát khỏi nhà tù của Shah Ismail ở Tabriz, lấy lại từ tay Safavid sau khi quy phục Ottoman — Diyarbakır quanh đó vẫn thuộc Safavid đến năm 1515, Hasankeyf đến năm 1517.", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["Muş và Bingöl (Çapakçur) từ Safavid chuyển sang quyền cai quản của Ottoman", "b0a53b5a"], "d": ["Khi miền Đông Anatolia được lấy từ Safavid sau Chaldiran, Muş đi vào quyền cai quản của Ottoman năm Hijri 921/1515; Çapakçur (Bingöl) lân cận cũng quy về Ottoman trong cùng tiến trình.", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Chinh phục pháo đài Kemah từ tay người Safavid", "73fd8671"], "d": ["Trú đông tại Amasya trên đường về từ Chaldiran, Sultan Selim I giao cho Bıyıklı Mehmed Pasha việc chinh phục pháo đài kiên cố Kemah án ngữ điểm vượt sông Euphrates. Sau cuộc vây hãm có sultan đích thân tham dự, pháo đài được lấy khỏi tay Safavid và cánh cửa vào Đông Anatolia được mở ra. Cuộc chinh phục này là bước đi cụ thể đầu tiên biến chiến thắng Chaldiran thành thành quả lãnh thổ lâu dài.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Chiến thắng Turnadağ — tiểu quốc Dulkadir lệ thuộc Ottoman", "fd879145"], "d": ["Quân Ottoman đánh bại Alaüddevle Bozkurt, bey Dulkadir, kẻ tỏ thái độ nước đôi trong chiến dịch Chaldiran, tại địa điểm Ördekli giữa Göksun và Andırın; Alaüddevle bị giết trong trận này. Tiểu quốc không bị sáp nhập vào thời điểm đó: sau Alaüddevle, Sultan Selim I đưa Şehsuvaroğlu Ali Bey lên đứng đầu tiểu quốc Dulkadir, và xứ sở lấy Maraş-Elbistan làm trung tâm tiếp tục tồn tại như một tiểu quốc lệ thuộc Ottoman. Vùng đệm trên biên giới Mamluk như vậy nằm dưới sự kiểm soát của Ottoman, mở đường cho chiến dịch Ai Cập hai năm sau; việc sáp nhập sẽ diễn ra sau khi Ali Bey bị giết.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Chinh phục Amid (Diyarbekir) và lập tỉnh beylerbey Diyarbekir", "a6867d5b"], "d": ["Sau khi Idris Bitlisi lôi kéo được các thủ lĩnh người Kurd Sunni trong vùng về phía Ottoman, quân Safavid không chịu nổi cuộc vây hãm kéo dài, và chìa khóa Amid được trao cho Bıyıklı Mehmed Pasha. Thành phố được lập làm trung tâm của tỉnh beylerbey Diyarbekir mới thành lập. Như vậy, hạt nhân hành chính của Thượng Lưỡng Hà về tay Ottoman.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Chinh phục Harput — mở đường đến Diyarbekir", "564eb269"], "d": ["Hüsrev Pasha, beylerbey Karaman, lên đường giải vây Diyarbekir (đã lấy được sau Chaldiran) khỏi quân Safavid, sau ba ngày vây hãm đã lấy được pháo đài Harput, nơi vùng phụ cận trước đó đã bị Çerkez Hüseyin Bey chiếm. Như vậy con đường đến Diyarbekir ở phía đông sông Euphrates được bảo đảm.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Trận Koçhisar (Kızıltepe) — Kara Khan bại trận", "9ea9e843"], "d": ["Quân Ottoman do Bıyıklı Mehmed Pasha chỉ huy đã đánh bại tổng trấn Safavid Kara Khan trong một trận dã chiến kéo dài suốt ngày tại địa điểm Koruk, trên đồng hoang Dede Garkın gần Koçhisar; thủ cấp của Kara Khan được gửi về doanh trại sultan. Sau đó quân Ottoman tiến vào thành Mardin nhưng chỉ ở lại vài ngày rồi rút; pháo đài Mardin do quân trấn thủ Safavid nắm giữ mãi một năm sau mới đầu hàng. Chiến thắng này giúp Selim bảo đảm biên giới phía nam và hướng đến chiến dịch Ai Cập. Các nơi khác được sáp nhập vào cùng ngày: Palu, Çemişgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Sultan Selim I rời Istanbul mở chiến dịch Ai Cập", "ac258b4b"], "d": ["Sultan Selim I rời Istanbul với vẻ ngoài là chuẩn bị một chiến dịch phía đông mới chống người Safavid, đi qua Akşehir rồi hướng xuống phía nam. Việc sultan Mamluk Qansuh al-Ghuri liên lạc với Shah Ismail và đe dọa sườn phía đông của Ottoman sẽ sớm làm thay đổi mục tiêu. Chiến dịch là khởi đầu của cuộc hành quân lớn kéo dài hai năm, biến Ottoman thành một đế quốc Trung Đông.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Chiếm Zabid: lần đầu tiên thủy thủ Ottoman tiến vào Biển Đỏ", "38740e0c"], "d": ["Trước sức ép của Bồ Đào Nha ở Ấn Độ Dương, theo yêu cầu của sultan Mamluk Qansuh al-Ghuri, hai thủy thủ gốc Ottoman là Hüseyin Bey và Selman Reis được phái ra Biển Đỏ và cùng hạm đội của mình chiếm Zabid. Cuộc hành quân này, khi đó vẫn tiến hành trong biên chế Mamluk, là sự hiện diện thực tế đầu tiên của hải quân Ottoman trên tuyến Biển Đỏ - Ấn Độ. Một năm sau, khi Ai Cập về tay Ottoman, chính hạm đội ấy sẽ trực thuộc Istanbul.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Chính thức tuyên bố mục tiêu chiến dịch là người Mamluk và Aleppo", "689e310d"], "d": ["Khi Qansuh al-Ghuri thỏa thuận với người Safavid rồi đưa quân đến Aleppo, Sultan Selim I công khai tuyên bố mục tiêu của chiến dịch là sultan Mamluk và Aleppo. Như vậy, sự kình địch ngấm ngầm nhiều năm giữa hai nhà nước Sunni đã biến thành chiến tranh công khai. Lời tuyên bố này khởi đầu cuộc đếm ngược bốn tuần dẫn đến Marj Dabiq.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Cuộc vây hãm Aden thất bại: nỗ lực đầu tiên ở Biển Đỏ chống Bồ Đào Nha", "8ffd46f2"], "d": ["Để chiếm Aden, cửa ngõ của Biển Đỏ ra Ấn Độ Dương, Selman Reis và Hüseyin Bey tiến hành vây hãm tám ngày, nhưng phải rút lui trước hệ thống phòng thủ vững chắc của thành. Việc không lấy được Aden sẽ làm trì trệ chiến lược phương nam chống Bồ Đào Nha trong nhiều năm. Nỗ lực này là thử thách đầu tiên của Ottoman trong chính sách đại dương.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Tiểu quốc Ramazan thần phục Ottoman", "cfaa3754"], "d": ["Trong đợt phong cấp sau chiến thắng Marj Dabiq, tiểu quốc Ramazan lấy Adana làm trung tâm được giao cho Mahmud Bey và đặt dưới chủ quyền Ottoman. Thoát khỏi địa vị lệ thuộc Mamluk, tiểu quốc không bị xóa bỏ mà được để lại cho gia tộc theo quy chế 'ocaklık' (lãnh địa cha truyền con nối); nhà Ramazan tiếp tục cai quản Cilicia với tư cách sanjak-bey Ottoman. Chế độ đặc quyền này kéo dài đến năm 1608, khi Pir Mansur từ bỏ tiểu quốc. Các nơi khác được sáp nhập vào cùng ngày: Malatya, Tarsus, Mosul, Antep.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Aleppo, Raqqa và Deir ez-Zor thuộc chủ quyền Ottoman", "2088eb6a"], "d": ["Bốn ngày sau Marj Dabiq, Sultan Selim I vào Aleppo mà không gặp kháng cự, và khutbah trong các thánh đường của thành được đọc nhân danh ông. Việc Aleppo, được coi là thủ phủ thương mại và hành chính của Syria, thất thủ nhanh đến vậy cho thấy quyền uy Mamluk trong vùng đã sụp đổ. Việc chiếm thành lập tức mở đường đến Damascus và từ đó đến Ai Cập. Các nơi khác được sáp nhập vào cùng ngày: Antioch, Raqqa, Deir ez-Zor.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Cuộc gặp với khalip Abbasid al-Mutawakkil III tại Gökmeydan, Aleppo", "22979f42"], "d": ["Al-Mutawakkil III, khalip Abbasid ở Cairo, bị bắt làm tù binh cùng quân Mamluk tại Marj Dabiq, được đưa đến trước mặt sultan tại Gökmeydan ở Aleppo, và Sultan Selim I tỏ lòng hết sức kính trọng ông. Chức khalip Cairo, từ năm 1261 chỉ là ngôi vị tượng trưng dưới bóng các sultan Mamluk, qua cuộc gặp này trên thực tế chuyển sang sự bảo hộ của Ottoman. Sau đó, khalip được đưa cùng sultan về Istanbul.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Tripoli (Syria) và Hama thuộc quyền cai quản của Ottoman", "a1e19a79"], "d": ["Sau Aleppo và Hama, Tripoli trên bờ biển Syria cũng chuyển sang quyền cai quản của Ottoman mà không kháng cự. Là một trong những hải cảng nhộn nhịp nhất Đông Địa Trung Hải, thành phố này là cửa ngõ ra biển của Damascus và trung tâm buôn bán tơ lụa cùng đường. Khi chiếm được nó, toàn bộ dải ven biển của Bilad al-Sham đã đổi chủ.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Damascus thuộc chủ quyền Ottoman", "2b844d91"], "d": ["Được mở đường nhờ Hama và Homs đầu hàng sau Aleppo, ngày 27 tháng 9 Sultan Selim I đến trước Damascus; ông không vào thành ngay mà dựng lều ở địa điểm Mastaba bên ngoài, và đến ngày thứ mười hai sau khi đến mới long trọng vào thành. Lưu lại Damascus khá lâu, ông thiết lập trật tự hành chính cho Syria và cho xây lăng mộ Muhyiddin Ibn al-'Arabi. Như vậy toàn bộ Bilad al-Sham đã thoát khỏi quyền cai quản của Mamluk. Các nơi khác được sáp nhập vào cùng ngày: Beirut.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Tuman Bay được tuyên bố làm sultan Mamluk ở Cairo", "6020d90d"], "d": ["Sau khi Qansuh al-Ghuri chết tại Marj Dabiq, các emir Mamluk đưa Tuman Bay, người sẽ là sultan cuối cùng của nhà nước, lên ngai. Vị sultan mới gốc Circassia tiếp nhận một nhà nước đã mất Syria, ngân khố cạn kiệt và thiếu hỏa khí. Dẫu vậy, ông sẽ dựng phòng tuyến trước Cairo và tổ chức cuộc kháng cự cuối cùng chống bước tiến Ottoman.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Trận Gaza (Khan Yunis): Janbirdi al-Ghazali bại trận", "9f1eb8cb"], "d": ["Sultan Selim I phái đại tể tướng Hadım Sinan Pasha cùng đội tiên phong bốn nghìn người đến Gaza. Janbirdi al-Ghazali, được Tuman Bay đặt làm phó vương Damascus, tìm cách chặn tiền quân Ottoman trên tuyến Gaza - Khan Yunis, nhưng đại bại và chạy sang Ai Cập. Với sự tan rã của lực lượng đệm Mamluk cuối cùng ở Palestine, con đường đến sa mạc Sinai hoàn toàn rộng mở.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["Phía đông sông Jordan: Amman thuộc quyền cai quản của Ottoman", "9db62667"], "d": ["Khi quân Ottoman chuẩn bị cho chiến dịch Ai Cập sau trận Gaza tiến xuống phía nam, Amman ở phía đông sông Jordan cũng thuộc quyền cai quản của Ottoman. Còn các thành phố ven biển và nội địa của Palestine (Jaffa, Nablus, Sidon, Acre, Jerusalem) đã đổi chủ từ mùa thu năm 1516, sau trận Marj Dabiq. Suốt bốn thế kỷ, các thành phố này được cai quản như những sanjak của tỉnh Damascus.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Sultan Selim I đến Jerusalem", "66d7bfad"], "d": ["Jerusalem, thành phố đã về tay Ottoman sau Marj Dabiq mà không kháng cự, được Sultan Selim I đến thăm cùng các đại thần và quân lính sau trận Gaza. Sultan viếng Mái vòm Đá (Qubbat al-Sakhra) và Thánh đường al-Aqsa, khẳng định địa vị thiêng liêng của thành phố. Từ thời điểm này đến tháng 12 năm 1917, tròn bốn thế kỷ, Jerusalem sẽ nằm dưới quyền cai quản của Ottoman.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Sultan Selim I vào Gaza và hướng về sa mạc Sinai", "2106bfc7"], "d": ["Sau khi Janbirdi al-Ghazali bại trận tại Khan Yunis (21 tháng 12 năm 1516), Gaza nằm trong tay đội tiên phong. Ngày 2 tháng 1 năm 1517, sultan vào Gaza, gặp Sinan Pasha chỉ huy tiền quân, và quân đội hoàn tất những chuẩn bị cuối cùng để sang Ai Cập. Trong sa mạc khô cằn Qatya (Sinai) trải từ Gaza đến Salihiya, họ sẽ phải đi tám chặng đường, chở nước bằng lạc đà. Cuộc vượt này là giai đoạn nhiều rủi ro nhất và khó khăn nhất về hậu cần của chiến dịch.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Chiếm Suez — cửa ngõ ra Biển Đỏ", "05f3324e"], "d": ["Khi quân Ottoman tiến vào Cairo sau chiến thắng Ridaniya, Suez ở đầu phía bắc Biển Đỏ cũng thuộc quyền cai quản của Ottoman. Cảng kiêm xưởng đóng tàu này, nơi người Mamluk từng xuất hạm đội ra Ấn Độ Dương, trở thành căn cứ cho chính sách phương nam nhằm chống Bồ Đào Nha. Suez là cửa phía bắc của tuyến mà ba thế kỷ sau kênh đào sẽ được khai mở.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Quân Ottoman lần đầu tiến vào Cairo", "0a3f4f4d"], "d": ["Một ngày sau chiến thắng Ridaniya, quân đội Ottoman được phép vào Cairo, và ngày 24 tháng 1 các đơn vị đóng trong thành. Nhưng việc vào thành này chưa có nghĩa là kiểm soát hoàn toàn thành phố; Tuman Bay đã rút lên Thượng Ai Cập, sức kháng cự Mamluk chưa bị bẻ gãy. Cuộc chinh phục Cairo không hoàn tất trong một ngày mà trong một quá trình đẫm máu kéo dài nhiều tuần.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Tuman Bay đột kích Cairo và ba ngày giao chiến trên đường phố", "b83b6ce6"], "d": ["Đã rút lên Thượng Ai Cập, đêm 27-28 tháng 1, Tuman Bay cùng khoảng bảy nghìn người đột ngột vào Cairo, phát động kháng chiến trong thành và đẩy quân Ottoman vào tình thế cực kỳ khó khăn. Trong ba ngày giao chiến ác liệt trên đường phố, người Mamluk tạm thời giữ được phần lớn thành phố. Cuộc kháng cự chỉ bị bẻ gãy khi pháo binh Ottoman và viện binh vào cuộc.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Janbirdi al-Ghazali vào phục vụ Ottoman", "a94ea459"], "d": ["Sau trận Ridaniya, cựu emir Mamluk Janbirdi al-Ghazali, đã rút về Salihiya, xin sultan tha mạng. Nghĩ rằng ông ta sẽ hữu ích trong việc lập lại trật tự ở Ai Cập và Syria, Sultan Selim I nhận ông vào phục vụ. Lựa chọn này là ví dụ lớn đầu tiên cho chính sách của Ottoman đưa đội ngũ Mamluk vào hệ thống thay vì thanh trừng.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Sultan Selim I long trọng vào Cairo và khutbah được đọc", "6d98080c"], "d": ["Sau khi các cuộc giao chiến trên đường phố bị dẹp, ngày 15 tháng 2 năm 1517 sultan vào Cairo trong một nghi lễ vô cùng huy hoàng, và khutbah được đọc nhân danh ông trong các thánh đường. Việc đọc khutbah tại Cairo nhân danh sultan Ottoman là lời tuyên cáo rằng quyền thống trị Mamluk kéo dài từ năm 1250 đã chấm dứt về pháp lý. Mốc này được coi là thời điểm hoàn tất mang tính biểu tượng của cuộc chinh phục Ai Cập trên thực tế.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Sultan Mamluk cuối cùng Tuman Bay bị bắt tại Tarruja", "7058e6ad"], "d": ["Rời Cairo rồi ẩn náu ở châu thổ sông Nile, Tuman Bay bị chính những người Bedouin cho ông trú ẩn chỉ điểm và bị bắt tại vùng Tarruja. Việc ông bị bắt đã xóa bỏ trung tâm có tổ chức của cuộc kháng cự Mamluk. Vị sultan cuối cùng sau đó bị Ottoman giam giữ mười bốn ngày.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Tuman Bay bị treo cổ tại cổng Bab Zuwayla và Nhà nước Mamluk cáo chung", "ad9820be"], "d": ["Mười bốn ngày sau khi bị bắt, Tuman Bay bị treo cổ tại Bab Zuwayla, cổng thành nổi tiếng của Cairo; thi hài ông sau đó được an táng trong madrasa do chú ông xây dựng. Như vậy Nhà nước Mamluk, thống trị Ai Cập và Syria từ năm 1250, đã chính thức đi vào lịch sử. Khi sức kháng cự bị bẻ gãy, các thành phố ở Thượng Ai Cập (Sa'id) như Asyut và Aswan cũng thuộc quyền cai quản của Ottoman.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Hạm đội Bồ Đào Nha tấn công Jeddah và cuộc phòng thủ của Selman Reis", "52322cf5"], "d": ["Hạm đội Bồ Đào Nha gồm khoảng ba mươi chiến thuyền galley và galleon tấn công Jeddah; Selman Reis chỉ huy phòng thủ thành, ngăn địch đổ bộ và đánh chìm vài tàu Bồ Đào Nha. Cuộc phòng thủ này đã ngăn hải cảng của Mecca, và qua đó con đường hành hương, rơi vào tay một nhà nước Cơ đốc giáo. Vài tháng sau, khi Hejaz tuyên thệ trung thành (bay'a), Jeddah chính thức thuộc quyền cai quản của Ottoman.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Hạm đội tiếp nhận Alexandria — hoàn tất cuộc chinh phục Ai Cập", "386878fe"], "d": ["Tròn bốn tháng sau Ridaniya, ba mươi sáu ngày sau khi Tuman Bay bị hành quyết, khi hạm đội Ottoman do Cafer Bey chỉ huy đến cảng, Alexandria thuộc quyền cai quản của Ottoman; các cảng ở châu thổ như Rashid và Damietta cũng quy thuộc trong cùng quá trình. Việc hải cảng lớn này của Ai Cập trên Địa Trung Hải được tiếp nhận nhiều tháng sau khi Cairo thất thủ, và từ phía biển chứ không phải trên bộ, cho thấy rõ cuộc chinh phục không hoàn tất bằng một trận đánh duy nhất mà theo từng vùng. Từ đó Alexandria trở thành hải cảng sống còn nối Istanbul với Cairo. Các nơi khác được sáp nhập vào cùng ngày: Rashid (Rosetta).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Hejaz sáp nhập không giao chiến: Abu Numayy, con trai Sharif Mecca, tuyên thệ trung thành", "c13b98c7"], "d": ["Ban đầu Sultan Selim I tính chuyện đưa quân chiếm Mecca và vùng phụ cận, nhưng sau khi Emir Mecca là Sharif Barakat tỏ ý quy phục, ông từ bỏ ý định đó. Con trai mười hai tuổi của Barakat là Abu Numayy mang lễ vật của cha và chìa khóa Mecca đến Cairo và được sultan tiếp kiến. Như vậy, Hejaz không sáp nhập vào Ottoman như hệ quả tự động của trận Ridaniya, mà năm tháng rưỡi sau đó, không một phát súng, một cách hòa bình và bằng lời tuyên thệ trung thành (bay'a). Các nơi khác được sáp nhập vào cùng ngày: Taif. Các khu định cư khác bị mất vào cùng ngày: Khurmah (phía đông Taif), Rabigh, Badr.", "74c58fb7"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Nhận danh hiệu Khadim al-Haramayn và khutbah tại Medina", "63b32b59"], "d": ["Sau lần tiếp kiến phái đoàn Mecca thứ hai, Sultan Selim I chính thức nhận lãnh việc bảo hộ hai thánh địa và bắt đầu dùng danh hiệu 'người phụng sự hai thánh địa cao quý' (khadim al-Haramayn al-Sharifayn). Sharif Barakat mặc áo ban thưởng (hil'at) được gửi đến và cho đọc khutbah nhân danh sultan; sau khi phái đoàn Medina cũng đến Istanbul, tước vị emir của Barakat được phê chuẩn bằng chiếu chỉ. Sultan gửi cho dân hai thánh địa hai trăm nghìn đồng vàng cùng nhiều lương thực, mở đầu truyền thống surre (lễ vật hành hương) lặp lại hằng năm. Các nơi khác được sáp nhập vào cùng ngày: Yanbu, Tabuk.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Selman Reis vào phục vụ Ottoman và việc tiếp quản chính sách Biển Đỏ", "771da99a"], "d": ["Selman Reis, người đã bảo vệ Jeddah trước quân Bồ Đào Nha, đến Cairo và yết kiến Sultan Selim I; tuy bị giữ lại một thời gian, năm 1519 ông được triệu về Istanbul và cam kết chuẩn bị ba mươi chiến thuyền galley cùng vài chiếc thuyền galliot để chống mối đe dọa Bồ Đào Nha. Cuộc gặp này khởi đầu việc tiếp quản di sản Mamluk về chính sách Biển Đỏ và Ấn Độ Dương, đặt nó trực thuộc Istanbul. Ottoman giờ đây không chỉ là một nhà nước Địa Trung Hải mà còn là thế lực theo đuổi chính sách đại dương.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Sultan Selim I rời Cairo và Khayr Bey làm beylerbey", "8cd4fb23"], "d": ["Sau khoảng tám tháng ở Ai Cập để thiết lập trật tự hành chính, tài chính và quân sự, Sultan Selim I rời Cairo; Khayr Bey, cựu phó vương Aleppo, người đã rút cánh trái khỏi trận Marj Dabiq khiến người Mamluk thất bại nhanh hơn, bắt đầu cai trị từ Thành Cairo (Qal'at al-Jabal) với tư cách beylerbey Ottoman đầu tiên của Ai Cập. Việc chọn một tổng đốc gốc Mamluk là chính sách chuyển tiếp có chủ ý, nhằm giúp chính quyền mới không trở nên xa lạ với dân bản địa. Trên đường về, sultan còn đưa theo đến Istanbul khalip Abbasid cuối cùng al-Mutawakkil III cùng những nghệ nhân và học giả ưu tú của Ai Cập.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Chức khalip Abbasid ở Cairo cáo chung — truyền thuyết về 'lễ chuyển giao'", "1d357640"], "d": ["Khi chiếm Ai Cập, Sultan Selim I đưa theo về Istanbul vị khalip cuối cùng al-Mutawakkil III, bị bắt làm tù binh tại Marj Dabiq; chức khalip Abbasid ở Cairo, tồn tại không có thực quyền dưới bóng các sultan Mamluk từ năm 1261, như vậy đã chấm dứt. Trong khi đó, truyền thuyết nổi tiếng rằng chức khalip đã được chuyển giao cho Selim trong một nghi lễ chính thức tại Hagia Sophia lần đầu xuất hiện trong tác phẩm của d'Ohsson vào cuối thế kỷ 18 và không có trong bất cứ nguồn nào thời Selim. Bách khoa toàn thư Hồi giáo TDV coi truyền thuyết này là bịa đặt vì không có nguồn gốc nào ghi lại nghi lễ; nhưng cũng ghi nhận rằng theo luật Hồi giáo, việc chuyển giao chức khalip không cần đến một lễ chuyển giao như vậy.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Erzurum sáp nhập vào Ottoman — ảnh hưởng Safavid ở Đông Anatolia bị bẻ gãy", "78d1be02"], "d": ["Tuy ảnh hưởng Ottoman trong vùng tăng lên sau chiến thắng Chaldiran (1514), việc chiếm hoàn toàn Erzurum phải chờ đến khi ảnh hưởng Iran bị bẻ gãy; chỉ sau chiến dịch Ai Cập, vào những năm 1518-19, thành phố mới sáp nhập vào Ottoman. Erzurum thuộc chủ quyền Safavid từ năm 1502, khi Shah Ismail chấm dứt tiểu quốc Aq Qoyunlu; thời kỳ mười sáu năm này như vậy khép lại. Năm 1534, trong chiến dịch hai Iraq (Irakeyn), tỉnh beylerbey Erzurum sẽ được thành lập. Trong khoảng 1518-1519, cùng với vùng Erzurum, Aşkale cũng thuộc quyền cai quản của Ottoman (ngày chưa được xác minh).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Khởi đầu các cuộc nổi loạn Celali: cuộc khởi nghĩa của Sheikh Celal ở Bozok", "99bd8a99"], "d": ["Ở vùng Bozok, một người tên Sheikh Celal tự xưng là Mahdi và nổi dậy quanh Tokat; tuy cuộc nổi loạn bị dẹp, tên ông suốt một thế kỷ đã trở thành tên gọi cho mọi phong trào cướp bóc và khởi nghĩa ở Anatolia. Phong trào Celali, đến cuối thế kỷ 16 kết hợp với sự tan rã của chế độ timar và áp lực dân số, đã trở thành vấn đề an ninh nội địa dai dẳng nhất của đế quốc. Các cuộc nổi loạn dẫn đến những đợt di cư hàng loạt ở Anatolia, gọi là 'cuộc đại tẩu tán'.", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Algiers sáp nhập vào Nhà nước Ottoman", "b8eba4c1"], "d": ["Hayreddin Reis, đang kháng cự sức ép Tây Ban Nha ở Bắc Phi, để trụ vững đã cầu đến Istanbul, dâng Algiers cho sultan, và khutbah được đọc nhân danh Sultan Selim I. Như vậy Algiers chính thức sáp nhập vào đất Ottoman; Hayreddin được gửi quân lính và đại bác cùng danh hiệu beylerbey. Việc quy thuộc này đặt nền móng cho quyền bá chủ trên biển của Ottoman ở Tây Địa Trung Hải kéo dài nhiều thế kỷ. Các nơi khác được sáp nhập vào cùng ngày: Constantine, Cherchell, Medea (Titteri), Setif.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Sultan Selim I qua đời tại Çorlu", "9fe83744"], "d": ["Selim I, người trong tám năm đã mở rộng lãnh thổ nhà nước hơn gấp đôi, rời Istanbul ngày 18 tháng 7 năm 1520 cho một chiến dịch mới; do một khối u lớn mọc trên lưng, ông không đi quá được Çorlu. Dù thầy thuốc can thiệp, bệnh tình ngày càng nặng, và sau hai tháng chữa trị vô vọng, ông qua đời tại đây ngày 8-9 tháng Shawwal năm 926 (21-22 tháng 9 năm 1520). Qua các trận Chaldiran, Marj Dabiq và Ridaniya, ông đã chặn đứng Iran, xóa sổ Nhà nước Mamluk, đưa chức khalip và vai trò bảo hộ hai thánh địa về Ottoman. Ông để lại một con trai duy nhất: Süleyman.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["Đảo Nikaria (Ikaria) thuộc quyền cai quản của Ottoman", "6afa972b"], "d": ["Nikaria, nằm giữa Samos và Chios, từ năm 1481 đến 1521 thuộc quyền cai quản của Hiệp sĩ Thánh Gioan ở Rhodes; thời kỳ Ottoman đầu tiên trên đảo bắt đầu năm 1522 và kéo dài đến năm 1822. Trong thời kỳ này, kaymakam chịu trách nhiệm thu và nộp thuế; như ở các đảo Aegea khác, hội đồng kỳ lão địa phương (demogerontia) vẫn tồn tại và đôi khi xung đột với chính quyền Ottoman.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["Sáp nhập xứ Dulkadir — tỉnh eyalet Dulkadir đóng tại Maraş", "595c3c30"], "d": ["Xứ Dulkadir, tồn tại như một công quốc lệ thuộc Ottoman sau thảm bại Turnadağ năm 1515, đã được sáp nhập trực tiếp vào lãnh thổ Ottoman và tổ chức thành tỉnh eyalet đóng tại Maraş sau khi Şehsuvaroğlu Ali Bey cùng các con bị giết ở Artukova. Vùng Bozok của công quốc được gắn vào quyền cai quản của Ottoman thành một sanjak riêng. Như vậy thời kỳ Dulkadir gần hai thế kỷ của Maraş, Elbistan, Göksun, Gürün, Zamantı và Darende khép lại; công quốc đệm ở biên giới Mamluk hoàn toàn biến mất.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["Chinh phục Knin", "a46d3117"], "d": ["Qua các cuộc tập kích của sanjakbey Bosnia Gazi Hüsrev Bey trong các năm Hijri 927–928 (1521–1522), một loạt pháo đài của Venice, đứng đầu là Knin, Skradin và Ostrovica, đã chuyển sang quyền cai quản của Ottoman; biên giới được đẩy ra phía bên kia dãy núi thứ hai. Chuỗi chinh phục này đặt nền móng cho sanjak Dalmatia, sẽ được hoàn tất mười lăm năm sau khi chiếm Klis.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["Các hiệp sĩ rút lui: chuyển giao Bodrum, Kos và quần đảo Mười Hai Đảo", "ea01666e"], "d": ["Theo điều khoản đầu hàng của Rhodes, Hiệp sĩ Thánh Gioan không chỉ bỏ trung tâm hòn đảo mà còn mọi vị trí họ đã nắm giữ suốt hai trăm năm. Pháo đài Bodrum (Saint Pierre) trên bờ Anatolia cùng các đảo Kos, Kalymnos và Leros như vậy chuyển sang quyền cai quản của Ottoman mà không có giao tranh. Với cuộc chuyển giao hoàn tất hai tuần sau khi Rhodes thất thủ, sự hiện diện của người Latinh ở góc đông nam biển Aegea chấm dứt hoàn toàn.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Cuộc nổi loạn của kẻ phản bội Ahmed Pasha ở Ai Cập", "b18bb805"], "d": ["Ahmed Pasha, đang mong chức đại tể tướng mà bị cử làm tổng đốc Ai Cập, tự xưng 'al-Malik al-Mansur Sultan Ahmed' ở Cairo và tuyên bố độc lập. Cuộc nổi loạn nhanh chóng bị dẹp và viên pasha bị giết, nhưng sự kiện cho thấy sự mong manh của quyền kiểm soát trung ương tại tỉnh giàu nhất đế quốc. Sau đó, Ibrahim Pasha sang Ai Cập và cho soạn Bộ luật Ai Cập nổi tiếng, tổ chức lại nền cai trị tỉnh này.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["Sáp nhập miền bắc Bosnia: Jajce và Banja Luka", "8ec86cfa"], "d": ["Khi phòng tuyến Hungary sụp đổ sau Mohács, sanjakbey Bosnia Gazi Hüsrev Bey tiến theo thung lũng sông Vrbas và chiếm những pháo đài Bosnia cuối cùng còn trong tay vương quốc Hungary. Với việc Jajce và Banja Luka thất thủ, tỉnh Bosnia vươn đến sông Sava ở phía bắc và mặt trận Croatia ra đời. Banja Luka chẳng bao lâu trở thành trung tâm thứ hai của tỉnh.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Chiếm Buda và trao cho Zápolya", "fba4f89b"], "d": ["Trên đường chinh phạt Vienna, quân đội Ottoman vây và chiếm lại Buda, vốn đã rơi vào tay Ferdinand, rồi giao thành cho vua Hungary được Ottoman bảo hộ là János Szapolyai. Như vậy, trong cuộc cạnh tranh Habsburg - Ottoman đối với Hungary, một mô hình vương quốc chư hầu đệm được thiết lập. Trật tự này kéo dài đến năm 1541; sau khi Zápolya qua đời, Buda trở thành tỉnh Ottoman trực thuộc.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["Süleyman Lập pháp mở chiến dịch Đức — thách thức Charles V", "7c3d7055"], "d": ["Sau khi cuộc vây hãm Vienna không có kết quả và Ferdinand lại vây Buda, lần này sultan rời Istanbul để trực tiếp kéo hoàng đế Charles V vào một trận dã chiến. Quân đội sẽ bị sự kháng cự của pháo đài nhỏ Kőszeg (Güns) cầm chân vào tháng 8, và khi hoàng đế không ra giao chiến, chiến dịch chỉ giới hạn ở các cuộc đột kích. Chiến dịch dọn đường cho hòa ước đầu tiên ký với nhà Habsburg năm sau.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Chiến dịch Đức và cuộc vây hãm Kőszeg (Güns)", "8aec937a"], "d": ["Nhằm buộc Charles V giao chiến trên chiến trường, Süleyman Lập pháp đưa quân tiến vào Áo; pháo đài nhỏ Kőszeg kháng cự hai mươi lăm ngày, làm chậm bước tiến của quân đội. Khi hoàng đế không ra giao chiến, quân kỵ đột kích (akıncı) đánh phá vùng quanh Vienna, và do mùa đã muộn, quân đội quay về. Chiến dịch không đem lại đất đai, nhưng đã đưa nhà Habsburg vào bàn đàm phán, đặt nền móng cho hòa ước năm sau.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Hiệp ước Istanbul — hòa bình đầu tiên với nhà Habsburg", "b085767a"], "d": ["Tiếp sứ giả Cornelius của Ferdinand, sultan chấp thuận đình chiến, và văn bản hòa bình chính thức đầu tiên giữa Ottoman và Áo ra đời. Theo hiệp ước, Ferdinand đồng ý nộp cống hằng năm cho phần đất Hungary ông đang nắm giữ, còn đại công tước Áo trong nghi thức được coi là ngang hàng với đại tể tướng. Địa vị bất bình đẳng này là biểu hiện rõ ràng của tuyên bố ưu thế trong ngoại giao Ottoman thế kỷ 16.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["Chiếm Kars và mở biên giới đông bắc", "742e3101"], "d": ["Khi đạo tiên phong của Chiến dịch Hai xứ Iraq hướng từ Erzurum về phía đông, pháo đài Kars, nằm trong tay công quốc atabeg Gruzia và hoang phế từ thời Timur, đã được tiếp nhận mà không gặp kháng cự. Vì nắm giữ lối đi giữa vòng cung sông Aras và Çıldır, thành phố được coi là chìa khóa của cửa ngõ phía bắc mở sang Iran. Thành quả này là mắt xích đầu tiên của tỉnh beylerbeylik Kars, được lập ba mươi năm sau, và của phòng tuyến Kavkaz.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["Lần đầu tiến vào Tabriz — mở đầu Chiến dịch Hai xứ Iraq", "cf7ed4e3"], "d": ["İbrahim Pasha, đi trước với tư cách tổng tư lệnh, đã tiến vào kinh đô Safavid là Tabriz mà không gặp kháng cự, do Shah Tahmasp tránh giao chiến trên dã ngoại và rút vào sâu trong nội địa. Kanunî cũng đến thành phố vào tháng 9; tuy nhiên, vì mùa đông ập đến và đường tiếp tế quá dài, quân đội chuyển hướng về Baghdad, và Tabriz không giữ được lâu. Thành phố, bị chiếm lần thứ hai sau Chaldiran, là nơi người Ottoman học được rằng ở phía đông, chiếm thì dễ mà giữ thì khó.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Barbaros chinh phục Tunis", "d8754216"], "d": ["Đại đô đốc Barbaros Hayreddin Pasha, sau khi dùng hạm đội đánh phá bờ biển Ý, hướng đến Tunis, đuổi quân vương Hafsid là Mulay Hasan và vào thành. Việc chiếm Tunis, nơi có vị trí khống chế eo biển Sicilia, lập tức nghiêng cán cân quyền lực ở Tây Địa Trung Hải về phía Ottoman. Tuy nhiên quyền thống trị này không lâu bền; năm sau, Charles V sẽ đáp trả bằng một hạm đội lớn.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Mất Tunis vào tay Charles V", "a691f0f8"], "d": ["Trong một cuộc viễn chinh lớn được hạm đội Genoa và Giáo hoàng hỗ trợ, sau khi hạ La Goulette (Halk al-Wadi), Charles V chiếm Tunis và đưa Mulay Hasan trở lại ngai dưới sự bảo hộ của Tây Ban Nha. Một đồn trú Tây Ban Nha được đặt trong thành, tạm thời chặn bước tiến của Ottoman ở Trung Địa Trung Hải. Cuộc chinh phục dứt khoát Tunis chỉ có thể thực hiện bốn mươi năm sau, năm 1574.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Chiến dịch dọc sông Sava của Gazi Hüsrev Bey: Bosanski Brod và Jasenovac", "3740ec83"], "d": ["Sau khi Jajce và Banja Luka bị chiếm năm 1528, các pháo đài dọc sông Sava vẫn thêm một thời gian ở biên giới Croatia – Slavonia thuộc vương miện Habsburg. Gazi Hüsrev Bey, lần thứ ba làm sanjakbey Bosnia vào năm 1536, ngay trong năm đó vừa chiếm Požega và vùng phụ cận, vừa đưa các pháo đài Brod và Jasenovac bên bờ Sava vào quyền cai quản của Ottoman. Như vậy biên giới phía bắc của Bosnia vươn đến sông Sava; vùng này được hoàn tất hai năm sau khi chiếm Dubica.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Makbul Ibrahim Pasha bị hành quyết", "348aa7b8"], "d": ["Ibrahim Pasha, làm đại tể tướng mười ba năm, bạn thân nhất của Süleyman Lập pháp và trên thực tế là nhân vật thứ hai của nhà nước, đã bị thắt cổ trong cung điện nơi ông được mời đến dùng bữa xả chay (iftar), mà không được nêu bất cứ lý do nào. Thái độ của ông trong chiến dịch hai Iraq, việc ông dùng danh hiệu 'serasker sultan' và các thế cân bằng trong cung được coi là có tác động đến cái chết của ông. Cuộc hành quyết là bước ngoặt cho thấy trong chính quyền trung ương Ottoman, đại tể tướng không hề có sự an toàn tuyệt đối.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Chinh phục pháo đài Klis và lập sanjak Dalmatia", "6ffd4ebf"], "d": ["Murad Bey, người Croatia cải đạo, kethüda (phụ tá) của Gazi Husrev Bey, đã lấy từ tay Venezia pháo đài chiến lược Klis ngay phía bắc Split. Ngay sau cuộc chinh phục, Klis được lập làm trung tâm của một sanjak và quận (kaza) mới bao gồm vùng phụ cận; ranh giới sanjak này phần lớn vạch ra khung của Croatia thuộc Ottoman. Đến mười lăm năm sau Knin, cuộc chinh phục này hoàn chỉnh khung hành chính của vùng nội địa Dalmatia.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Vây hãm Corfu và chiến tranh với Venezia", "11af95bd"], "d": ["Sau chiến dịch Apulia, quân đội Ottoman đổ bộ lên Corfu và vây pháo đài vững chắc của Venezia trên đảo. Do địa thế hiểm trở của pháo đài, tổn thất nặng nề và điều kiện mùa vụ, ngày 6 tháng 9 vòng vây được dỡ bỏ và quân rút đi. Tuy cuộc vây hãm không có kết quả, chiến tranh nổ ra với Venezia đã kết thúc bằng việc nhiều đảo ở biển Aegea và Adriatic được sáp nhập vào Ottoman và chiến thắng Preveza năm sau.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Chiến dịch Aegea của Barbarossa: chiếm các đảo do Venice trực tiếp cai quản", "1b32ed96"], "d": ["Hạm đội trở về sau cuộc vây hãm Corfu, lợi dụng việc chiến tranh đã được tuyên với Venice, lần lượt tiếp nhận các đảo ở biển Aegea trực thuộc Venice chứ không thuộc công quốc. Aegina bị chiếm sau sự kháng cự quyết liệt; Astypalaia thuộc dòng họ Querini cùng Karpathos và Kasos đầu hàng; Patmos dưới sự cai quản của tu viện cũng chấp nhận sự bảo hộ của Ottoman. Công quốc Naxos thì bị buộc nộp cống và được để nguyên; việc sáp nhập nó phải đợi đến năm 1566.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Chiến dịch bắc Aegea của Barbarossa: chiếm Skyros và quần đảo Bắc Sporades", "20ab688e"], "d": ["Trên đường dẫn đến Preveza, hạm đội lần lượt tiếp nhận các đảo bắc Aegea đã nương nhờ Venice sau cuộc chinh phục Istanbul. Skyros ở phía bắc Euboea cùng Skiathos, Skopelos và Alonnisos trấn giữ cửa vịnh Salonika như vậy thuộc quyền cai quản của Ottoman. Những đảo này lấp khoảng trống cuối cùng ở bắc Aegea, vốn vẫn nằm trong tay Venice thêm sáu mươi tám năm dù Euboea đã bị chiếm năm 1470.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Chiếm Aden và sáp nhập bờ biển Yemen", "e7d46d8f"], "d": ["Hạm đội khởi hành từ Suez cho chiến dịch Ấn Độ trước tiên hướng đến bờ biển Yemen, vì không thể ra đại dương khi chưa bảo đảm an toàn Biển Đỏ. Ngày 3 tháng 8 năm 1538, Hadım Süleyman Pasha tiến vào cảng Aden; Amir ibn Dawud, người cai trị thuộc dòng Tahiri có khuynh hướng ngả về Bồ Đào Nha, bị đưa đến trước cửa thuyền trưởng và bị xử tử, và một đội canh giữ 500 người được để lại trong thành phố. Trong cùng chiến dịch, Mocha cùng các đảo Kamaran và Farasan khống chế eo biển cũng được tiếp nhận, và nền móng của tỉnh beylerbeylik Yemen được đặt. Như vậy lần đầu tiên Đế quốc Ottoman sở hữu toàn bộ bờ phía bắc của Bab al-Mandab; còn Sanaa và vùng nội địa sẽ phải đợi thêm chín năm.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Chiến dịch Moldavia và sáp nhập vùng Budjak (Bender)", "90a88a56"], "d": ["Trong chiến dịch đánh voivode Moldavia Petru Rareş, người không làm tròn nghĩa vụ với Ottoman, Suceava bị chiếm, còn thành Iaşi bị khan Crimea Sahib Giray cướp phá. Sultan đưa Stefan Lăcustă lên làm voivode và sáp nhập trực tiếp Bender cùng vùng Budjak (Nam Bessarabia) vào đất Ottoman. Việc sáp nhập này là một trong những mắt xích biến bờ tây bắc Biển Đen thành vùng nội hải của Ottoman. Moldavia vốn đã là một công quốc voivode lệ thuộc Ottoman; chiến dịch này không lấy đất từ một nhà nước ngoại quốc, mà chỉ tước quyền cai quản nội bộ Bender và Budjak khỏi voivode và đặt trực thuộc sultan; phần còn lại của công quốc vẫn giữ địa vị chư hầu. Cùng một cấu trúc sẽ lặp lại năm 1484 tại Kiliya và Akkerman, năm 1713 tại Khotyn: các pháo đài biên giới thì trực trị, vùng đất bên trong thì chư hầu.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Tiếp quản Nauplion (Anabolu) theo hiệp ước", "104d0937"], "d": ["Cuộc chiến với Venice kéo dài ba năm sau Preveza kết thúc khi nước cộng hòa chấp nhận từ bỏ hai pháo đài cuối cùng ở Morea. Nauplion và Monemvasia, vốn không thể chiếm bằng vây hãm, được giao cho Ottoman trên bàn đàm phán cùng với khoản bồi thường chiến phí ba trăm nghìn ducat. Bán đảo Morea như vậy được thống nhất, không còn lại một dấu chân nào của Venice.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["Szeged thuộc quyền cai quản của Ottoman và việc lập liva Szeged", "019aa000"], "d": ["Sau khi quyền cai quản của Ottoman được thiết lập đầy đủ tại Buda năm 1541, giới chức sắc Szeged đã chấp nhận quyền thống trị của Ferdinand I và chuẩn bị phòng thủ vũ trang. Đầu năm 1543, tổng đốc beylerbey Buda là Küçük Bali Pasha cho triệu các nhà quản lý thành phố đến chỗ mình, xử tử họ với tội phản bội, sau đó phái quân đến chiếm thành phố. Vào lúc này, liva (sanjak) Szeged được thành lập, và Derviş Bey, con trai Bali Pasha, được bổ nhiệm làm sanjakbey đầu tiên; liva ban đầu trải đến vùng giữa sông Danube và sông Tisza.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Chinh phục Valpó, Siklós và Pécs", "2ca030a3"], "d": ["Mục tiêu đầu tiên của chiến dịch Hungary tiến hành hai năm sau khi sáp nhập Buda là bảo đảm an toàn cho cánh phía nam của tỉnh mới nằm giữa sông Drava và sông Danube. Sau khi chiếm các pháo đài Valpó và Siklós, trung tâm vùng Baranya là Pécs đầu hàng. Thành phố sẽ trở thành trung tâm đông dân nhất và được xây dựng nhiều nhất của Hungary thuộc Ottoman, và sử gia İbrahim Peçuylu lấy tên mình từ đây.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Chinh phục Esztergom và Székesfehérvár", "efca9e05"], "d": ["Trong chiến dịch Hungary do Süleyman Lập pháp đích thân thực hiện, sau hai tuần rưỡi vây hãm, Esztergom, trung tâm tôn giáo và tòa tổng giám mục của Vương quốc Hungary, thuộc quyền cai quản của Ottoman. Sau đó, Székesfehérvár, thành phố nơi các vua Hungary đăng quang, cũng bị chiếm, hoàn tất vành đai phòng thủ của tỉnh Buda. Esztergom, pháo đài then chốt của tuyến sông Danube, nằm trong tay Ottoman đến năm 1595.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Vành đai phòng thủ phía bắc và phía tây của Buda: Vác, Hatvan và Simontornya", "733ee5ce"], "d": ["Sau khi Esztergom và Székesfehérvár được chiếm, tổng đốc beylerbey Buda đã hành động mà không cần chiến dịch của sultan để hoàn tất vành đai pháo đài bao quanh thủ phủ. Vác ở khúc quanh sông Danube, Hatvan — cửa ngõ của đồng bằng Alföld — và Simontornya trên tuyến sông Sió lần lượt được tiếp nhận. Những thành quả của năm lặng lẽ này đã biến Buda từ một thành phố biên cương thành trung tâm của một tỉnh sẽ trụ vững suốt một trăm bốn mươi năm.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Sáp nhập Basra và vươn ra vịnh Basra", "02f87c11"], "d": ["Trong thời gian chinh phục Baghdad (1534), người cai trị Basra là Rashid ibn Maghamis đã tỏ lòng quy phục Kanunî, và năm 1538 gửi chìa khóa thành. Khi người kế nhiệm Sheikh Yahya quay sang chống Ottoman, tổng đốc beylerbey Baghdad Ayas Pasha tiến quân theo đường bộ, còn sanjakbey Mosul tiến theo sông Euphrates với 120 thuyền; Ayas Pasha tiến vào Basra ngày 26 tháng 12 năm 1545, và thành phố trở thành trung tâm một tỉnh beylerbeylik. Hải cảng ở cửa sông Shatt al-Arab này là cánh cửa để Ottoman vươn ra vùng vịnh mà Bồ Đào Nha kiểm soát từ Hormuz; theo Hiệp ước Amasya năm 1555, Iran cũng công nhận tình trạng này.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Chinh phục Sanaa và vùng nội địa Yemen", "d31ded85"], "d": ["Sau Taiz, Sanaa cũng bị chiếm và toàn xứ được gắn vào tỉnh beylerbeylik. Tuy nhiên, vì địa hình hiểm trở và khác biệt giáo phái, quyền thống trị này không bao giờ yên ổn; đối với Ottoman, Yemen trở thành mặt trận không ngừng nuốt binh lính.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Chinh phục Taiz", "d4509df9"], "d": ["Ở Yemen, nơi chín năm trước Ottoman chỉ bằng lòng với dải bờ biển, trước việc các imam Zaydi ngày càng mạnh lên ở vùng nội địa miền núi, lực lượng của Özdemir Pasha đã lên cao nguyên và chiếm Taiz.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["Hiệp ước Istanbul — hòa bình năm năm với nhà Habsburg", "41f81773"], "d": ["Một hòa ước thời hạn năm năm được ký giữa Ottoman và nhà Habsburg; Ferdinand đồng ý nộp mỗi năm 30.000 ducat cho phần đất Hungary mình nắm giữ. Hiệp ước ghi nhận về pháp lý tình trạng thực tế Hungary bị chia ba. Việc mặt trận phía tây được bảo đảm như vậy cho phép Süleyman Lập pháp tổ chức những chiến dịch mới đánh Iran.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Chiến dịch Iran lần thứ hai và việc chiếm lại Tabriz", "e82365df"], "d": ["Trong chiến dịch tiến hành theo sự xúi giục của Alqas Mirza, em trai của Shah Tahmasp đã nổi loạn chống ông và lánh sang Istanbul, quân đội tiến vào Tabriz lần thứ hai. Vì người Safavid lại không giao chiến trên dã ngoại mà vừa rút vừa đốt phá đất đai, quân đội chỉ ở lại thành phố được vài tuần. Chiến dịch khẳng định dứt khoát rằng không thể giữ được Tabriz và hướng chiến lược Ottoman sang việc thiết lập một đường biên giới cố định, tức là củng cố Van.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Chinh phục Van và ổn định biên giới phía đông", "fc8f930b"], "d": ["Pháo đài Van, bị vây trên đường trở về từ Tabriz, nằm trên khối đá vươn cao ở bờ đông hồ, là ổ khóa không thể tranh cãi của vùng và đã đầu hàng sau một cuộc vây hãm ngắn. Thành phố lập tức được đặt làm trung tâm tỉnh beylerbeylik; các sanjak Erciş, Adilcevaz và Hakkâri được gắn vào đây. Trái ngược với Tabriz, Van được giữ vững và suốt bốn trăm năm vẫn là vị trí thường trực tiến xa nhất về phía đông của Ottoman.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Sáp nhập al-Ahsa và Qatif — bờ vịnh phía Ả Rập", "f6701e60"], "d": ["Sau khi chiếm Basra, Qatif, nơi đã trở thành tiền đồn của Bồ Đào Nha trên bờ tây vùng vịnh, bị chiếm, và cùng với các ốc đảo al-Ahsa trong nội địa, một tỉnh beylerbeylik mới được lập. Đây là điểm xuất phát của các chiến dịch hướng đến Bahrain và Hormuz. Như vậy Đế quốc Ottoman cùng lúc có tiếng nói trên cả bờ Biển Đỏ lẫn bờ vịnh Basra của bán đảo Ả Rập.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Mất Shahrizor — Sührab, bey Ardalan, ngả sang Safavid", "5600efc9"], "d": ["Vùng Shahrizor, đã công nhận quyền cai quản của Ottoman trong Chiến dịch Hai xứ Iraq (1535), nằm dưới quyền của emir Ardalan là Bige Bey, đóng tại pháo đài Zalm. Sau khi Bige Bey mất năm 1550, người em Sührab chiếm pháo đài Zalm và nắm quyền công quốc, quay sang Safavid và bỏ sự quy phục Ottoman; vùng Shahrizor như vậy thoát khỏi ảnh hưởng của Ottoman. Vùng này chỉ được lấy lại trong chiến dịch Nakhchivan, khi pháo đài Zalm bị vây và chiếm năm 1554.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Chiếm Ardahan và lưu vực Çıldır", "14c9eb76"], "d": ["Trong cuộc chiến đang tiếp diễn với Safavid, tổng đốc beylerbey Erzurum hướng đến lãnh thổ của các atabeg Gruzia trên vòng cung sông Kura và đưa Ardahan cùng vùng quanh Çıldır vào quyền cai quản của Ottoman. Tuyến Kars – Ardahan như vậy được thống nhất, và các cao nguyên mở sang Gruzia ở phía đông bắc được kiểm soát. Trật tự hành chính dứt khoát của vùng sẽ được hoàn tất với tỉnh eyalet Çıldır thành lập hai mươi bảy năm sau.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Sokullu Mehmed Pasha vượt sông Danube — chiến tranh Transylvania bắt đầu", "38fde931"], "d": ["Trước những rối loạn do tu sĩ Martinuzzi, người giám hộ của vua nhỏ tuổi János Zsigmond xứ Transylvania, gây ra, và việc Transylvania giao các pháo đài Banat cho Ferdinand, một chiến dịch mới được coi là cần thiết; quyền chỉ huy được trao cho tổng đốc beylerbey Rumelia Sokullu Mehmed Pasha. Bất chấp các nỗ lực trì hoãn của Martinuzzi, quân đội vượt sông Danube, chiếm Becse, Becskerek, Csanád và Lipova; tuy nhiên cuộc vây hãm Temeşvar bị dỡ bỏ ngày 16 tháng 11 vì giá rét. Như vậy một cuộc chiến mới giữa Ottoman và Habsburg đã mở ra ở Hungary.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["Thành phố Lipova (Lippa) rơi vào tay quân Áo của Castaldo — pháo đài đầu hàng ngày 5 tháng 12", "a0e1ff0d"], "d": ["Lipova, được Sokullu Mehmed Pasha chiếm vào tháng 10 năm 1551, bị quân của tướng Castaldo vây hãm ngày 4 tháng 11; hai ngày sau, thành phố rơi vào tay quân Áo. Ulama Pasha với đội đồn trú 5.000 người còn giữ pháo đài thêm chín ngày và ngày 5 tháng 12 năm 1551 rút ra theo thỏa thuận. Lipova nằm trong tay Habsburg cho đến khi Temeşvar thất thủ năm 1552.", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["Các lực lượng phái từ Temeşvar chiếm giữ những đồn lũy palanka ở Nam Banat — Versec, Haram, Keve", "edca0921"], "d": ["Sau khi Temeşvar đầu hàng quân đội Ottoman, các đơn vị tách khỏi đạo quân vây hãm đã tiến đến những đồn lũy palanka nhỏ ở Banat; theo tường thuật của Bánlaky, các palanka Versec, Facset, Mehádia, Csákóvár, Haramvár và Keve đã bị những lực lượng này chiếm giữ. Như vậy Haram bên bờ sông Danube cũng rơi vào tay người Ottoman.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["Chinh phục Szolnok và cuộc vây hãm Eger thất bại", "a7156e8f"], "d": ["Hai đạo quân Ottoman hợp lại sau khi chiếm Temeşvar đã lấy Szolnok bên sông Tisza gần như không cần giao chiến, khi lính đánh thuê bỏ pháo đài. Pháo đài Eger bị vây sau đó thì không thể chiếm được trước sức kháng cự ba mươi tám ngày của đội đồn trú hai nghìn người dưới quyền István Dobó, và quân đội rút lui khi mùa đông ập đến. Việc trong cùng một chiến dịch pháo đài này thất thủ dễ dàng còn pháo đài kia trụ được là dấu hiệu rõ ràng đầu tiên cho thấy biên giới ở Hungary không còn tự động tiến lên có lợi cho Ottoman nữa.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Liên minh Ottoman - Pháp — hạm đội Pháp đặt dưới quyền Ottoman", "a8e01b22"], "d": ["Theo hiệp ước ngày 1 tháng 2 năm 1553, hạm đội Pháp được đặt dưới quyền hạm đội Ottoman; hai bên dự kiến hành động chung chống Tây Ban Nha ở Tây Địa Trung Hải. Sau hiệp ước, ngày 15 tháng 6 năm 1553, Turgut Reis ra khơi với bốn mươi lăm chiến thuyền galley để hỗ trợ Pháp. Đây là hiệp ước liên minh chính thức đầu tiên đưa nền tảng thương mại của các nhượng ước (capitulation) năm 1536 sang hợp tác quân sự.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Hoàng tử Mustafa bị hành quyết tại Ereğli (Konya)", "dec36858"], "d": ["Vào lều của cha để gia nhập quân đội được tập hợp cho chiến dịch Nakhchivan, hoàng tử Mustafa, đúng lúc sắp được yết kiến, đã gặp các đao phủ và bị thắt cổ chết. Việc sát hại vị ứng viên kế vị được quân đội rất yêu mến đã gây phẫn nộ sâu sắc trong lính Janissary, và Rüstem Pasha bị cách chức đại tể tướng. Sự kiện đi vào văn học và ký ức dân gian như một trong những vết rạn gây tranh cãi nhất của chính sách hoàng tử Ottoman.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["Đẩy biên giới Ibrim và Nubia xuống phía nam", "c57d5d77"], "d": ["Biên giới phía nam của tỉnh Ai Cập được đẩy quá thác ghềnh thứ hai khi Özdemir Bey củng cố pháo đài Ibrim, vươn trên một mũi đá bên sông Nile, và Hạ Nubia được sáp nhập hoàn toàn vào Ai Cập thuộc Ottoman. (Ở Ibrim, tổ chức hành chính Ottoman đã được thiết lập sau cuộc chinh phục Ai Cập; trên bản đồ, Ibrim được thể hiện thuộc Ottoman từ năm 1517. Năm này chỉ là xấp xỉ, nguồn không nêu năm.) Pháo đài vừa là con đê chắn các cuộc tập kích từ Nubia, vừa là điểm kiểm soát con đường vàng và nô lệ đi Sennar. Đơn vị đồn trú người Bosnia được bố trí tại đây tồn tại lâu đến mức ba trăm năm sau con cháu họ vẫn còn ở trong pháo đài. Các nguồn đưa ra hai tường thuật khác nhau về thời điểm Ibrim đi vào quyền cai quản của Ottoman: mục từ Sudan của TDV gắn việc Hạ Nubia sáp nhập vào Ai Cập thuộc Ottoman với chiến dịch của Özdemir Pasha giữa thế kỷ 16, còn mục từ Nubia viết rằng vùng đến tận thung lũng Halfa và tổ chức hành chính ở Ibrim được thiết lập ngay sau cuộc chinh phục năm 1517. Sanjak Ibrim được gắn vào tỉnh Habesh ngày 26 tháng 7 năm 1573.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["Giành Béjaïa (Bougie) từ tay người Tây Ban Nha", "49691cda"], "d": ["Béjaïa, nằm trong tay Tây Ban Nha suốt bốn mươi ba năm và chia đôi dải bờ biển giữa Algiers và Constantine, đã đầu hàng sau khi bị vây cả trên bộ lẫn trên biển. Với việc pháo đài thất thủ, bờ biển thuộc quân đoàn đồn trú Algiers trở nên liền mạch đến tận Oran. Ở Tây Ban Nha, tổn thất này gây phẫn nộ lớn đến mức viên chỉ huy giao nộp pháo đài, Alonso de Peralta, bị xử tử tại quê nhà.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["Zeila được sáp nhập vào tỉnh Habesh", "7bbf369a"], "d": ["Ở cực nam của tỉnh Habesh, hải cảng Zeila trên bờ châu Phi của vịnh Aden được đưa vào quyền cai quản của Ottoman. Thành phố này, cửa ngõ ra biển của Vương quốc Hồi giáo Adal, là điểm tiếp tế cuối cùng cho tàu thuyền đi ra ngoài Bab al-Mandab. Với việc sáp nhập Zeila, biên giới của Đế quốc Ottoman ở châu Phi đạt đến điểm cực nam.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Trận chiến giữa các hoàng tử tại Konya", "1c8de387"], "d": ["Bước vào cuộc tranh ngôi, hoàng tử Bayezid đem khoảng 30.000 quân đến trước Konya và sau hai ngày giao chiến đã bại trước người em là hoàng tử Selim. Bại trận, Bayezid chạy qua Amasya sang Iran, nương nhờ Shah Tahmasp. Trận đánh biến cuộc khủng hoảng kế vị trong những năm cuối đời Süleyman Lập pháp thành vấn đề đối ngoại.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["Hải chiến thắng lợi Djerba", "c7b905c1"], "d": ["Hạm đội Ottoman do Piyale Pasha chỉ huy đã đánh tan hạm đội liên minh Tây Ban Nha - Genoa - Malta, tập hợp để chiếm lại Tripoli (Libya), ngoài khơi Djerba bằng chiến thuật chia đôi đội hình. Quân đồng minh mất phần lớn hạm đội, và pháo đài trên đảo cũng sớm thất thủ. Djerba được coi là hải chiến thắng lợi lớn thứ hai, sau Preveza, củng cố ưu thế của Ottoman ở Địa Trung Hải.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["Hoàng tử Bayezid bị hành quyết tại Qazvin", "a759de14"], "d": ["Hoàng tử Bayezid, người lánh nạn sang Iran, sau những cuộc mặc cả dài đã bị Shah Tahmasp giao cho phái đoàn Ottoman và bị thắt cổ cùng bốn con trai. Đổi lại việc giao nộp, người Safavid nhận được những nhượng bộ vật chất đáng kể và bảo đảm biên giới. Với cuộc hành quyết này, trở ngại cuối cùng trên đường lên ngôi của Selim II được dẹp bỏ, và trật tự hòa bình của Hiệp ước Amasya được duy trì.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["Giành Chios từ tay người Genoa", "a4559b96"], "d": ["Chios, suốt hai trăm năm được cai quản như một thuộc địa thương mại của dòng họ Giustiniani người Genoa và nộp cống cho Ottoman, đã được Piyale Pasha tiếp nhận mà không nổ một phát súng, với lý do chậm nộp cống và cho tàu địch vào cảng. Cùng với Chios và Psara, sự hiện diện cuối cùng của Genoa ở bờ đông biển Aegea cũng bị xóa bỏ. Việc sản xuất nhựa mastic và đặc quyền của người Chios được giữ nguyên, đảo được gắn vào tỉnh Quần đảo Địa Trung Hải (Cezayir-i Bahr-i Sefid).", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["Sáp nhập Công quốc Naxos — toàn bộ quần đảo Cyclades", "68f0ec0b"], "d": ["Công quốc Naxos của người Latinh, tồn tại từ năm 1207 và nộp cống cho Ottoman từ năm 1537, đã bị bãi bỏ với lý do những khiếu nại về việc công tước cuối cùng Giacomo Crispo áp bức dân chúng. Naxos, Paros, Milos, Andros, Syros, Mykonos, Ios, Amorgos và toàn bộ các đảo Cyclades quanh đó được đưa vào quyền cai quản trực tiếp của Ottoman chỉ bằng một quyết định. Kanunî giao việc quản lý các đảo cho Joseph Nasi một thời gian; quyền thống trị ba thế kỷ rưỡi của người Latinh như vậy chấm dứt giữa lòng biển Aegea.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["Cuộc nổi dậy ở Yemen và chiến dịch Yemen của Koca Sinan Pasha", "c8218d8e"], "d": ["Imam phái Zaydi là Mutahhar nổi dậy với lý do bị cưỡng thu thuế, đánh bật chính quyền Ottoman khỏi phần lớn Yemen. Được Istanbul phái đến, Koca Sinan Pasha, qua các cuộc hành quân những năm 1568-1570, đã chiếm Kawkaban sau một cuộc vây hãm dài và tái lập chủ quyền Ottoman trong vùng. Chiến dịch có ý nghĩa sống còn trong việc giữ quyền kiểm soát cửa phía nam của Biển Đỏ và tuyến thương mại Ấn Độ Dương.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["Liên minh phòng thủ với Vương quốc Hồi giáo Aceh và viện trợ cho Ấn Độ Dương", "8e835f24"], "d": ["Trước các cuộc tấn công của Bồ Đào Nha, sứ giả Aceh đến xin Süleyman Lập pháp cứu viện; khi sultan qua đời tại Szigetvár, họ bày tỏ lòng trung thành với Selim II, và một hiệp ước phòng thủ được ký với ông. Sultan ra lệnh gửi đại bác, súng, đạn dược và thợ lành nghề từ Alexandria; mười bảy chiến thuyền được chuẩn bị để đưa sang vùng biển Ấn Độ. Cuộc nổi dậy ở Yemen lan rộng đã ngăn hạm đội khởi hành, nhưng các pháo thủ và thợ Ottoman đến được Aceh đã để lại dấu ấn lâu dài trong vùng.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["Đổ bộ lên Síp: chiếm Limassol", "9074ccc9"], "d": ["Quân đội Ottoman đổ bộ lên đảo đã chiếm Limassol mà không gặp kháng cự đáng kể và hôm sau hướng đến Larnaca. Nhờ dân địa phương bất mãn với sự cai trị của Venice và giúp đỡ lực lượng Ottoman, ở Larnaca cũng không gặp kháng cự nghiêm trọng; bến Tuzla được dùng làm căn cứ đổ quân và trang bị. Venice đã dồn lực phòng thủ vào Nicosia và Famagusta; tổng đốc Paphos chỉ tỏ ý quy phục tổng chỉ huy sau khi Nicosia thất thủ.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["Chinh phục Nicosia", "413d866b"], "d": ["Sau cuộc vây hãm bắt đầu ngày 25 tháng 7 năm 1570 và kéo dài bốn mươi lăm ngày, Nicosia, thủ phủ Síp do Venezia cai quản, đầu hàng quân đội Ottoman. Việc trung tâm hòn đảo thất thủ đã dồn sức kháng cự của Venezia vào pháo đài Famagusta. Cuộc chinh phục gây tiếng vang lớn ở phương Tây và đẩy nhanh quá trình dẫn đến việc lập hạm đội Liên minh Thần thánh dưới sự dẫn dắt của Giáo hoàng.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["Kyrenia đầu hàng — bờ biển phía bắc của Síp", "39fdeea5"], "d": ["Việc Nicosia thất thủ ngày 9 tháng 9 trong cảnh bị tàn sát đã bẻ gãy sự kháng cự ở miền bắc Síp. Pháo đài Kyrenia sau dãy núi Pentadaktylos (Beşparmak), khi biết số phận thủ phủ, tám ngày sau đã đầu hàng có điều kiện, và đội đồn trú được cho rời đảo. Trên đảo, cờ Venice chỉ còn ở Famagusta; nơi này còn trụ thêm mười một tháng.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["Tái thiết hạm đội sau Lepanto", "db51fe44"], "d": ["Việc đầu tiên của Kılıç Ali Pasha, được cử làm đại đô đốc sau thảm bại Lepanto, là xây dựng lại hạm đội đã tổn thất nặng; các xưởng đóng tàu làm việc không ngừng suốt mùa đông 1571-1572. Tháng 6 năm 1572, một hạm đội mới gồm khoảng 250 chiến thuyền galley và 300 galley của các thuyền trưởng tình nguyện ra Địa Trung Hải. Sự phục hồi nhanh chóng này cho thấy Lepanto không thể bẻ gãy lâu dài sức mạnh hải quân Ottoman.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["Hiệp ước Istanbul với Venezia — công nhận Síp", "4d08ef50"], "d": ["Bị đơn độc khi Liên minh Thần thánh tan rã, Venezia ký hòa ước riêng với Ottoman, chính thức công nhận Síp thuộc về Ottoman và chấp nhận trả bồi thường chiến phí. Hiệp ước cho thấy rõ rằng chiến thắng Lepanto không đem lại thành quả chính trị nào cho thế giới Cơ đốc. Từ đó, suốt bảy mươi năm, Venezia sẽ tránh chiến tranh trực tiếp với Ottoman.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["Selim II qua đời", "c289f5ee"], "d": ["Sau một cú ngã, Selim II không thể dự divan (hội đồng triều chính) khoảng hai tháng rồi qua đời. Cái chết của ông được giấu trong cung mười hai ngày, cho đến khi con trai trưởng Murad từ Manisa về đến Istanbul. Các nguồn khác nhau về ngày mất: Selaniki ghi ngày 15 tháng 12; Gerlach, Mehmed b. Mehmed và Cenabi ghi ngày 13 tháng 12.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["Công bố Selim II qua đời và Murad III lên ngôi", "84334d70"], "d": ["Ngày 22 tháng 12 năm 1574, cái chết của Selim II và việc Murad III, được đưa từ Manisa về, lên ngôi được chính thức công bố. Vị sultan mới sẽ ở ngôi hai mươi mốt năm; thời trị vì của ông được nhớ đến với các cuộc chiến dài với Iran ở phương Đông, đêm trước của cuộc Chiến tranh Dài ở phương Tây, và việc pha giảm phẩm chất đồng akçe ở trong nước. Cho đến khi Sokollu Mehmed Pasha qua đời năm 1579, trật tự cũ trong việc điều hành nhà nước vẫn được duy trì.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["Trận Wadi al-Makhazin (Ksar el-Kebir) — Abd al-Malik được Ottoman hậu thuẫn tiêu diệt quân đội Bồ Đào Nha", "21280dac"], "d": ["Lên ngôi Morocco với sự hậu thuẫn của Ottoman, Abd al-Malik đã tiêu diệt đại quân của vua Bồ Đào Nha Sebastian tại Wadi al-Makhazin; vì ba quân vương cùng chết trong trận này, các nguồn phương Tây gọi đây là 'Trận Ba Vua'. Sức mạnh quân sự Bồ Đào Nha sụp đổ và chẳng bao lâu sau đất nước này rơi vào tay Tây Ban Nha. Abd al-Malik cũng chết trong trận; người em kế vị là Ahmad al-Mansur cử một phái đoàn đến báo tin chiến thắng cho Istanbul. Quan hệ giữa hai nhà nước không ở mức cống nạp hay thần phục mà ở mức trao đổi sứ giả và lễ vật, và chẳng bao lâu sau trở nên căng thẳng vì chuyện lễ vật.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["Dân Derbent tỏ lòng quy phục Lala Mustafa Pasha — Cổng Sắt thuộc quyền cai quản của Ottoman", "9c55aeff"], "d": ["Trong chiến dịch Shirvan, một phái đoàn bảy người của dân Derbent đã đến gặp Tổng chỉ huy Lala Mustafa Pasha tại Aresh để tỏ lòng quy phục. Derbent (Cổng Sắt), chặn lối đi hẹp giữa bức tường Kavkaz và biển Caspi, là cửa ải bắt buộc của các tuyến đường bộ từ phía bắc, đóng vai trò then chốt trong việc giữ Shirvan. Quyền thống trị của Ottoman ở đây kéo dài đến năm 1607.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["Chinh phục Shirvan: chiếm Shamakhi", "9afae4c1"], "d": ["Sau chiến thắng Çıldır, quân đội tiến vào Kavkaz đã vào Shirvan, tỉnh giàu nhất của Safavid bên bờ biển Caspi, và chiếm trung tâm là Shamakhi. Özdemiroğlu Osman Pasha được bổ nhiệm làm tổng đốc beylerbey ở đây, và nhánh phía bắc của Con đường Tơ lụa được đặt dưới sự kiểm soát của Ottoman. Shirvan sẽ trở thành mặt trận đổi chủ nhiều nhất và tốn kém nhất trong cuộc chiến phía đông kéo dài mười hai năm.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["Chiếm Baku — vươn tới bờ biển Caspi", "eb5adab8"], "d": ["Là mắt xích cuối cùng của chiến dịch Shirvan, hải cảng Baku trên bờ tây biển Caspi bị chiếm. Các giếng dầu quanh thành phố ngay thời đó đã là nguồn thu được biết đến, và hải cảng là điểm xuất đi của lụa Iran vận chuyển qua biển Caspi. Như vậy lần đầu tiên và duy nhất trong lịch sử, Đế quốc Ottoman có được dải bờ biển trên biển Caspi.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["Chinh phục Yerevan (Revan) và xây pháo đài", "7f623b7b"], "d": ["Ferhad Pasha, ở Kars nhận lệnh đến Yerevan và xây một pháo đài tại đó, đã tiến quân đến Yerevan, và thành phố được đặt dưới sự kiểm soát của Ottoman vào đầu tháng Ramadan năm 991 (giữa tháng 9 năm 1583). Tại Yerevan, nơi trấn giữ cửa ngõ phía bắc của thung lũng sông Aras, một pháo đài mới và lớn được xây; thành phố trở thành trung tâm tỉnh beylerbeylik. Nằm giữa đường hành quân từ Kars đến Tabriz, Yerevan là xương sống hậu cần của mặt trận phía đông. Pháo đài được xây kiên cố đến mức suốt hai trăm năm sau đó luôn là mục tiêu không đổi của các cuộc chiến Ottoman – Iran.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["Sáp nhập Karabakh và Ganja", "29abaead"], "d": ["Là thành quả cuối cùng của cuộc chiến mười năm ở phía đông, năm 1588 Ferhad Pasha tiến quân đến Ganja và vào thành phố ngày 1 tháng 9; vùng Karabakh giữa sông Kura và sông Aras cùng trung tâm Ganja được đưa vào quyền cai quản của Ottoman. Như vậy Shirvan, Yerevan và Karabakh hợp lại, tạo thành một tuyến Ottoman liền mạch ở Kavkaz. Hiệp ước Ferhad Pasha ký năm 1590 sẽ xác nhận biên giới này, nhưng thành quả chỉ giữ được hai mươi năm.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["Chinh phục Bihać", "651a7275"], "d": ["Beylerbey Bosnia là Telli Hasan Pasha, sau khi lấy đồn tiền tiêu Ripač của Bihać vào tháng 11 năm 1591, đã chiếm cả thành và pháo đài vào năm 1592; sau mười ngày vây hãm, viên chỉ huy Lamberg đầu hàng. Cuộc chinh phục này đẩy biên giới Bosnia tiến dọc sông Una, và là thành quả lớn cuối cùng của Ottoman trước thềm cuộc Chiến tranh Dài sẽ bùng nổ một năm sau, khi Telli Hasan Pasha tử trận trước sông Kupa.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["Bùng nổ cuộc 'Chiến tranh Dài' Ottoman - Áo", "bd22c392"], "d": ["Sau khi beylerbey Bosnia là Telli Hasan Pasha bị đánh tan và tử trận trước sông Kupa (Sisak), Nhà nước Ottoman tuyên chiến với Áo, mở đầu cuộc Chiến tranh Dài kéo dài mười ba năm. Cuộc chiến này, trong đó bộ binh trang bị hỏa khí giữ vai trò quyết định, đã đẩy nhanh việc tuyển dụng lính sekban và lính hỏa mai trong tổ chức quân đội Ottoman và làm sâu thêm sự suy thoái của kỵ binh sipahi hưởng đất timar. Chiến tranh kết thúc năm 1606 bằng Hiệp ước Zsitvatorok.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["Koca Sinan Pasha xuất quân đánh Áo — chiến dịch đầu tiên của Chiến tranh Dài", "d4a2f46d"], "d": ["Sau khi beylerbey Bosnia là Hasan Pasha bị đánh tan và tử trận trước Sisak, đại tể tướng Koca Sinan Pasha dùng lời lẽ hoa mỹ và những lời hứa thuyết phục sultan đồng ý chiến tranh, rồi lên đường cùng 12.000 lính Janissary và các đơn vị khác. Như vậy, chiến dịch đầu tiên của cuộc chiến Ottoman - Áo kéo dài mười ba năm đã mở màn.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["Chinh phục Győr (Yanıkkale)", "14b75207"], "d": ["Sau hơn một tháng vây hãm, đại tể tướng Koca Sinan Pasha tiếp nhận sự đầu hàng của Győr, được coi là ổ khóa trên đường đến Vienna. Việc pháo đài thất thủ gây hoảng loạn lớn ở châu Âu và là thành quả rực rỡ nhất của Ottoman trong cuộc Chiến tranh Dài. Tuy nhiên, pháo đài chỉ giữ được bốn năm.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["Murad III qua đời", "1b62e886"], "d": ["Sau hai mươi mốt năm trị vì, Murad III qua đời trong những ngày quân Wallachia đốt Brăila và tiến đến tận Silistra; ông được an táng trong khu mộ của Hagia Sophia. Con trai ông là Mehmed III, được triệu từ Manisa, mười ngày sau đến Istanbul và lên ngôi (27 tháng 1 năm 1595).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["Mất Esztergom vào tay Áo", "f420d333"], "d": ["Trong cuộc vây hãm do Karl von Mansfeld chỉ huy, quân trấn thủ Esztergom không được tiếp viện đầy đủ đã giao pháo đài cho Đại công tước Matthias. Với việc quyền thống trị năm mươi hai năm của Ottoman chấm dứt, chuỗi phòng thủ trên tuyến sông Danube bị đứt gãy và Buda lâm vào mối đe dọa trực tiếp. Pháo đài mãi mười năm sau, năm 1605, mới được lấy lại.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["Chinh phục pháo đài Eger", "3e511629"], "d": ["Sau ba tuần giao tranh, pháo đài Eger vững mạnh, nơi trước đó người Ottoman không sao chiếm được, đã thất thủ khi quân trấn thủ đầu hàng. Cuộc chinh phục có sultan đích thân hiện diện này phần nào khôi phục tinh thần bị tổn hại do mất Esztergom, và tỉnh Eger được thành lập. Cùng với chiến thắng Keresztes (Haçova) giành được hai tuần sau, năm 1596 trở thành năm thành công nhất của Ottoman trong cuộc Chiến tranh Dài.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["Mất Győr (Yanıkkale)", "b4ccc679"], "d": ["Các đơn vị do Miklós Pálffy và Adolf von Schwarzenberg chỉ huy đã đột kích, cho nổ tung cổng pháo đài và chiếm lại Győr. Việc mất pháo đài mà bốn năm trước Koca Sinan Pasha phải tốn bao công sức mới giành được đã làm sụp đổ tuyến tiền phương của Ottoman ở Hungary. Tuy lực lượng địch vây Buda trong cùng năm bị đẩy lui, cán cân chiến tranh ngày càng biến thành chiến tranh tiêu hao.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["Cuộc nổi dậy của Karayazıcı Abdülhalim", "30493b0d"], "d": ["Tập hợp các lính sekban và levend đào ngũ khỏi quân đội trong cuộc Chiến tranh Dài, Karayazıcı Abdülhalim kiểm soát một vùng rộng lớn ở Trung Anatolia, chiếm pháo đài Urfa (tháng 11 năm 1599), tự xưng quân vương với danh hiệu 'Halim Shah' và ban những sắc chỉ mang ấn triện (tughra) của riêng mình. Được coi là thủ lĩnh đầu tiên của làn sóng Celali lớn, Karayazıcı chết năm 1602, và người em là Deli Hasan tiếp tục phong trào. Cuộc nổi dậy mở đầu thời kỳ 'cuộc đại tẩu tán', khi nông dân Anatolia ồ ạt bỏ ruộng đất.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["Tiryaki Hasan Pasha phòng thủ Kanizsa", "d56a5e6a"], "d": ["Muốn chiếm lại Kanizsa bị chinh phục một năm trước, Đại công tước Ferdinand cùng đồng minh vây pháo đài hơn hai tháng; Tiryaki Hasan Pasha chống cự với 9000 quân. Dù không nhận được viện binh bên ngoài, ông đẩy lui các cuộc tổng tiến công và bằng những cuộc xuất kích buộc địch phải rút lui với tổn thất nặng nề. Cuộc phòng thủ đã thành thiên anh hùng ca trong sử học Ottoman, và 'cuộc vây hãm Kanizsa' tự nó trở thành một thể loại văn học.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["Mehmed III qua đời và Ahmed I lên ngôi", "da735fde"], "d": ["Khi Mehmed III qua đời ngày 20 tháng 12, con trai mười bốn tuổi của ông là Ahmed I lên ngôi. Việc đây là vị sultan đầu tiên lên ngôi khi còn nhỏ và chưa từng đi trấn nhậm sanjak cho thấy trên thực tế lệ đào tạo hoàng tử ở các tỉnh đã chấm dứt. Dưới triều Ahmed I, tục giết anh em bị bỏ, chuyển sang nguyên tắc 'ekberiyet' (thành viên nam lớn tuổi nhất lên ngôi).", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["Thu hồi Esztergom", "7330f273"], "d": ["Đại tể tướng Lala Mehmed Pasha vây Esztergom, mất mười năm trước, và đưa trở lại quyền cai quản của Ottoman. Trong cùng chiến dịch, Pest và Vác cũng được giải cứu, Ottoman chấn chỉnh được tuyến phòng thủ ở Hungary. Thành công này giúp năm sau Ottoman ngồi vào bàn tại Zsitvatorok ở thế tương đối mạnh; Esztergom nằm trong tay Ottoman đến năm 1683.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["Chiến thắng đồng bằng Oruç và dẹp cuộc nổi loạn của Canbolatoğlu", "30f93532"], "d": ["Canbolatoğlu Ali Pasha, kẻ lập một tiểu quốc độc lập ở Aleppo và tìm cách liên minh với Toscana, bị đại tể tướng Kuyucu Murad Pasha giáng cho thất bại nặng nề tại đồng bằng Oruç. Với việc tái lập quyền uy trung ương ở Syria, nhánh nguy hiểm nhất của làn sóng Celali bị bẻ gãy. Cuộc thanh trừng tàn nhẫn kéo dài hai năm của Kuyucu Murad Pasha đã đem lại an ninh cho Anatolia, dù chỉ tạm thời.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["Chiến thắng Alaçayır và dẹp cuộc nổi loạn của Kalenderoğlu", "55db0485"], "d": ["Thủ lĩnh Celali là Kalenderoğlu, kẻ bắt các vùng Manisa và Bursa nộp cống, bị Kuyucu Murad Pasha đánh tan tại Alaçayır và buộc phải chạy sang Iran. Với chiến thắng này, đạo quân Celali lớn cuối cùng ở Anatolia bị giải tán. Cuộc thanh trừng khốc liệt của Kuyucu Murad Pasha, người mà tương truyền đã cho đổ xác phiến quân bị giết xuống những cái giếng sai đào, tuy lập lại trật tự trong ngắn hạn nhưng không bù đắp được tổn thất về dân số và sản xuất của Anatolia.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["Ban nhượng ước (ahdname) đầu tiên cho Hà Lan", "5d9d117e"], "d": ["Cornelis Haga, sứ thần của Cộng hòa Liên hiệp Hà Lan, đã giành được từ Ahmed I một ahdname có phạm vi như những bản đã ban cho Pháp và Anh. Nhờ đó, Hà Lan có quyền mở sứ quán tại Istanbul, lãnh sự quán tại các bến cảng Ottoman và buôn bán dưới cờ riêng. Ahdname này tượng trưng cho việc các cường quốc hải dương phương Bắc, thay thế Venezia trong thương mại Địa Trung Hải, bước vào thị trường Ottoman.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["Ahmed I qua đời và Mustafa I lên ngôi — nguyên tắc người lớn tuổi nhất kế vị", "9901c09e"], "d": ["Sau năm mươi mốt ngày mắc bệnh dạ dày, Ahmed I qua đời ở tuổi hai mươi tám, và người được đưa lên ngôi không phải con ông mà là em ông, Mustafa I. Như vậy, lệ kế vị từ cha sang con bị bỏ, trên thực tế chuyển sang chế độ 'ekberiyet', theo đó thành viên nam lớn tuổi nhất của hoàng tộc lên ngôi. Lần trị vì đầu tiên kéo dài chín mươi sáu ngày này cũng mở đầu thời kỳ các hoàng tử được nuôi lớn trong 'kafes' (cái lồng, khu cung cấm biệt lập).", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["Mustafa I bị phế truất và Osman II (Osman Trẻ) lên ngôi", "e0f552f2"], "d": ["Với lý do tâm thần không ổn định, Mustafa I bị phế truất sau chín mươi sáu ngày, và Osman II, con trai mười bốn tuổi của Ahmed I, trở thành sultan. Theo lời thuật dựa trên Hasanbeyzade, Mustafa Agha, tổng quản hoạn quan, đã có ảnh hưởng đến quyết định phế truất này. Osman Trẻ, với dự định giải tán quân đoàn Janissary và lập một quân đội mới, được coi là tên tuổi cấp tiến đầu tiên trong các cuộc tranh luận cải cách Ottoman. Dự định này bốn năm sau sẽ khiến ông phải trả giá bằng mạng sống.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["Hiệp ước Serav — tái lập hòa bình với Iran", "e778aca8"], "d": ["Hiệp ước Serav đạt được với Iran sau thất bại Pul-i Shikaste phần lớn xác nhận các điều khoản của Hiệp ước Nasuh Pasha năm 1612; lượng tơ lụa người Safavid phải gửi hằng năm được giảm từ hai trăm kiện xuống một trăm kiện. Như vậy, giai đoạn thứ hai của các cuộc chiến phía đông kéo dài từ năm 1603 khép lại. Hòa bình không bền lâu; khi Baghdad bị mất năm 1623, chiến tranh lại bùng lên.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["Chiến dịch Khotyn và Hiệp ước Khotyn", "bc4c823c"], "d": ["Trước đại quân do Osman II đích thân chỉ huy, doanh trại có công sự mà Chodkiewicz dựng trước Khotyn không thể vượt qua, và các đợt tấn công kéo dài nhiều tháng không đem lại kết quả. Theo hiệp ước ký ngày 9 tháng 10, sông Dniester được công nhận là biên giới, người Ba Lan cam kết ngăn các cuộc đột kích của người Cossack. Chiến dịch tuy được trình bày như thắng lợi nhưng không đạt kết quả đã củng cố sự ngờ vực của vị sultan trẻ đối với lính Janissary và ý định giải tán quân đoàn.", "7d812c58"]},
"OLAYLAR_EK5:1622-04-23:0":{"b": ["Lấy Hormuz từ tay người Bồ Đào Nha", "93e5f6cf"], "d": ["Lực lượng Safavid vây hãm và lấy lại Hormuz, nằm trong tay Bồ Đào Nha từ năm 1515; Qeshm và Gamrun (Bandar Abbas) trên bờ biển cũng chuyển sang quyền cai quản của Safavid, và thương mại vùng vịnh chuyển sang cảng mới.", "cc55e4bf"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["Mustafa I bị phế truất lần thứ hai và Murad IV lên ngôi", "1b3a9e74"], "d": ["Được đưa lên ngôi lần thứ hai sau khi Osman II bị sát hại, Mustafa I sau một năm ba tháng lại bị hạ bệ, và Murad IV mười một tuổi được tuyên bố làm sultan. Trong chín năm đầu, nhà nước trên thực tế do mẹ ông là Kösem Sultan và các đại thần trong cung điều hành. Từ năm 1632, Murad IV sẽ đích thân nắm quyền, mở ra thời kỳ tập quyền cứng rắn.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["Mất Baghdad vào tay Safavid", "db81be0c"], "d": ["Sau cuộc thương lượng của Bekir Subashi, kẻ nổi loạn ở Baghdad, với người Safavid, con trai ông là Derviş Mehmed, người đang giữ nội thành, đã giao thành cho quân của Shah Abbas. Việc mất một trong những thành phố biểu tượng của di sản chức khalip cùng phần lớn Iraq gây phẫn nộ lớn ở Istanbul. Giành lại Baghdad sẽ là mục tiêu duy nhất của chính sách phương Đông của Ottoman suốt mười lăm năm.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["Dẹp cuộc nổi loạn của Abaza Mehmed Pasha lấy Erzurum làm trung tâm", "e6da2729"], "d": ["Abaza Mehmed Pasha, beylerbey Erzurum, nổi dậy chống lính Janissary với danh nghĩa trả thù cho việc sát hại Osman II, đã kiểm soát Đông Anatolia nhiều năm và chống lại triều đình trung ương. Trước cuộc vây hãm Erzurum của đại tể tướng Hüsrev Pasha, ông buộc phải đầu hàng, được ân xá và bổ nhiệm sang Bosnia. Việc cuộc nổi loạn chấm dứt là điều kiện tiên quyết để Murad IV có thể xuất quân đánh Iran.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["Vụ hành quyết sheikh al-Islam đầu tiên: Ahizade Hüseyin Efendi", "a60a58c5"], "d": ["Lấy cớ ông đứng ra làm trung gian trong cơn hỗn loạn quân sự và gửi cho sultan lời cảnh báo bằng văn bản về thủ tục tư pháp, sheikh al-Islam Ahizade Hüseyin Efendi bị hành quyết gần Büyükçekmece. Việc ông là sheikh al-Islam Ottoman đầu tiên bị hành quyết đã phá vỡ truyền thống lâu đời rằng hình phạt nặng nhất đối với giới học giả tôn giáo (ilmiye) là lưu đày. Sự kiện được coi là biểu tượng cho quyền uy ngày càng cứng rắn của Murad IV và sự rạn vỡ thế cân bằng giữa nhà nước và giới ulama.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["Murad IV chinh phục Yerevan", "b65a9b73"], "d": ["Rời Istanbul ngày 28 tháng 3 năm 1635, Murad IV vây Yerevan ngày 28-29 tháng 7 và tiếp nhận pháo đài đầu hàng ngày 8 tháng 8; sau đó ông vào Tabriz đã bị bỏ trống và cho phá hủy thành. Để kỷ niệm chiến thắng, sultan cho xây Đình Revan (Revan Köşkü) trong Cung điện Topkapı. Chiến dịch này là cuộc hành quân lớn đầu tiên về phía đông, sau ba mươi năm gián đoạn, mà sultan đích thân cầm quân.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["Mất Yerevan vào tay Safavid", "fbb8dd25"], "d": ["Sau khi quân đội Ottoman rút đi, quân của Shah Safi vây Yerevan và chiếm lại trong vòng tám tháng. Việc pháo đài bị mất nhanh đến thế cho thấy giữ quyền thống trị lâu dài ở Kavkaz khó khăn thế nào về mặt hậu cần. Theo Hiệp ước Qasr-e Shirin năm 1639, Yerevan được để lại cho Iran, và Ottoman từ bỏ yêu sách đối với Azerbaijan.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["Tái chinh phục Baghdad", "4d2f27f3"], "d": ["Rời Istanbul ngày 8 tháng 5 năm 1638, Murad IV, sau cuộc vây hãm ác liệt kéo dài bốn mươi ngày, đã lấy lại Baghdad nằm trong tay Safavid suốt mười lăm năm; vizier Tayyar Mehmed Pasha tử trận trong cuộc vây hãm. Với việc chinh phục thành phố, quyền cai quản của Ottoman ở Iraq được tái lập, và sultan nhận danh hiệu 'Người chinh phục Baghdad'. Cuộc chinh phục trở nên lâu dài nhờ Hiệp ước Qasr-e Shirin năm sau, đặt nền móng cho đường biên giới Thổ Nhĩ Kỳ - Iran ngày nay.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["Murad IV qua đời và Sultan Ibrahim lên ngôi", "e2ca1ca0"], "d": ["Sau Murad IV, qua đời ở tuổi hai mươi bảy (hai mươi tám theo cách tính lịch Hijri), người em Ibrahim, thành viên nam duy nhất còn sống của hoàng tộc, lên ngôi. Dưới thời vị sultan mới, người đã sống nhiều năm trong 'kafes', chi tiêu của cung đình và tranh giành ảnh hưởng trong cung làm lung lay trật tự nhà nước. Việc ông bị phế truất rồi giết tám năm sau sẽ là vụ giết sultan thứ hai trong lịch sử Ottoman.", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["Thu hồi pháo đài Azov từ tay người Cossack", "e5fcf160"], "d": ["Pháo đài Azov bị người Cossack sông Don chiếm năm 1637 đã được bỏ trống trước cuộc hành quân phối hợp của Sultanzade Mehmed Pasha và khan Crimea Mehmed Giray IV; người Cossack phóng hỏa pháo đài rồi rút đi. Việc lấy lại cửa ngõ phía bắc của Biển Đen đã khép lại thời kỳ nguy hiểm khi các cuộc đột kích của người Cossack lan đến tận eo Bosphorus. Năm 1696, pháo đài lại bị mất, lần này vào tay Sa hoàng Nga Pyotr I.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["Chiến dịch Crete bắt đầu và chinh phục Chania", "a1b0c77f"], "d": ["Lấy cớ cướp biển Malta tấn công tàu hành hương Ottoman rồi lánh vào Crete, Ottoman tuyên chiến với Venezia, và hạm đội do Yusuf Pasha chỉ huy đổ quân lên đảo. Sau năm mươi bốn ngày vây hãm, pháo đài Chania bị chiếm, lập nên căn cứ Ottoman lâu dài đầu tiên trên đảo Crete. Như vậy cuộc chiến dài nhất lịch sử Ottoman đã bắt đầu; hòn đảo mãi hai mươi bốn năm sau, năm 1669, mới bị chinh phục hoàn toàn.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["Chinh phục Rethymno — Crete bị chia đôi", "8f2c4353"], "d": ["Một năm sau khi chiếm Chania, pháo đài Rethymno ở phần giữa đảo cũng thất thủ, và nửa phía tây của Crete hoàn toàn thuộc quyền cai quản của Ottoman. Trong tay Venice chỉ còn thủ phủ Candia và mỏm phía đông; hòn đảo sống trong cảnh chia đôi suốt hai mươi ba năm. Việc chiếm Rethymno là bước khởi đầu cuộc vây hãm Candia — cuộc vây hãm dài nhất trong lịch sử bắt đầu từ đây.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["Mất Klis vào tay Venezia", "5473c22c"], "d": ["Cuộc phản công của tướng Venezia Leonardo Foscolo trên mặt trận Dalmatia trong Chiến tranh Crete (Candia) đã bao trùm cả Klis, trung tâm sanjak từ năm 1537; pháo đài về tay Venezia. Việc Ottoman dồn toàn lực vào Crete khiến không thể giành lại tổn thất trên biên giới Dalmatia này — Klis không bao giờ trở lại dưới quyền cai quản của Ottoman; trung tâm sanjak được chuyển đến Livno.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["Cuộc vây hãm Candia bắt đầu", "13016b10"], "d": ["Sau khi lấy Chania và Rethymno, quân đội Ottoman vây Candia, chỗ dựa lớn cuối cùng của Venezia trên đảo. Cuộc phong tỏa kéo dài hai mươi mốt năm này được ghi nhận là một trong những cuộc vây hãm dài nhất lịch sử quân sự thế giới. Suốt thời gian vây hãm, những nỗ lực của hạm đội Venezia nhằm đóng eo Dardanelles sẽ đưa chiến tranh vào giữa lòng biển Aegea.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["Büyük Valide Kösem Sultan bị sát hại", "9d763f79"], "d": ["Kösem Sultan, khoảng sáu mươi hai tuổi, bị tìm thấy trong một căn phòng ở hậu cung và bị giết bởi tổng quản thị tòng (Başlala) Uzun Süleyman Agha cùng thủ hạ, hành động theo lệnh Turhan Sultan, mẹ của Mehmed IV. Cái chết của người phụ nữ hoàng tộc đầy quyền lực, định hướng chính sách nhà nước qua ba triều sultan, được coi là dấu chấm hết trên thực tế của thời kỳ gọi là 'Vương quyền của Phụ nữ'. Khoảng trống quyền lực để lại đã mở đường để năm năm sau Köprülü Mehmed Pasha trở thành đại tể tướng với quyền hạn phi thường.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["Thất bại ở Dardanelles và mất Bozcaada (Tenedos) cùng Lemnos", "e01a1f7e"], "d": ["Hải chiến thắng lợi lớn mà đô đốc Venezia Mocenigo giành được trước eo Dardanelles vào tháng 6 năm 1656 gần như tiêu diệt toàn bộ hạm đội Ottoman; sau đó Tenedos, Lemnos và Samothrace bị chiếm đóng. Khi eo biển bị Venezia phong tỏa, giá lương thực ở Istanbul tăng vọt và nỗi sợ kinh đô bị tấn công lan rộng. Thảm họa này là nguyên nhân trực tiếp khiến Köprülü Mehmed Pasha được đưa lên chức đại tể tướng vào tháng 9 năm 1656 với điều kiện kèm theo và quyền hạn phi thường.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["Chiến thắng Dardanelles và thu hồi Bozcaada (Tenedos)", "603da863"], "d": ["Hạm đội do Köprülü Mehmed Pasha huy động đã đánh tan hạm đội Venezia trước eo biển ngày 19 tháng 7 năm 1657; sau đó, ngày 25 tháng 8, lực lượng do Kurd Pasha chỉ huy lấy lại Tenedos, và ngày 30 tháng 8 người Venezia rút sạch khỏi đảo. Tháng 11, Lemnos cũng được giải cứu, vòng phong tỏa Dardanelles bị phá vỡ và đường tiếp tế cho Istanbul lại thông suốt. Köprülü đích thân sang đảo, cho tu sửa công sự; thành công này là thành quả quân sự lớn đầu tiên của thời đại nhà Köprülü.", "af4d7bfd"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["Chinh phục Ineu (Yanova) và chiến dịch Transylvania", "d1089616"], "d": ["Xuất quân trừng phạt Vương công Transylvania György Rákóczi II, kẻ tự ý viễn chinh Ba Lan, chà đạp quyền bảo hộ của Ottoman, Köprülü Mehmed Pasha hành quân qua Belgrade và chiếm pháo đài chiến lược Ineu. Một vương công mới được bổ nhiệm cho Transylvania, nhắc nhở nghiêm khắc về mối ràng buộc chư hầu. Chiến dịch này là mắt xích đầu tiên trong nỗ lực tái lập quyền uy của Ottoman ở Trung Âu. Transylvania vốn đã là công quốc lệ thuộc Ottoman; việc chiếm Ineu không phải chinh phục từ một nhà nước ngoại quốc, mà là tách pháo đài này khỏi quyền cai quản của công quốc chư hầu và đặt trực thuộc một sanjak Ottoman; phần còn lại của công quốc vẫn giữ địa vị chư hầu.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["Dẹp cuộc nổi loạn của Abaza Hasan Pasha", "4ba74321"], "d": ["Chống lại các cuộc thanh trừng khắc nghiệt của Köprülü Mehmed Pasha, Abaza Hasan Pasha, được các beylerbey Anatolia và các agha sekban ủng hộ, phát động một cuộc nổi dậy lớn, đòi cách chức đại tể tướng. Cuộc nổi loạn bị dập tắt ở Aleppo và các thủ lĩnh bị loại trừ; đây là cuộc kháng cự tập thể cuối cùng của các pasha tỉnh chống triều đình trung ương. Quyền uy của Köprülü nhờ vậy trở nên không thể tranh cãi, và chức đại tể tướng lại vươn lên vị trí trung tâm hành pháp thực sự của nhà nước.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["Chinh phục Oradea (Varad)", "0e6ad300"], "d": ["Trong khuôn khổ chiến dịch chống Vương công Transylvania György Rákóczi II, người tuyên chiến với Ottoman, pháo đài và thành phố Oradea đã bị chiếm. Khi một trong những pháo đài then chốt của Transylvania thất thủ, một tỉnh Ottoman mới (tỉnh Varad) được lập trong vùng. Cuộc chinh phục khiến nhà Habsburg báo động và trở thành một trong những nguyên nhân trực tiếp của cuộc chiến Ottoman - Áo bắt đầu ba năm sau. Các nơi khác được sáp nhập vào cùng ngày: Varat. Ở đây đất cũng không lấy từ một nhà nước ngoại quốc: Transylvania vốn là công quốc Ottoman lệ thuộc; việc Oradea thành tỉnh chỉ là tước quyền cai quản thành phố này khỏi công quốc chư hầu và đặt trực thuộc sultan, đúng như trường hợp Ineu hai năm trước.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["Trận Saint Gotthard", "61ebc1f2"], "d": ["Lực lượng Ottoman vượt sông Raab bị quân đội liên minh châu Âu do Montecuccoli chỉ huy chặn lại và chịu tổn thất nặng. Trận đánh được coi là bước ngoặt trong lịch sử quân sự vì lần đầu tiên cho thấy rõ ưu thế của hỏa lực súng trường của bộ binh có kỷ luật trước đợt xung phong của kỵ binh Ottoman. Dù bại trận, Ottoman vẫn giành được những điều khoản có lợi trong Hiệp ước Vasvár ký chín ngày sau.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["Hiệp ước Vasvár", "089c978c"], "d": ["Hiệp ước được ký bất chấp thất bại ở Saint Gotthard quy định Nové Zámky (Uyvar) và Oradea ở lại với Ottoman, Transylvania được để trung lập dưới sự bảo hộ của Ottoman, và Áo trả 200.000 kuruş 'tặng phẩm'. Nền hòa bình thời hạn hai mươi năm này là một trong những ví dụ hiếm hoi bên thua trận lại thắng trên bàn đàm phán. Sự bất mãn mà hiệp ước gây ra trong dư luận Habsburg sẽ nuôi dưỡng phong trào Trung Hungary và gián tiếp là chiến dịch Vienna năm 1683.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Chế độ cai trị của các dey bắt đầu ở Algiers", "e99faa51"], "d": ["Đạo đồn trú Algiers và hội các thuyền trưởng cướp biển (taife-i reîs) đã phế truất vị agha cuối cùng và bầu Hacı Mehmed làm dey suốt đời. Từ đó, Algiers không còn do beylerbey mà Istanbul bổ nhiệm cai quản, mà do dey được chính đạo đồn trú địa phương bầu ra từ hàng ngũ mình; mối ràng buộc với Ottoman chỉ còn giới hạn ở việc xướng tên sultan trong bài khutbah, lá cờ sanjak và nghĩa vụ tham chiến. Algiers như vậy đã chuyển từ tỉnh (eyalet) thành một ocaklık tự trị — Tunis trải qua sự chuyển biến tương tự năm 1705 với nhà Husaynid, và Tripoli (Libya) năm 1711 với nhà Karamanli.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["Chiến dịch Ba Lan bắt đầu — Mehmed IV và Fazıl Ahmed Pasha dẫn đầu quân đội", "75e15a39"], "d": ["Khi Ba Lan tiếp tục tấn công hetman Ukraina Petro Doroshenko, người đã chịu sự bảo hộ của Ottoman, Istanbul yêu cầu vua Ba Lan chấm dứt các cuộc tấn công; không nhận được trả lời thuận, triều đình quyết định viễn chinh Ba Lan. Ngày 4 tháng 6 năm 1672, đại tể tướng Fazıl Ahmed Pasha lên đường sang Ba Lan cùng quân đội có cả sultan tham dự. Chiến dịch sẽ kết thúc bằng việc chinh phục Kamianets và Hiệp ước Buchach.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["Chinh phục Kamianets và thành lập tỉnh Podolia", "c3f4f6d0"], "d": ["Sau chín ngày vây hãm, Kamianets, được coi là pháo đài mạnh nhất ở phía đông Ba Lan, đã đầu hàng; ngày 2 tháng 9, Mehmed IV dự buổi lễ thứ Sáu đầu tiên tại thánh đường được chuyển đổi từ nhà thờ chính tòa. Pháo đài được lập làm trung tâm của tỉnh Podolia, và lá cờ Ottoman vươn đến điểm cực bắc trên lãnh thổ Ukraina ngày nay. Kamianets sẽ là mũi tây bắc của đế quốc cho đến Hiệp ước Karlowitz năm 1699.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Kara Mustafa Pasha tiếp nhận Uman từ tay Ba Lan", "0d3543a0"], "d": ["Được phái đi đánh Ba Lan, Kara Mustafa Pasha tiếp nhận Uman, một trong các pháo đài trong tay Ba Lan; thành phố ở dưới quyền cai quản của Ottoman cho đến Karlowitz.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["Chinh phục pháo đài Chyhyryn", "a17cedd0"], "d": ["Sau cuộc hành quân không kết quả của Melek Ibrahim Pasha năm trước, đại tể tướng Merzifonlu Kara Mustafa Pasha đích thân chỉ huy, vây pháo đài kiên cố Chyhyryn (19/21 tháng 7) và chiếm được ngày 21 tháng 8. Việc pháo đài, biểu tượng cuộc cạnh tranh Ottoman - Nga đối với chính quyền hetman Cossack ở Ukraina, thất thủ đã buộc Nga phải hòa. Thành công này cũng là một trong những nguồn gốc sự tự tin đưa Merzifonlu hướng đến Vienna.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["Hiệp ước Bakhchysarai — hòa bình chính thức đầu tiên với Nga", "df82bc0b"], "d": ["Kết thúc các cuộc đàm phán do khan Crimea làm trung gian sau các chiến dịch Chyhyryn, Nhà nước Ottoman và Nga ký hòa ước hai mươi năm, lấy sông Dnieper (Özü) làm biên giới. Vì là hiệp ước toàn diện đầu tiên giữa hai nước, nó được coi là văn kiện khởi đầu quan hệ Ottoman - Nga. Nhờ hòa bình, mặt trận phía đông được bảo đảm, quân đội có thể chuyển hướng sang Trung Âu.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["Trao chiếu phong vương quốc Trung Hungary cho Imre Thököly", "3cd8d51d"], "d": ["Imre Thököly, quý tộc Hungary theo đạo Tin Lành nổi dậy chống sức ép Habsburg, từ tháng 4 năm 1682 bắt đầu được coi là 'vua được bầu của Trung Hungary', và ngày 16 tháng 9, beylerbey Buda là Ibrahim Pasha trao cho ông các biểu trưng của bậc vương công. Như vậy, một nhà nước Hungary chư hầu mới được lập dưới sự bảo hộ của Ottoman. Sự can thiệp này khiến chiến tranh với Áo không thể tránh khỏi, khởi động chuỗi sự kiện dẫn đến cuộc vây hãm Vienna lần thứ hai năm sau.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["Mất Lefkada (Ayamavra) vào tay Venezia", "e6905fee"], "d": ["Hạm đội Venezia, nước đã gia nhập Liên minh Thần thánh, sau khi pháo kích thành phố đã chiếm đóng đảo Lefkada trên biển Ionia. Cùng năm, Preveza cũng thất thủ, phá vỡ quyền kiểm soát của Ottoman ở cửa biển Adriatic. Những tổn thất này là bước khởi đầu của cuộc hành quân trong đó Morosini sẽ chiếm toàn bộ Morea trong vòng ba năm.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["Mất Koroni vào tay Venezia", "2ed762bc"], "d": ["Quân Venezia do Morosini chỉ huy đã chiếm pháo đài Koroni ở mũi tây nam bán đảo Morea; từ đó thành phố ở dưới quyền cai quản của Venezia ba mươi năm. Việc Koroni thất thủ là thành quả lớn đầu tiên trong chiến dịch của Venezia nhằm chinh phục Morea. Mãi đến năm 1715, quân đội Ottoman do Silahdar Ali Pasha chỉ huy mới lấy lại được pháo đài.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["Lấy lại Athens — Venice rút lui", "03393b46"], "d": ["Morosini, người vào tháng 9 năm 1687 pháo kích Acropolis và làm nổ tung đền Parthenon, sau khi qua mùa đông ở Athens đã nhận ra không thể trụ lại trong thành phố. Trước dịch hạch, khó khăn tiếp tế và việc lực lượng Ottoman củng cố lại, đội đồn trú Venice bỏ thành phố và rút về Morea. Athens như vậy trở lại quyền cai quản của Ottoman mà không cần giao chiến, nhưng sự tàn phá mà đền Parthenon phải chịu thì không thể đảo ngược.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["Lipova (Lippa) đầu hàng Caraffa — rơi vào tay Áo", "7f0a8d38"], "d": ["Sau cuộc vây hãm ba ngày của Antonio Caraffa, Lipova đầu hàng trong khoảng 12–22 tháng 6 năm 1688 và rơi vào tay Áo. Sau đó người Ottoman lấy lại thành phố, Áo chiếm lại năm 1691; trong chiến dịch năm 1695, Ottoman lại giành quyền kiểm soát. Các điểm định cư khác trên bản đồ chuyển từ Ottoman sang Habsburg cùng ngày: Arad và Világos (Șiria). Với Arad, nguồn chỉ nêu năm (MKL, Arad: nằm trong tay Ottoman giữa 1551 và 1688); ngày được lấy từ Lipova, còn Világos đi theo chuỗi của Arad (xấp xỉ có công bố). Các pháo đài Lugos (Lugoj) và Karánşebeş (Caransebeş) cũng chuyển sang Áo vào cuối tháng 6 (Bánlaky 0016/1302 'Jenővel elveszett Lugos és Karánsebes'; 0017/1443 'június végén').", "2c8131d4"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["Đẩy lui cuộc vây hãm Negroponte của Venezia", "aae7e6a0"], "d": ["Sau khi chiếm Morea, Morosini hướng sang biển Aegea và tìm cách lấy Negroponte bằng cuộc vây hãm kéo dài hơn ba tháng; nhưng trước công sự được gia cố trong mùa đông 1687-1688 và sự kháng cự của quân trấn thủ, ông phải rút lui với tổn thất nặng. Thất bại này chặn đứng bước tiến của Venezia ở Aegea và làm tổn hại uy tín quân sự của Morosini. Negroponte vẫn ở trong tay Ottoman cả sau Karlowitz.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["Mất pháo đài Kanizsa vào tay Áo", "553b45f3"], "d": ["Bị quân đội Habsburg 60.000 người phong tỏa chặt từ tháng 1 năm 1690, Kanizsa kháng cự nhiều tháng không được tiếp viện, rồi bị mất theo thỏa thuận đầu hàng do vị trấn thủ cuối cùng là Mustafa Pasha ký. Như vậy, quyền thống trị chín mươi năm của Ottoman tại pháo đài gắn với cuộc phòng thủ anh hùng của Tiryaki Hasan Pasha đã chấm dứt. Mất Kanizsa là sự sụp đổ chỗ dựa lớn cuối cùng của Ottoman ở miền tây Hungary.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["Süleyman II qua đời", "d2478080"], "d": ["Süleyman II, được đưa lên ngôi năm 1687 sau khi trải qua khoảng bốn mươi năm trong cảnh giam lỏng kafes, trong lúc đau ốm theo dõi việc chuẩn bị của quân đội, đã qua đời tại Edirne gần trưa thứ Sáu ngày 22 tháng 6 năm 1691; triều đại của ông kéo dài ba năm tám tháng hai ngày. Đại tể tướng đã được chỉ thị trước về việc đưa người em Ahmed lên ngôi nếu sultan qua đời. Lễ cầu nguyện tang cử hành cùng ngày tại đình Alay; thi hài ông được đưa về Istanbul và an táng trong lăng của Sultan Süleyman Lập pháp, ở phía bên phải của vị này.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["Ahmed II lên ngôi", "52947b14"], "d": ["Khi Süleyman II qua đời, người em bốn mươi chín tuổi của ông là Ahmed II lên ngôi tại Edirne. Triều đại ông trùng với những năm nặng nề nhất của các cuộc chiến chống Liên minh Thần thánh; hai tháng sau khi ông lên ngôi, đại tể tướng Fazıl Mustafa Pasha tử trận tại Slankamen. Bù lại, chế độ malikane (cho thầu thuế trọn đời) được áp dụng dưới thời ông trở thành một trong những quy định quan trọng nhất làm thay đổi cơ cấu dài hạn của tài chính Ottoman.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["Mehmed IV qua đời tại Edirne", "17388b7e"], "d": ["Mehmed Thợ Săn (Avcı), bị phế truất năm 1687, được đưa đến Edirne trong chiến dịch Hungary năm 1689 của Süleyman II và chứng kiến cả triều đại của người em khác là Ahmed II. Ông qua đời tại thành phố mà ông rất yêu thích này. Thi hài ông được đưa về Istanbul và an táng trong lăng của mẹ ông, Turhan Sultan, bên cạnh thánh đường Yeni Cami.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["Ahmed II qua đời tại Edirne", "c6306c08"], "d": ["Ahmed II, người có bốn năm trị vì trôi qua trong chiến tranh, qua đời tại Edirne ở tuổi năm mươi hai vì chứng phù (istiska). Thi hài ông được đưa về Istanbul và an táng trong lăng của Sultan Süleyman Lập pháp. Người cháu là Mustafa II kế vị.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["Người Iran chiếm Basra", "a9cdf3a3"], "d": ["Trong khi Đế quốc Ottoman đang bận với các cuộc chiến chống Liên minh Thần thánh ở phía tây, sau trận dịch hạch năm 1690, Basra trước hết bị sheikh bộ lạc Muntafiq là Mani, rồi đến Farajullah, khan của Huwayza, cướp phá. Lợi dụng tình trạng hỗn loạn này, người Iran chiếm thành phố năm 1696 và để lại một viên trấn thủ tại Basra.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["Hiệp ước Istanbul — nhượng Azov cho Nga", "79db4724"], "d": ["Tại Karlowitz, với Nga chỉ đạt được đình chiến hai năm; hòa ước lâu dài được ký ở Istanbul sau một năm rưỡi mặc cả gay go. Nhà nước Ottoman chính thức nhượng cho Nga pháo đài Azov đã mất năm 1696 cùng vùng đất xung quanh, còn khan Crimea từ bỏ khoản cống hằng năm nhận từ Moskva. Đổi lại, Nga được quyền cử sứ thần thường trú tại Istanbul; như vậy, sự hiện diện của Nga ở bờ bắc Biển Đen đã được ghi nhận về pháp lý.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Daltaban Mustafa Pasha lấy lại Qurna và Basra", "7adb777d"], "d": ["Daltaban Mustafa Pasha, được bổ nhiệm làm tổng đốc Baghdad và tổng chỉ huy Basra sau Hiệp ước Karlowitz, tiến về phía nam với lực lượng của Aleppo, Raqqa, Sivas và Karaman cùng một hạm đội sông đi xuống từ Birecik. Các sheikh bộ lạc trong vùng lần lượt quy phục, viên trấn thủ Basra của Iran là Davud Khan bỏ thành phố, và Qurna cùng Basra lại thuộc quyền cai quản của Ottoman.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["Mustafa II qua đời", "626c394d"], "d": ["Mustafa II, người đã nhường ngôi cho người em Ahmed III sau Sự biến Edirne, qua đời tại thành phố Edirne mà ông rất yêu thích, khoảng năm tháng sau khi bị phế truất. Nỗi buồn về những diễn biến cuối cùng đã chồng thêm lên bệnh tật của ông. Một số nguồn phương Tây viết rằng trong dân chúng phổ biến niềm tin ông đã bị đầu độc.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Chế độ cai trị Mamluk (Kölemen) bắt đầu ở Baghdad", "abe52618"], "d": ["Với việc Hasan Pasha gốc Gruzia được cử làm tổng đốc Baghdad, ở Iraq mở ra thời kỳ mà thay cho các tổng đốc được trung ương bổ nhiệm, một tầng lớp cai trị xuất thân từ chính nô lệ của họ nắm quyền. Từ khi Süleyman Pasha làm tổng đốc năm 1749, hệ thống bén rễ chắc chắn, và Sublime Porte giờ không còn bổ nhiệm được người mình muốn mà buộc phải bổ nhiệm một trong các Mamluk đã nắm được ảnh hưởng. Cơ cấu bán tự trị này tuy hữu ích trong việc phòng thủ biên giới Iran nhưng suốt một thế kỷ rưỡi đã làm suy yếu sự kiểm soát của quyền uy trung ương đối với Iraq.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Triều đại Husaynid được lập ở Tunis", "cb1a98f9"], "d": ["Trong khoảng trống quyền lực sinh ra khi quân Algiers xâm chiếm Tunis, Husayn b. Ali, agha kỵ binh sipahi gốc Thổ, nắm lấy tiểu quốc và, bằng việc tuyên bố trung thành với sultan Ottoman, giành được tính chính danh. Triều đại do ông lập cai trị Tunis trong các giai đoạn 1705-1735 và 1756-1957; chế độ của đạo đồn trú nhường chỗ cho một trật tự bey cha truyền con nối. Như vậy, trong các xứ đồn trú phương Tây đã ra đời ví dụ đầu tiên về cơ cấu triều đại trực thuộc trung ương nhưng thực tế tự trị.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Lấy Oran và Mers el-Kébir từ tay người Tây Ban Nha", "b67ce06a"], "d": ["Lực lượng của beylerbey thuộc đạo đồn trú Algiers, sau một cuộc vây hãm dài, đã chiếm Oran cùng hải cảng Mers el-Kébir, nằm trong tay quân trú phòng Tây Ban Nha suốt hai thế kỷ. Đây là thành công lớn nhất mà các xứ đồn trú phương Tây được Ottoman bảo hộ giành được trước Tây Ban Nha ở Tây Địa Trung Hải, và nó bảo đảm sườn phía tây của Algiers. Năm 1732, thành phố lại bị Tây Ban Nha chiếm đóng, chỉ đến năm 1792 mới được lấy lại dứt khoát.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Hiệp ước Pruth — lấy lại Azov và Taygan", "bac5d2a1"], "d": ["Hiệp ước bảy điều ký khi quân Nga bị vây dọc sông Pruth đầu hàng quy định trả lại pháo đài Azov cho Ottoman cùng với đất đai và đạn dược. Các công sự Taygan, Kamenka và Yenikale phải bị phá bỏ, và các bên không được xây pháo đài mới trong những vùng này. Hệ thống hạm đội và căn cứ mà Pyotr I gây dựng suốt mười sáu năm ở Voronezh và Azov sụp đổ; đà tiến xuống Biển Đen của Nga bị chậm lại khoảng năm mươi năm.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Triều đại Karamanli được lập ở Tripoli (Libya)", "e1105d4a"], "d": ["Ở Tripoli, nơi khốn đốn vì tranh chấp giữa các agha đồn trú, sĩ quan kỵ binh Ahmed Karamanli nắm chính quyền và hợp thức hóa địa vị bằng chiếu phong beylerbey nhận từ Istanbul. Qua Ahmed Pasha, con trai ông là Mehmed Pasha và cháu là Yusuf Pasha, hình thành một triều đại kéo dài từ 1711 đến 1835; xuất hiện một cơ cấu bán độc lập tự lập hạm đội và trực tiếp ký hiệp ước với các nước châu Âu. Thời kỳ này chỉ chấm dứt năm 1835, khi tỉnh được đặt trực thuộc trung ương.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Hiệp ước Edirne với Nga", "14901a70"], "d": ["Vì những lời hứa tại Pruth không được thực hiện, chiến tranh lại được tuyên bố thêm hai lần; cuối cùng, khi người Nga chấp nhận các cam kết, hòa bình lâu dài được ký tại Edirne. Hiệp ước xác nhận các điều khoản Pruth; Nga sẽ không can dự vào công việc của Ba Lan, rút khỏi đất của người Cossack và không cản trở vua Thụy Điển Charles XII trở về nước. Việc mặt trận phía bắc khép lại như vậy giúp Nhà nước Ottoman quay sang mặt trận Morea và Venezia. Các nơi khác được sáp nhập vào cùng ngày: Khotyn.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Tuyên chiến với Venezia — chuẩn bị chiến dịch Morea", "d970b122"], "d": ["Với lý do Venezia ủng hộ quân nổi dậy Montenegro, tịch thu tàu buôn Ottoman và đè nặng sưu thuế lên Morea mà họ chiếm được theo Karlowitz, Divan quyết định tuyên chiến. Chiến dịch do đại tể tướng Silahdar Damad Ali Pasha chuẩn bị sẽ kết thúc vào năm sau bằng việc thu hồi toàn bộ bán đảo Morea trong chưa đầy một trăm ngày. Tuy nhiên, thành công này sẽ khiến Áo ra tay và mở cửa cho một cuộc chiến nặng nề hơn nhiều vào năm 1716.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["Tinos (İstendil): đảo cuối cùng của Venice ở biển Aegea đầu hàng", "4abec891"], "d": ["Hạm đội lên đường cho chiến dịch Morea đã thả neo trên đường đi trước Tinos, hòn đảo duy nhất Venice còn giữ ở biển Aegea. Tuy Công quốc Naxos đã sụp đổ năm 1566, hòn đảo nhờ dân cư Latinh vẫn mang cờ Venice thêm một trăm năm mươi năm; nay sau cuộc vây hãm ngắn, nó đầu hàng mà không đổ máu. Như vậy dấu chân cuối cùng của Venice ở biển Aegea bị xóa sạch, và vùng biển này hoàn toàn trở thành biển nội địa của Ottoman.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["Chinh phục Nauplion — pháo đài then chốt của Morea", "62a5808a"], "d": ["Nauplion, thủ phủ của Venice ở Morea và là công sự mạnh nhất của họ, đã thất thủ khi đồn lũy Palamidi bị chiếm sau chín ngày pháo kích. Việc pháo đài bị chiếm nhanh chóng như vậy đã bẻ gãy sự kháng cự ở phần còn lại của bán đảo. Việc lấy lại Morea mất tại Karlowitz trên thực tế hoàn tất ở đây. Điểm định cư khác trên bản đồ chuyển từ Venice sang Ottoman cùng ngày: Argos — đi theo chuỗi trung tâm chủ quản của Nauplion (TDV anabolu; xấp xỉ có công bố).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["Methoni đầu hàng", "43faa909"], "d": ["Sau khi Nauplion thất thủ, pháo đài Methoni ở mỏm tây nam Morea bị quân đội trên bộ và hạm đội trên biển vây hãm, và đầu hàng sau một thời gian ngắn. Hải cảng mà Venice dùng suốt hai trăm năm trong các chuyến đi đông Địa Trung Hải này là điểm ghé bắt buộc để tàu lấy nước và lương thực. Mất nó, hạm đội Venice không còn khả năng cơ động ở biển Aegea.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["Koroni đầu hàng — hoàn tất chiến dịch Morea", "e4b9c8a4"], "d": ["Với việc pháo đài Koroni trấn giữ cửa vịnh Messenia đầu hàng, quyền cai trị của Venice trên bán đảo Morea chấm dứt hoàn toàn. Bán đảo mất tại Karlowitz đã được lấy lại toàn bộ chỉ ba tháng sau khi chiến dịch mở màn. Tiếp theo trong cùng chiến dịch, vào tháng 9 năm 1715, đảo Lefkada (Ayamavra) ở biển Ionia cũng được lấy từ Venice. Tốc độ này buộc Venice phải lôi Áo vào cuộc chiến, và ba năm sau mở ra con đường đến Passarowitz.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["Chiếm đảo Kythira (Cerigo)", "494de6c6"], "d": ["Đảo Kythira ở mỏm phía nam Morea đã được hạm đội tiếp nhận sau khi việc chiếm bán đảo hoàn tất. Hòn đảo canh giữ lối đi giữa biển Ionia và biển Aegea là tiền đồn mà Venice dùng để kiểm soát vùng biển này. Tuy nhiên, nó không ở lại trong tay Ottoman: ba năm sau, tại Passarowitz, nó được trả lại cho Venice.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Áo và Venezia lập liên minh — mở cửa cho chiến tranh Ottoman - Áo 1716-1718", "99511ca2"], "d": ["Sau khi Ottoman lấy lại Morea từ Venezia, Áo, viện cớ Hiệp ước Karlowitz bị vi phạm, đã ký hiệp ước liên minh với Venezia; trong thư gửi đại tể tướng, Vương công Eugène đòi trả lại những nơi đã lấy của Venezia. Trong cuộc nghị bàn tại doanh trại Davutpaşa, dưới sức ép của đại tể tướng Ali Pasha, chiến tranh được tuyên bố với Áo, và để làm việc đó, một fatwa được xin từ sheikh al-Islam.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["Đại tể tướng Ali Pasha mở chiến dịch đánh Áo", "2fbdce42"], "d": ["Sau khi tuyên chiến với Áo, tổng tư lệnh (serdar-ı ekrem) Ali Pasha xuất chinh đánh Áo với đạo quân hơn 100.000 người; còn hạm đội hướng đến Corfu trong cùng mùa hè. Quân đội sẽ tiến từ Belgrade đến Petrovaradin, và đại tể tướng sẽ tử trận trong thất bại đầu tháng 8.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Thất bại Petrovaradin (Varadin) — Damad Ali Pasha tử trận", "265c1d81"], "d": ["Vượt sông Danube qua Belgrade, quân đội Ottoman đụng độ trước Petrovaradin với lực lượng Áo do Vương công Eugène chỉ huy; tuy đợt xung phong đầu tiên của Janissary đã uy hiếp chiến hào địch, hàng ngũ tan rã khi cánh kỵ binh sụp đổ. Đại tể tướng Silahdar Damad Ali Pasha bị bắn vào trán và tử trận, toàn bộ doanh trại và pháo binh rơi vào tay địch. Thất bại này, được các biên niên sử Ottoman nhắc đến là 'năm Varadin', là mắt xích đầu tiên trong chuỗi dẫn đến việc mất Temesvár và, năm sau, mất Belgrade.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Cuộc vây hãm Corfu thất bại", "b2aa7011"], "d": ["Serasker Morea là Kara Mustafa Pasha từ trên bộ, đại đô đốc Canım Hoca Mehmed Pasha cùng hạm đội từ phía biển, dồn sức đánh Corfu; đảo này là căn cứ then chốt của Venezia ở Adriatic. Nhưng công sự cực kỳ vững chắc của pháo đài, viện binh do hạm đội Venezia đưa đến và tin bại trận từ mặt trận sông Danube đã dẫn đến việc dỡ bỏ vòng vây. Việc không lấy được Corfu đã dập tắt khí thế đang dâng lên nhờ tái chinh phục Morea và chuyển trọng tâm cuộc chiến sang Hungary.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Mất Temeşvar (Timişvar) vào tay Áo", "27fe1365"], "d": ["Sau thảm bại tại Varadin, Hoàng thân Eugène tiến thẳng đến Temeşvar, và sau cuộc vây hãm kéo dài hơn bốn mươi ngày, pháo đài đã được giao nộp theo thỏa thuận đầu hàng. Thành phố được chinh phục năm 1552 dưới triều Süleyman Lập pháp và suốt 164 năm, với tư cách trung tâm của một beylerbeylik (tỉnh do tổng đốc beylerbey cai quản), được coi là trụ cột phía đông của phòng tuyến Hungary, đã bị mất như vậy. Với sự thất thủ của Temeşvar, toàn bộ vùng Banat thuộc về Áo và biên giới Ottoman bị đẩy xuống phía nam sông Danube. Các điểm định cư khác trên bản đồ chuyển từ Ottoman sang Habsburg cùng ngày: Csákóvár, Facset và Karánşebeş (Caransebeş) — cùng với việc chuyển giao tỉnh eyalet Temeşvar (TDV timisvar; nguồn không ghi ngày ở cấp địa điểm, chuỗi trung tâm chủ quản, xấp xỉ có công bố).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Pháo đài Haram (Yeni Palanka) giao nộp cho Áo — Ottoman mất dải bờ sông Danube của Banat", "38ee4c6d"], "d": ["Sau khi Temeşvar thất thủ, tướng kỵ binh Áo Mercy, được giao nhiệm vụ đánh chiếm phần còn lại của Banat, ngày 14 tháng 11 tiến đến Haram (Yeni Palanka) bên bờ sông Danube; khi ông tới pháo đài vào ngày 16 tháng 11, đội đồn trú Ottoman gồm 200 người đã kéo cờ trắng và đầu hàng với điều kiện được tự do rút lui. Như vậy tuyến sông Danube của Nam Banat, do Ottoman nắm giữ từ năm 1552, cũng thuộc về Áo. Điểm định cư khác trên bản đồ chuyển từ Ottoman sang Habsburg cùng ngày: Versec — đi theo chuỗi trung tâm chủ quản của Haram (Bánlaky 0019/1703; xấp xỉ có công bố).", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["Hiệp ước Passarowitz — giữ được Morea, mất Belgrade và Banat", "d46aa216"], "d": ["Morea đã được lấy lại từ Venice, nhưng Áo, sau khi tham chiến, đã chiếm thế thượng phong trên bàn đàm phán nhờ những chiến thắng tại Petrovaradin và Belgrade. Hiệp ước ký với sự trung gian của Anh và Hà Lan để Morea lại cho Ottoman, bù lại Belgrade cùng miền Bắc Serbia, Banat và Tiểu Wallachia bị nhượng cho Áo; theo lời TDV, “miền Bắc Bosnia bị để hoàn toàn cho Áo” — trên bản đồ, từ ngày này các pháo đài dọc sông Sava như Bosanska Dubica và Bosanski Brod chuyển sang Áo (đường biên chính xác do các ủy viên vạch từng đoạn, TDV không nêu tên các pháo đài này); còn Venice giữ các vị trí của mình trên bờ biển Ionia như Preveza và Kythira. Theo hiệp ước thương mại ký cùng ngày, thuế quan đánh vào hàng hóa Áo được giảm từ năm xuống ba phần trăm. Hiệp ước, trong khi xác nhận sự thoái lui của Đế quốc Ottoman ở Trung Âu, đã mở ra nền hòa bình hai mươi bảy năm, tạo nền cho Thời kỳ Hoa Tulip (1718–1730): nhà in Ottoman đầu tiên (1727, İbrahim Müteferrika) dưới sự điều hành của Nevşehirli Damat İbrahim Pasha, các hội đồng dịch thuật, những quan sát về việc chủng đậu và một đời sống cung đình – văn hóa mới là sản phẩm của những năm hòa bình này. Các điểm định cư khác đổi chủ cùng ngày trên bản đồ: Craiova, Râmnicu Vâlcea và Turnu Severin (Tiểu Wallachia/Oltenia, từ Ottoman sang Áo) cùng Lefkada (Ayamavra) (từ Ottoman sang Venice; TDV ayamavra: năm 1718 theo Hiệp ước Passarowitz đảo bị nhượng cho Venice). Ở Tiểu Wallachia, Târgu Jiu cũng chuyển sang Áo; Vonitsa (TDV pasarofca-antlasmasi) và đảo Kythira (Cerigo, TDV cuka-adasi: điều 3 của Passarowitz) chuyển sang Venice.", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Chiến dịch phía đông: chiếm Tbilisi và khởi đầu chiến tranh với Iran", "78343dc2"], "d": ["Khi nhà nước Safavid sụp đổ trước cuộc xâm lược của người Afghan và Nga tiến xuống bờ biển Caspi, Đế quốc Ottoman đã điều quân sang phía đông để khoảng trống quyền lực không rơi hoàn toàn vào vòng ảnh hưởng của Nga. Tbilisi bị chiếm và Gruzia được đặt dưới sự cai quản của Ottoman; sau đó cuộc tiến quân tiếp tục theo hướng Ganja, Yerevan và Nakhchivan. Được tiến hành sau vẻ ngoài hiếu hòa của Thời kỳ Hoa Tulip, chiến dịch này mở đầu cho một cuộc phiêu lưu dài ở phía đông, kéo dài mười ba năm và kết thúc bằng việc trả lại mọi vùng đất đã giành được.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["Chiến dịch Iran 1723: tiến vào Shirvan và Gruzia", "c81189fc"], "d": ["Khi nhà nước Safavid sụp đổ trước cuộc xâm lược của người Afghan, một chiến dịch sang phía đông được mở ra với lý do ngăn Nga tiến xuống bờ biển Caspi. Đạo quân Erzurum đi qua Gruzia tiến đến Tbilisi, còn cánh quân Shirvan vào Shamakhi, lấy lại những vùng đất đã mất một trăm ba mươi năm trước. Chiến dịch này là bước tiến lớn cuối cùng của Ottoman ở Kavkaz.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["Chiếm Kermanshah — cửa ngõ Zagros", "ad14799f"], "d": ["Đạo quân Baghdad vượt các đèo Zagros và chiếm Kermanshah, được coi là cửa ngõ phía tây của Iran. Thành phố nằm trên đường thương đội và hành quân từ Baghdad đi Isfahan, và việc chiếm nó bảo đảm an ninh phía đông cho tỉnh Iraq. Đà tiến này khởi đầu cuộc đua chia phần giữa Ottoman và Nga trên xứ Safavid đang tan rã.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Hiệp ước phân chia Istanbul — Iran bị chia cắt với Nga", "fce8eec2"], "d": ["Nhằm ngăn Ottoman và Nga đối đầu nhau trên lãnh thổ Safavid đang sụp đổ, một hiệp ước phân chia đã được ký với sự trung gian của đại sứ Pháp. Bờ phía tây và phía nam biển Caspi thuộc về Nga; Gruzia, Shirvan, Azerbaijan và các thành phố ở miền Tây Iran thuộc về Đế quốc Ottoman. Sự phân chia này trên giấy tờ có vẻ là một món lợi lớn, nhưng chẳng bao lâu sau trên thực tế đã mất hiệu lực trước sự trỗi dậy của Nadir Shah. Theo hiệp ước, những vùng đất màu mỡ của Shirvan như Shabran và Müşkür được để lại về phía Nga (Çaycıoğlu, DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["Chiếm Nakhchivan", "bdf14d0a"], "d": ["Lực lượng Ottoman tiến dọc sông Aras đã chiếm Nakhchivan và Ordubad; Julfa cũng được nhập vào liva Nakhchivan. Thành phố, cửa ngõ tây bắc của Iran, được gắn vào tỉnh Yerevan mới lập. Như vậy biên giới Ottoman lại đạt đến đường ranh xa nhất về phía đông thời Kanunî.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["Chinh phục Hamadan", "e1339a97"], "d": ["Quân đội tiến từ Kermanshah về phía đông đã chiếm Hamadan, ở ngưỡng phía tây cao nguyên Iran, sau một cuộc vây hãm kéo dài. Thành phố là trạm lớn cuối cùng trên đường đi Isfahan, hướng xa nhất về phía đông mà quân đội Ottoman có thể vươn tới kể từ Chiến dịch Hai xứ Iraq. Cùng năm đó, công ước Istanbul ký với Nga đã đưa lên giấy việc Ottoman và Nga chia nhau Iran đang tan rã.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["Tái chinh phục Yerevan", "88acabef"], "d": ["Sau cuộc vây hãm ác liệt kéo dài chín mươi ngày, Yerevan, pháo đài then chốt của thung lũng sông Aras, lại thuộc quyền cai quản của Ottoman. Pháo đài được xây năm 1583 và mất năm 1604, lần này được củng cố bằng đội đồn trú mạnh hơn. Cuộc vây hãm kéo dài cho thấy quân đội Ottoman không còn tiến dễ dàng nữa. Các nahiye Karpi (Üçkilise), Sharur, Maku và Shuragel cũng được gắn vào tỉnh Yerevan.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["Đánh chiếm Tabriz — Azerbaijan bị thôn tính", "e502a4f7"], "d": ["Sau nỗ lực bất thành một năm trước đó, Tabriz bị vây hãm lần nữa và đã đầu hàng quân đội Ottoman sau trận chiến ác liệt giành giật từng con phố. Marand, Maragheh và Savojbolagh (Mahabad) trực thuộc tỉnh Tabriz cũng rơi vào quyền cai quản của Ottoman. Cùng năm đó, Lori, Ganja, Ardabil và Khorramabad cũng bị chiếm, qua đó các vùng thuộc phần của Ottoman theo Hiệp ước phân chia Istanbul đã bị chiếm đóng trên thực tế. Phạm vi đạt được ở phía đông là đường biên giới tiến xa nhất kể từ thời Hiệp ước Ferhad Pasha; tuy nhiên việc giữ được nó đã đặt gánh nặng lớn lên quân đội và ngân khố.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["Chinh phục Ganja — kết thúc chiến dịch Kavkaz", "875bca7a"], "d": ["Ganja, mục tiêu cuối cùng của chiến dịch Kavkaz, đã được tiếp nhận với tư cách trung tâm của Karabakh giữa sông Kura và sông Aras. Khi tuyến Shirvan, Yerevan, Nakhchivan và Ganja được hoàn tất, Đế quốc Ottoman đạt phạm vi ở Kavkaz như năm 1590. Tuy nhiên, thành quả này tồn tại ngắn ngủi: sự trỗi dậy của Nadir Shah sẽ lấy lại toàn bộ vùng trong vòng mười năm.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Hiệp ước Hamadan — Miền Tây Iran sáp nhập vào Ottoman", "94a29dc3"], "d": ["Hiệp ước ký với vua Afghan Ashraf Shah đã chấm dứt cuộc chiến kéo dài bốn năm, và các lãnh thổ miền Tây Iran do Đế quốc Ottoman chiếm đóng được công nhận về mặt pháp lý. Đổi lại, Ashraf Shah thừa nhận tước vị caliph của sultan Ottoman và cam kết cho đọc bài giảng khutba ở Iran nhân danh sultan. Thắng lợi ngoại giao này chỉ tồn tại ngắn ngủi; cuộc phản công do Nadir Shah phát động năm 1730 đã quét sạch những thành quả của hiệp ước chỉ trong vài năm.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Hekimoğlu Ali Pasha chiếm Urmia", "eac7f64d"], "d": ["Trong chiến dịch Iran, Hekimoğlu Ali Pasha trước tiên chiếm Urmia, sau đó ngày 15 tháng 11 năm 1731 chiếm Tabriz, vốn đã được bỏ trống cho Ottoman. TDV không nêu ngày chiếm Urmia; chỉ biết năm và biết rằng sự kiện này diễn ra trước Tabriz.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Hiệp ước Ahmed Pasha — Trả lại phần lớn miền Tây Iran", "590d839f"], "d": ["Trước chiến thắng của Nadir Shah tại Malayer và các cuộc tiến công liên tiếp của Iran, tổng đốc Baghdad là Ahmed Pasha đã ký một văn bản hòa bình mà không tham vấn triều đình trung ương. Theo hiệp ước, sông Aras được chấp nhận làm biên giới; các thành phố miền Tây Iran như Hamadan, Kermanshah, Ardalan, Ardabil và Tabriz được trả lại cho Iran, còn Ganja và Tbilisi vẫn thuộc Ottoman. Văn bản này bị phản đối ở Istanbul, đồng thời Nadir Shah cũng cho là chưa thỏa đáng, và chiến tranh bùng phát trở lại khi năm 1732 còn chưa kết thúc. Bản đồ cũng tính Kotur, nơi đi theo chuỗi của Khoy, chuyển từ Ottoman sang Safavid vào ngày này (TDV hoy; nguồn không có ngày riêng cho Kotur — xấp xỉ có công bố).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["Oran (Vahran) lại rơi vào tay Tây Ban Nha", "20485027"], "d": ["Hạm đội đổ bộ lớn do vua Tây Ban Nha Felipe V phái đi, dưới quyền chỉ huy của Bá tước Montemar, đã đến trước Oran, đánh tan lực lượng của quân đoàn đồn trú Ottoman tại Algiers và chiếm lại thành phố. Hải cảng được chinh phục hai mươi bốn năm trước đó sẽ lại nằm trong tay đội đồn trú Tây Ban Nha suốt sáu mươi năm. Tổn thất này cho thấy giới hạn sức mạnh của các quân đoàn đồn trú Ottoman ở Bắc Phi tại tây Địa Trung Hải, và mãi đến cuộc chinh phục dứt điểm Oran năm 1792 mới được bù đắp.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Cải tổ Quân đoàn Pháo thủ đạn nổ theo kiểu châu Âu và thành lập Humbarahane", "d980cf2a"], "d": ["Humbaracı Ahmed Pasha, một người gốc Pháp vào phục vụ Ottoman, được Đại tể tướng Hekimoğlu Ali Pasha ủng hộ, đã tổ chức lại quân đoàn pháo thủ đạn nổ (humbaracı) thành một đơn vị có lương, được xếp đặt theo kiểu châu Âu. Ba trăm binh sĩ tuyển mộ từ Bosnia được huấn luyện chính quy dựa trên số học và hình học; các quy chế mới về tổ chức, trang bị và hưu trí được soạn thảo, và một trăm khẩu pháo bắn đạn nổ cùng năm mươi nghìn quả đạn nổ được chế tạo bằng kỹ thuật đương thời. Humbarahane, nơi giảng dạy hình học, được coi là hạt nhân đầu tiên của nền đào tạo kỹ thuật quân sự hiện đại ở Đế quốc Ottoman.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["Ahmed III qua đời", "455f7fba"], "d": ["Ahmed III, bị phế truất năm 1730 trong cuộc nổi loạn Patrona Halil, đã trải qua sáu năm cuối đời trong khu phòng của cung Topkapı dành cho các sultan bị phế truất, và qua đời ở tuổi sáu mươi ba. Ông được an táng trong lăng của bà nội Turhan Sultan bên cạnh thánh đường Yeni Cami ở Bahçekapı.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Hiệp ước Istanbul — Nhượng Nam Kavkaz cho Iran", "8c205aab"], "d": ["Cuộc chiến thứ hai với Iran kéo dài bốn năm đã kết thúc bằng hiệp ước ký sau thảm bại Arpaçay và việc mất Ganja cùng Tbilisi. Đế quốc Ottoman rút khỏi toàn bộ lãnh thổ Nam Kavkaz và miền Tây Iran đã chiếm từ năm 1723, và biên giới trở về đường ranh Kasr-ı Şirin năm 1639. Mười ba năm chiến dịch ở phía đông chỉ để lại gánh nặng tài chính lớn và một ngân khố trống rỗng; bù lại, việc đóng được mặt trận phía đông là lợi ích sống còn cho cuộc chiến mới bắt đầu với Nga.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Pháo đài Ochakov (Özi) rơi vào tay Nga", "f93e61f3"], "d": ["Quân đội Nga dưới quyền Thống chế Münnich vây hãm pháo đài Ochakov ở cửa sông Dnieper; khi kho đạn phát nổ, hệ thống phòng thủ sụp đổ và pháo đài thất thủ với tổn thất nhân mạng lớn. Việc mất Ochakov, được coi là ổ khóa của bờ tây bắc Biển Đen, đã mở đường đến Crimea cho người Nga và gây hoảng loạn lớn ở Istanbul. Năm sau, do dịch bệnh và khó khăn tiếp tế, người Nga bỏ pháo đài, và nó trở lại với Ottoman.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Chiến thắng Banja Luka — Giải cứu Bosnia", "f603865a"], "d": ["Khi lực lượng Áo tiến vào Bosnia và vây hãm Banja Luka, tổng đốc Bosnia Hekimoğlu Ali Pasha đã đến ứng cứu với lực lượng tập hợp từ cư dân địa phương và giáng cho kẻ địch đông hơn một thất bại nặng nề. Chiến thắng này làm sụp đổ kế hoạch chiếm Bosnia của Áo ngay từ nước đi đầu tiên, và miền bắc của tỉnh được thu hồi hoàn toàn. Banja Luka là một trong những bước ngoặt vực dậy tinh thần của quân đội Ottoman vốn liên tục thoái lui trước Áo sau năm 1683.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["Chiến thắng Grocka (Hisarcık) — Mở đường đến Belgrade", "2101cdff"], "d": ["Quân đội Áo tiến lên để bảo vệ Belgrade đã bị phục kích ở dải đèo hẹp bên bờ sông Danube và chịu tổn thất nặng trong trận đánh kéo dài suốt ngày. Trong khi lực lượng của Thống chế Wallis rút lui hỗn loạn về Belgrade, quân đội Ottoman áp sát trước pháo đài và bắt đầu vây hãm. Grocka là chiến thắng dã chiến dứt khoát nhất giành được trước Áo kể từ Karlowitz và trực tiếp đưa đến việc thu hồi Belgrade.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Hiệp ước Niš — Hòa bình với Nga, trung lập hóa Azov và chấm dứt các cuộc tập kích từ Crimea", "674f974e"], "d": ["Bị đơn độc khi Áo chấp nhận hòa bình tại Belgrade, Nga buộc phải kết thúc chiến tranh với sự trung gian của đại sứ Pháp Villeneuve. Công sự của pháo đài Azov bị phá hủy và vùng này được tuyên bố là đất trung lập giữa hai nước; Nga chấp nhận điều kiện không duy trì tàu chiến và tàu buôn trên Biển Đen. Như vậy mục tiêu vươn ra biển của Nga bị trì hoãn thêm một thế hệ, và đây là lần cuối cùng trong thế kỷ 18 Đế quốc Ottoman rời bàn đàm phán với phần lợi.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Ochakov trở về sau thời kỳ Nga chiếm đóng: theo hòa ước 1739, pháo đài được giao lại sau khi bị phá hủy công sự", "7ecc2bef"], "d": ["Người Nga đã chiếm Ochakov ngày 11 tháng 7 năm 1737. Theo hòa ước ký với Nga năm 1739, pháo đài được giao trả cho người Ottoman sau khi các công sự bị phá hủy; Ottoman nắm giữ Ochakov đến năm 1788, trước Hiệp ước Jassy.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["Phòng thủ Mosul — Đẩy lui Nadir Shah", "c03ffbc1"], "d": ["Sau khi chiếm Kirkuk và Erbil rồi tiến đến trước Mosul, Nadir Shah đã nã pháo vào thành phố suốt bốn mươi ngày và liên tiếp mở các đợt tổng công kích. Cuộc phòng thủ do tổng đốc Hüseyin Pasha al-Jalili chỉ huy, với việc vũ trang cả cư dân thành phố, đã buộc quân đội Iran phải giải vây sau khi chịu tổn thất nặng nề. Việc Mosul trụ vững đã ngăn toàn bộ Iraq bị mất và củng cố ảnh hưởng của dòng họ Jalili tại thành phố suốt một thế kỷ.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["Liên minh Diriyah — Thành lập Tiểu vương quốc Saud thứ nhất ở Najd", "188751bf"], "d": ["Emir Muhammad ibn Saud, người che chở cho học giả Muhammad ibn Abd al-Wahhab bị trục xuất khỏi Uyayna và đến Diriyah, đã lập với ông một liên minh đặt quyền lực chính trị vào việc phục vụ công cuộc truyền bá tôn giáo. Thỏa thuận này mở ra một trang sử mới cho dòng họ Saud và thống nhất các tiểu quốc ốc đảo rải rác ở Najd quanh một phong trào duy nhất. Trong vòng nửa thế kỷ, thế lực sẽ vươn tới Karbala, Mecca và Medina này buộc Đế quốc Ottoman phải bảo vệ quyền thống trị của mình ở Hejaz.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Hiệp ước Kerden — Kết thúc các cuộc chiến Ottoman – Iran", "1d3a919e"], "d": ["Hiệp ước ký sau cuộc chiến cuối cùng kéo dài bốn năm đã tái xác nhận nguyên vẹn đường biên giới Kasr-ı Şirin năm 1639; không bên nào giành thêm được lãnh thổ. Yêu cầu dai dẳng của Nadir Shah đòi công nhận phái Ja'fari là trường phái thứ năm không được đáp ứng; bù lại, hai bên quyết định cho người hành hương Iran được tự do đi hajj và trao đổi sứ thần. Như vậy các cuộc chiến Ottoman – Iran kéo dài hơn hai thế kỷ trên thực tế đã khép lại; đường biên giới này phần lớn được giữ nguyên cho đến ngày nay.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["Mahmud I qua đời và Osman III lên ngôi", "30203700"], "d": ["Mahmud I, người trong hai mươi bốn năm trị vì đã thu hồi các lãnh thổ mất theo Hiệp ước Belgrade và ủng hộ cuộc cải tổ Quân đoàn Pháo thủ đạn nổ, qua đời khi trở về sau lễ cầu nguyện thứ Sáu có nghi thức triều đình. Kế vị ông là người em Osman III, người đã sống trong cảnh giam lỏng kafes cho đến năm năm mươi tám tuổi. Một triều đại ngắn ngủi và bất an bắt đầu; dưới thời Osman III, người thay sáu Đại tể tướng trong ba năm, công việc triều chính rơi vào tình trạng trì trệ rõ rệt.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["Osman III qua đời và Mustafa III lên ngôi", "3ac10f85"], "d": ["Sau ba năm trị vì, Osman III qua đời, và Mustafa III, người cởi mở với các ý tưởng cải cách và quan tâm sát sao đến công việc triều chính, lên ngôi. Vị sultan mới dựa vào kinh nghiệm của Đại tể tướng Koca Ragıb Pasha để chấn chỉnh tài chính và canh tân quân đội; đội pháo binh bắn nhanh của Nam tước de Tott được thành lập trong thời kỳ này. Tuy nhiên, cuộc chiến với Nga bước vào năm 1768 sẽ làm lu mờ mọi thành quả của triều đại kéo dài mười bảy năm.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Tuyên chiến với Nga — Sự kiện Balta và khởi đầu chiến tranh 1768–1774", "9c6aabe0"], "d": ["Khi các đơn vị Nga và Cossack truy đuổi Liên minh Bar của Ba Lan tập kích và đốt phá thị trấn Balta ở biên giới Ottoman, Hội đồng Divan quyết định tuyên chiến, và đại sứ Nga bị giam vào pháo đài Yedikule. Cuộc chiến được tiến hành mà không có sự chuẩn bị quân sự nghiêm túc, lại được tuyên bố trước sáu tháng, nên diễn biến xấu ngay từ đầu. Cuộc đối đầu kéo dài sáu năm này, với trận tập kích Çeşme, thảm bại Kagul và việc Crimea bị chiếm đóng, sẽ trở thành một trong những chuỗi thất bại nặng nề nhất trong lịch sử Ottoman.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["Mất pháo đài Khotyn vào tay Nga", "66d43ea4"], "d": ["Hai nỗ lực của quân đội Nga dưới quyền Hoàng thân Golitsyn đã bị đẩy lui, nhưng sau thất bại của Đại tể tướng ở khu vực giữa Kamianets và Khotyn, quân đội rút lui và lính phòng thủ bỏ trống pháo đài. Việc công sự Ottoman mạnh nhất ở phía bắc sông Danube bị mất mà không có kháng cự đã mở toang cửa Wallachia và Moldavia cho người Nga. Hai công quốc bị chiếm đóng ngay trong năm đó; Khotyn mãi đến Hiệp ước Küçük Kaynarca năm 1774 mới được lấy lại.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["Thảm bại trên đồng bằng Kagul (Kartal)", "6f408eaf"], "d": ["Ba tuần sau khi hạm đội bị thiêu hủy tại Çeşme, đạo quân chủ lực Ottoman dọc sông Danube đã tan rã trên đồng bằng Kagul trước các đơn vị tuy ít quân hơn rất nhiều nhưng kỷ luật của Thống chế Rumyantsev. Doanh trại, quân trang và hàng trăm khẩu đại bác rơi vào tay địch; các đơn vị tháo chạy chịu tổn thất lớn khi vượt sông Danube. Việc cả hạm đội lẫn lục quân bị tiêu diệt trong cùng một mùa hè đã dẫn đến sự thất thủ liên tiếp của Kiliya, Akkerman, Izmail và Bender cùng việc Crimea bị chiếm đóng.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["Nga chiếm đóng bán đảo Crimea", "217837b0"], "d": ["Các đạo quân Nga, đã chiếm Budjak một năm trước đó, dưới quyền chỉ huy của Hoàng thân Dolgorukov đã vượt qua Perekop (Or Kapı) và tràn ngập toàn bộ bán đảo Crimea. Vị khan bị phế truất, Sahib Giray thân Nga được đưa lên ngôi, và bước đầu tiên nhằm tách hãn quốc khỏi Ottoman đã được thực hiện. Việc mất Crimea, lá chắn phía bắc của Ottoman suốt ba thế kỷ, là khởi đầu của tiến trình dẫn đến độc lập năm 1774 và bị sáp nhập trực tiếp năm 1783.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["Mustafa III qua đời và Abdülhamid I lên ngôi", "42cba8e2"], "d": ["Mustafa III qua đời vào lúc cuộc chiến với Nga khủng hoảng nhất; kế vị ông là người em Abdülhamid I, người đã trải qua bốn mươi ba năm trong cảnh giam lỏng kafes của hoàng cung, lên ngôi ở tuổi bốn mươi chín. Tiếp nhận đất nước vào một trong những giai đoạn khó khăn nhất, vị sultan mới phải đối mặt với những điều khoản nặng nề của Hiệp ước Küçük Kaynarca ký ngay trong năm đó. Triều đại mười lăm năm của ông trôi qua với việc mất Crimea và một cuộc chiến mới với Nga, rồi kết thúc bằng cơn đột quỵ khi ông đọc tin Ochakov thất thủ năm 1789.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Thảm bại Kozluja — Thất bại dẫn đến Küçük Kaynarca", "8e0542f9"], "d": ["Lực lượng Ottoman tập trung trước Shumen bị các cánh quân hợp nhất của Suvorov và Kamensky đánh bại tại Kozluja, và phần lớn quân đội tan rã. Sau thảm bại này, không còn lực lượng nào để kháng cự ở Balkan; quân tiên phong Nga vây Shumen và đại bản doanh của Đại tể tướng bị đe dọa. Việc chưa đầy một tháng sau phải ngồi vào bàn đàm phán tại Küçük Kaynarca và chấp nhận những điều khoản nặng nề khác thường là hệ quả trực tiếp của thất bại này.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["Nhượng Bukovina (bắc Moldavia) cho Áo", "190f9caa"], "d": ["Lợi dụng sự suy yếu do Küçük Kaynarca gây ra, Áo đòi vùng Bukovina, nơi nối liền Moldavia với Transylvania, và giành được lãnh thổ này bằng đe dọa và hối lộ mà không cần giao chiến. Việc mất vùng đất màu mỡ và có vị trí chiến lược ở tây nam Khotyn này trên thực tế đã chia đôi công quốc Moldavia. Cuộc nhượng đất diễn ra mà không nổ một phát súng nào được coi là một trong những dấu hiệu rõ ràng nhất cho thấy Đế quốc Ottoman đã mất khả năng răn đe. Với việc nhượng Bukovina năm 1775, Suceava và Chernivtsi thuộc về Áo (ngày chưa được xác minh).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["Basra bị Iran chiếm đóng", "0161e709"], "d": ["Sadiq Khan, em của vua nhà Zand là Karim Khan, đã chiếm Basra sau một năm vây hãm, và Đế quốc Ottoman mất hải cảng quan trọng nhất của mình trên vịnh Basra. Cuộc chiếm đóng giáng đòn trực tiếp vào tuyến thương mại với Ấn Độ, nguồn thu từ chà là và ngọc trai cùng hệ thống phòng thủ phía nam của Iraq. Mãi đến năm 1779, trong cuộc tranh giành ngôi báu bùng nổ ở Iran sau cái chết của Karim Khan, thành phố mới được lấy lại.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["Công ước giải thích Aynalıkavak — Thỏa hiệp tạm thời về Crimea", "9b3b0468"], "d": ["Hai nước, đã đến bên bờ chiến tranh vì vấn đề ai sẽ đứng đầu Hãn quốc Crimea, đã ký tại cung Aynalıkavak một văn bản giải thích với sự trung gian của Pháp. Nga chấp nhận rút quân khỏi Crimea, còn Đế quốc Ottoman chấp nhận công nhận ngôi khan của Şahin Giray thân Nga; quyền caliph về mặt tôn giáo của sultan đối với Crimea được tái xác nhận. Thế cân bằng mong manh kéo dài bốn năm này sẽ sụp đổ hoàn toàn khi Nga sáp nhập trực tiếp bán đảo vào năm 1783.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["Xây pháo đài Anapa — phòng tuyến Kavkaz", "be92a80f"], "d": ["Khi Crimea bị mất sau Küçük Kaynarca, việc xây một pháo đài mới ở cửa sông Kuban được khởi công nhằm giữ ảnh hưởng của Ottoman ở Kavkaz. Dựng trên tàn tích thuộc địa Genoa, Anapa, với khu chợ, các nhà tắm và hơn hai trăm năm mươi cửa hiệu, chẳng bao lâu trở thành thành phố bảo đảm liên lạc với các bộ lạc Circassia. Pháo đài là tiền đồn tiến xa nhất của Ottoman chống việc Nga tiến xuống Kavkaz suốt bốn mươi tám năm.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["Đại tể tướng Halil Hamid Pasha bị bãi chức và xử tử", "c44001ca"], "d": ["Đại tể tướng cải cách Halil Hamid Pasha, người mà Abdülhamid I đã nhiều dịp tỏ ra hài lòng về công lao, đã bất ngờ bị bãi chức vào rạng sáng ngày 31 tháng 3 năm 1785, bị đày đến Gallipoli và toàn bộ tài sản bị tịch thu. Trước hết ông được giao tỉnh Habesh, sanjak Jeddah và chức sheikh quản Thánh địa Mecca; trong khi trải qua tháng 4 năm 1785 ở Tenedos để chuẩn bị lên đường, ông cũng bị bãi luôn chức tổng đốc này, và theo sắc lệnh xử tử được ban ra, ông bị Karakethüdazade Ali, một người của Cezayirli Gazi Hasan Pasha, giết chết. Thủ cấp của ông được gửi về Istanbul và bêu tại cổng Giữa (Orta Kapı). Theo TDV, tuy sự sụp đổ đột ngột này được giải thích bằng lời buộc tội ông mưu phế truất sultan để đưa hoàng tử Selim lên thay, nguyên nhân thật có lẽ là sự phẫn nộ vì ông im lặng trước việc Crimea bị sáp nhập, sự thù địch của các giới bị cải cách của ông làm tổn hại và sự chống đối của Gazi Hasan Pasha.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Tuyên chiến với Nga — Chiến tranh Nga – Ottoman 1787–1792 bắt đầu", "3bfb870c"], "d": ["Trước chuyến du hành Crimea phô trương của Catherine II và việc bà đặt Gruzia dưới sự bảo hộ, Hội đồng Divan quyết định tuyên chiến nhằm đảo ngược việc sáp nhập, và đại sứ Nga lại bị giam vào Yedikule. Tuy nhiên quân đội chưa sẵn sàng, ngân khố trống rỗng và việc tìm kiếm đồng minh không có kết quả. Cuộc chiến kéo dài năm năm sẽ kết thúc với việc Ochakov thất thủ trong một cuộc thảm sát, mất Izmail và những điều khoản nặng nề của Hiệp ước Jassy.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["Áo tham chiến — Cuộc đối đầu trên hai mặt trận", "ae912290"], "d": ["Theo liên minh bí mật ký với Nga năm 1781, hoàng đế Áo Joseph II tuyên chiến với Đế quốc Ottoman và tiến quân theo hướng Belgrade và Bosnia. Quân đội Ottoman đột ngột phải chiến đấu cùng lúc trên hai mặt trận, với Nga ở phía bắc và Áo ở phía tây. Bất chấp những chiến thắng giành được trước quân Áo tại Lazarethane, Mehadia và Caransebeş, mặt trận phía tây cũng sụp đổ khi Belgrade bị mất năm 1789.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Liên minh Ottoman – Phổ", "03b88e51"], "d": ["Selim III, người tìm kiếm đồng minh ở châu Âu ngay khi lên ngôi, đã ký với Phổ một hiệp ước liên minh quy định tương trợ lẫn nhau; Phổ cam kết tuyên chiến với Nga và Áo, còn Đế quốc Ottoman cam kết không giảng hòa khi chưa lấy lại Crimea. Đây là văn bản liên minh tương hỗ thực sự đầu tiên trong lịch sử Ottoman ký với một quốc gia châu Âu, cho thấy quan niệm cổ điển “không liên minh với kẻ ngoại đạo” đã bị từ bỏ. Phổ không tham chiến, nhưng đã ép Áo giảng hòa, mở đường cho Hiệp ước Sistova.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["Pháo đài Izmail thất thủ và cuộc thảm sát", "6a296b0c"], "d": ["Pháo đài Izmail, được coi là công sự mạnh nhất ở châu thổ sông Danube, đã bị chiếm trong một ngày bằng cuộc tổng công kích đẫm máu do tướng Suvorov tổ chức; phần lớn đội đồn trú và cư dân thành phố bị chém giết. Cuộc thảm sát gây tiếng vang rộng rãi ở châu Âu này đã tạo ra cú sốc sâu sắc trong dư luận Ottoman và bẻ gãy xương sống của phòng tuyến sông Danube. Pháo đài được trả lại một năm sau theo Hiệp ước Jassy, nhưng khi đó số phận cuộc chiến đã được định đoạt từ lâu.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Hiệp ước Sistova — Đóng mặt trận chống Áo", "58741f1d"], "d": ["Nhờ sức ép của Phổ và việc Cách mạng Pháp khiến Áo bận tâm ở phía tây, hai nước giảng hòa trên cơ sở đường biên giới trước chiến tranh. Áo trả lại mọi nơi đã chiếm đóng, kể cả Belgrade; Đế quốc Ottoman chỉ chấp nhận vài điều chỉnh nhỏ ở biên giới Croatia. Việc đóng mặt trận phía tây theo những điều kiện này cho phép Ottoman dồn toàn lực chống Nga và hạn chế tổn thất trong Hiệp ước Jassy. Với những điều chỉnh ở biên giới Croatia này, Cetin (Cetingrad) và Drežnik Grad chuyển từ Ottoman sang Habsburg (TDV zistovi-antlasmasi; Korić 2016, chú thích 118, điều 4). Orșova (Orșova Cũ) là nơi duy nhất không được trả lại (Bánlaky 0019/1796); bản đồ ghi việc chuyển giao về pháp lý vào ngày này (chiếm đóng thực tế ngày 16 tháng 4 năm 1790).", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Hiệp ước Jassy — Mất hẳn Crimea và đường biên giới sông Dniester", "a56fd194"], "d": ["Theo hiệp ước ký khi cuộc chiến năm năm kết thúc, sông Dniester (Turla) được chấp nhận làm biên giới; tả ngạn thuộc về Nga, hữu ngạn thuộc về Ottoman, và Ochakov cùng vùng phụ cận bị mất hẳn. Đế quốc Ottoman từ bỏ hoàn toàn hy vọng lấy lại Crimea và công nhận về mặt pháp lý việc sáp nhập năm 1783; Wallachia và Moldavia được trả lại cùng với việc miễn thuế hai năm. Nghĩa vụ bồi thường chiến phí mười hai triệu kuruş cũng được chấp nhận, qua đó vùng phía bắc Biển Đen bị nhượng vĩnh viễn cho Nga. Nơi khác được tính cùng ngày này: Izmail.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["Người Tây Ban Nha bỏ Oran và giao cho Algiers", "9f95cee6"], "d": ["Khi trận động đất năm 1790 phá hủy phần lớn pháo đài và thành phố, Tây Ban Nha không còn gánh nổi đội đồn trú tốn kém duy trì suốt ba thế kỷ, nên đã thỏa thuận với quân đoàn đồn trú Algiers và giao Oran cùng Mers el-Kébir mà không giao chiến. Như vậy vị trí cuối cùng của châu Âu trên bờ Bắc Phi cũng bị thanh lý. Xứ Algiers thuộc Ottoman làm chủ toàn bộ dải bờ biển trong ba mươi tám năm cho đến cuộc chiếm đóng của Pháp.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["Pazvandoğlu Osman cai trị Vidin trên thực tế", "0ce70361"], "d": ["Pazvandoğlu Osman, nổi dậy chống các quy chế Trật tự Mới (Nizam-ı Cedid), đã cho bắt cóc tổng đốc Vidin, chiếm thành phố và củng cố nó bằng những hào sâu dọc sông Danube. Năm 1797, ở đỉnh cao quyền lực, ông tập hợp gần tám mươi nghìn quân và kiểm soát Nikopol, Sistova, Ruse, Sofia và Niš; ông tự giới thiệu mình không phải là kẻ phản loạn mà là nhà cải cách. Cuộc vây hãm kéo dài nhiều tháng của Triều đình Cổng Cao trong các năm 1798–1799 không có kết quả, và ông cai trị miền Bắc Bulgaria với địa vị bán độc lập cho đến khi qua đời năm 1807.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["Khai trường Kỹ thuật Lục quân Hoàng gia", "e9a3a34b"], "d": ["Trường kỹ thuật lục quân được mở tại Hasköy nhằm đào tạo sĩ quan pháo binh, công binh và bản đồ cho quân đội Trật tự Mới; đây là cơ sở của lục quân tương ứng với Trường Kỹ thuật Hải quân thành lập năm 1773. Chương trình giảng dạy gồm đại số, hình học, cơ học, công sự và đạn đạo học, đồng thời các sách toán và pháo binh được dịch từ các ngôn ngữ châu Âu. Được coi là cội nguồn của nền đào tạo kỹ thuật hiện đại ở Thổ Nhĩ Kỳ, ngôi trường này được xem là khởi đầu của Đại học Kỹ thuật Istanbul ngày nay.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Tuyên chiến với Pháp và liên minh với Nga, Anh", "80e95bd7"], "d": ["Trước việc Napoléon xâm chiếm Ai Cập, Đế quốc Ottoman phá bỏ tình hữu nghị truyền thống hai thế kỷ rưỡi với Pháp và tuyên chiến. Cũng trong tiến trình này, lần đầu tiên trong lịch sử, Ottoman liên minh với Nga và cho phép hạm đội Nga đi qua các Eo biển ra Địa Trung Hải; sau đó cũng ký liên minh với Anh. Nhờ các liên minh này, quần đảo Ionia được giành lại từ tay người Pháp, nhưng việc mở các Eo biển cho một hạm đội nước ngoài đã tạo ra tiền lệ phải trả giá đắt về sau.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["Giành Preveza từ tay người Pháp — Trận Nicopolis", "d8e5e892"], "d": ["Khi Cộng hòa Venice sụp đổ năm 1797, quần đảo Ionia cùng Preveza, Parga và Vonitsa trên đất liền rơi vào tay Pháp. Tổng đốc Ioannina Ali Pasha xứ Tepelenë, lợi dụng cuộc chiến mở ra do Pháp xâm chiếm Ai Cập, đã tiến quân đến Preveza và đánh bại nặng đội đồn trú Pháp tại phế tích Nicopolis ngoài thành phố. Như vậy hải cảng mà Passarowitz để lại cho Venice, tám mươi năm sau đã thuộc quyền cai quản của Ottoman. Butrint (Butrinto) thất thủ ngày 25 tháng 10 khi đội đồn trú Pháp cho nổ công sự và rút về Corfu (Curlin, Preveza B, 2010; bản đồ lấy ngày theo Preveza) và đi vào quyền cai quản của Ottoman.", "f32e8843"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["Phòng thủ Acre — Đẩy lui Napoléon", "56b5c45b"], "d": ["Napoléon, tiến từ Ai Cập sang Syria, đã vây hãm Acre và liên tiếp mở các đợt tấn công suốt hai tháng; Cezzar Ahmed Pasha bảo vệ thành phố với sự hỗ trợ của hạm đội Anh và các đơn vị Trật tự Mới được gửi từ Istanbul. Buộc phải giải vây và rút về Ai Cập, Napoléon đã chôn vùi giấc mộng vươn sang phương đông trước những bức tường thành này. Tin tức được đón nhận ở Istanbul với niềm vui lớn và được coi là bằng chứng cho thấy đội quân huấn luyện mới thành lập đã vượt qua thử thách nghiêm túc đầu tiên.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["Người Wahhabi tập kích Karbala", "522341ed"], "d": ["Lực lượng Wahhabi xuất phát từ Najd đã tiến vào Karbala, cướp phá thành phố, phá hoại lăng mộ Hussein và giết hơn ba nghìn người. Các tổng đốc gốc Mamluk của Đế quốc Ottoman ở Iraq không ngăn được cuộc tập kích; sự kiện gây phản ứng dữ dội cả ở Iran lẫn Istanbul. Cuộc tấn công này là lời tuyên bố rằng phong trào Saud không còn là một tiểu quốc ốc đảo mà đã trở thành thế lực khu vực đe dọa các thánh địa của Ottoman.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["Kartli-Kakheti (Đông Gruzia) bị sáp nhập vào Nga", "3b650c5e"], "d": ["Vương quốc Kartli-Kakheti, vốn đã chấp nhận sự bảo hộ của Nga năm 1783 và bị chiến dịch tàn phá của Iran năm 1795, bị giải thể; theo mệnh lệnh ngày 12 tháng 9 năm 1801, nó được tuyên bố là một tỉnh của Nga và hệ thống hành chính Nga bắt đầu được thiết lập. Từ thời điểm này Gruzia mất độc lập; trong vài năm, Mingrelia (1803), Imereti và Guria (1804) cũng rơi vào quyền thống trị của Nga, và Nga áp sát biên giới Kavkaz của Ottoman. Với sự kiện này, Gori, Dusheti (Kartli) và Telavi (Kakheti) chuyển sang Nga.", "f5e0d5d5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["Quân Pháp rút khỏi Ai Cập", "00cfdc8c"], "d": ["Nhờ chiến dịch phối hợp trên bộ và trên biển của lực lượng Ottoman và Anh, trước hết Cairo rồi đến Alexandria được tiếp nhận, và quân Pháp được đưa về nước bằng tàu. Khi cuộc chiếm đóng ba năm kết thúc, Ai Cập trên giấy tờ trở lại quyền cai quản của Ottoman, nhưng cuộc tranh giành quyền lực giữa các bey Mamluk và các đơn vị người Albania đã đẩy đất nước vào hỗn loạn. Khoảng trống này sẽ tạo nền cho sự trỗi dậy của Muhammad Ali người Kavala chỉ vài năm sau.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Hiệp ước Paris — Tái lập hòa bình với Pháp", "1b76991f"], "d": ["Theo hiệp ước ký sau khi quân Pháp rút khỏi Ai Cập, tình trạng chiến tranh giữa Đế quốc Ottoman và Pháp chính thức chấm dứt, và các ưu đãi thương mại (capitulations) cũ được khôi phục. Tàu buôn Pháp được phép vào Biển Đen; bù lại, Pháp công nhận sự toàn vẹn lãnh thổ của Ottoman. Việc tái lập hòa bình đã trả lại dư địa xoay xở cho chính sách đối ngoại của Selim III vốn đang bị kẹt bên cạnh Nga và Anh.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["Người Wahhabi chiếm Taif", "7b791359"], "d": ["Lực lượng Wahhabi dưới quyền chỉ huy của Saud ibn Abd al-Aziz trong nước đi đầu tiên nhằm vào Hejaz đã vây hãm và cướp phá Taif; thành phố thất thủ như cánh cửa đầu tiên mở vào vùng đất thánh. Đối với sultan Ottoman, người mang danh hiệu người bảo hộ Hai Thánh địa, đây là đòn trực tiếp làm lung lay tính chính danh của vương quyền. Hai tháng rưỡi sau, chính đạo quân này sẽ tiến về Mecca.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["Người Wahhabi lần đầu chiếm Mecca", "21157c05"], "d": ["Hai tháng rưỡi sau khi Taif thất thủ, lực lượng Wahhabi tiến vào Mecca, phá các lăng mộ và thiết lập trật tự theo quan niệm của mình; Sharif Ghalib buộc phải rút về Jeddah. Việc các đường hành hương bị đóng gây chấn động toàn thế giới Hồi giáo và buộc Istanbul phải yêu cầu tổng đốc Ai Cập Muhammad Ali viện trợ quân sự. Sự thống trị đầu tiên này chỉ kéo dài ba tháng.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Sharif Ghalib giành lại Mecca", "83d08dff"], "d": ["Sharif Ghalib, trước đó đã rút về Jeddah, đem lực lượng tập hợp được vây Mecca, và sau hai mươi lăm ngày vây hãm đã giành lại thành phố từ tay người Wahhabi; bài giảng khutba lại được đọc nhân danh Ottoman. Quyền thống trị lần thứ hai này cũng không lâu bền; lực lượng Saud sẽ chiếm lại thành phố năm 1806.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["Cuộc khởi nghĩa Serbia thứ nhất bùng nổ", "0f6e8767"], "d": ["Khi các thủ lĩnh janissary nổi loạn (dahi) nắm quyền ở Belgrade tàn sát hàng loạt các thân hào Serbia, một cuộc kháng chiến vũ trang dưới sự lãnh đạo của Karađorđe đã bắt đầu. Phong trào ban đầu trung thành với sultan và chỉ chống các dahi, nhưng chẳng bao lâu đã biến thành cuộc khởi nghĩa dân tộc đòi tự trị và độc lập. Lực lượng Serbia chiếm Belgrade năm 1806; cuộc nổi dậy này là mắt xích đầu tiên của các phong trào độc lập mang tính dân tộc chủ nghĩa ở Balkan.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["Người Wahhabi chiếm đóng Medina", "84e310d7"], "d": ["Sau Mecca, Medina cũng rơi vào tay lực lượng Wahhabi; kho báu của lăng Nhà Tiên tri (Rawda) bị phân phát và các lăng mộ có mái vòm trong thành phố bị phá hủy. Như vậy cả hai thành phố thánh cùng thoát khỏi sự kiểm soát của Ottoman, và các đoàn hành hương từ Damascus và Ai Cập không thể lên đường trong nhiều năm. Mãi bảy năm sau, năm 1812, Medina mới được quân đội Ai Cập dưới quyền Tosun Pasha, con trai Muhammad Ali Pasha, lấy lại.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["Khởi đầu chiến tranh với Nga (Chiến tranh Nga – Ottoman 1806–1812) và đóng cửa các Eo biển", "ea170804"], "d": ["Sau chiến thắng Austerlitz của Napoléon, Selim III xích lại gần Pháp và bãi chức các voyvoda Wallachia và Moldavia bất chấp sức ép của Nga; quân Nga liền chiếm đóng hai công quốc và chiến tranh bùng nổ. Đế quốc Ottoman đóng các Eo biển đối với hạm đội Nga; đáp lại, Anh đứng về phía Nga và phái một hạm đội đến Istanbul. Cuộc chiến sáu năm này, đan xen với cuộc nổi loạn Kabakçı và việc phế truất Selim III, sẽ kết thúc với việc mất Bessarabia trong Hiệp ước Bucharest năm 1812.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["Hạm đội Anh đến trước Istanbul (chiến dịch Duckworth)", "195bb58f"], "d": ["Muốn ép Đế quốc Ottoman cắt đứt quan hệ với Pháp, Anh cho hạm đội dưới quyền Đô đốc Duckworth vượt eo Dardanelles và thả neo trước Istanbul. Cũng nhờ sự chỉ dẫn của đại sứ Pháp Sébastiani, dân chúng Istanbul được huy động, các trận địa pháo bờ biển được tăng cường trong vài ngày, và hạm đội buộc phải rút lui trước khi có thể nã pháo vào thành phố; trên đường về, nó chịu tổn thất nặng ở Dardanelles. Việc kinh đô lần đầu tiên bị một hạm đội nước ngoài đe dọa gần đến thế đã đặt vấn đề Eo biển vào trung tâm của ngoại giao châu Âu.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["Mustafa IV bị thắt cổ giết chết", "eeb75c20"], "d": ["Khi Alemdar Mustafa Pasha bị đột kích và chết, còn quân nổi loạn muốn tiến vào hoàng cung, Mustafa IV đã bị phế truất bị thắt cổ giết chết theo lệnh của người em Mahmud II. Linh cữu ông được an táng trong lăng của cha ông, Abdülhamid I, ở Bahçekapı; trong quân nổi loạn lan truyền tin đồn rằng quan tài trống rỗng.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Hiệp ước Kala-i Sultaniye (Dardanelles) — Hòa bình với Anh và nguyên tắc về Eo biển", "fe282117"], "d": ["Sau khi chiến dịch Duckworth thất bại, hiệp ước ký với Anh đã chấm dứt chiến tranh giữa hai nước và trả lại cho thương nhân Anh các đặc quyền cũ. Điều khoản trong văn bản, được gọi là “quy tắc cổ xưa”, ghi nhận rằng trong thời bình không tàu chiến nước ngoài nào được đi qua các Eo biển. Nguyên tắc này trở thành cơ sở pháp lý cho mọi dàn xếp quốc tế định hình chế độ Eo biển suốt thế kỷ 19.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["Thảm bại Slobozia — Đạo quân sông Danube bị bao vây", "54b60fd1"], "d": ["Phần lớn quân đội Ottoman vượt sông Danube trước Ruse đã bị Kutuzov, bằng cuộc cơ động bao vây từ bờ bên kia sông, dồn ép tại Slobozia và bỏ mặc cho chết đói. Hàng nghìn binh sĩ buộc phải đầu hàng; lực lượng trong tay Đại tể tướng trên thực tế đã tan biến, và một tháng sau Triều đình Cổng Cao buộc phải xin ngừng bắn. Thất bại này là nguyên nhân trực tiếp khiến Ottoman chấp nhận nhượng Bessarabia trong Hiệp ước Bucharest năm 1812.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["Thu hồi Belgrade và dẹp cuộc khởi nghĩa Serbia thứ nhất", "06f56f52"], "d": ["Mất đi sự hỗ trợ của Nga theo Hiệp ước Bucharest, quân khởi nghĩa Serbia không trụ nổi trước chiến dịch phối hợp của các lực lượng đến từ Bosnia và Rumelia; Hurşid Ahmed Pasha tiến vào Belgrade, và cuộc nổi dậy chín năm bị dập tắt hoàn toàn. Karađorđe trốn sang Áo, sanjak Smederevo lại được đặt dưới sự cai quản trực tiếp của Ottoman. Tuy nhiên, những biện pháp hà khắc được áp dụng sẽ châm ngòi cho cuộc khởi nghĩa thứ hai, lâu bền hơn, dưới sự lãnh đạo của Miloš Obrenović hai năm sau.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["Cuộc khởi nghĩa Serbia thứ hai và việc Miloš Obrenović làm đại thủ lĩnh (knez tối cao)", "e6e82ad2"], "d": ["Chống lại các biện pháp nặng nề áp dụng sau khi cuộc khởi nghĩa thứ nhất bị dẹp, một cuộc nổi dậy mới dưới sự lãnh đạo của Miloš Obrenović đã bùng nổ; lần này Triều đình Cổng Cao chọn thỏa hiệp thay vì dùng vũ lực. Theo thỏa thuận đạt được, Miloš được công nhận với tư cách “knez tối cao”, quyền thu thuế và điều hành nội bộ được giao cho các knez Serbia. Hạt nhân đầu tiên của nền tự trị trên thực tế này trở thành điểm khởi đầu của tiến trình dẫn đến sắc lệnh firman năm 1830 và nền độc lập năm 1878.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["Cuộc nổi dậy ở Wallachia — Ypsilanti vượt sông Prut và cuộc khởi nghĩa của Vladimirescu", "67d46a98"], "d": ["Alexander Ypsilanti, một vị tướng trong quân đội Nga, đã vượt sông Prut nhân danh hội Filiki Eteria và tìm cách phát động cuộc nổi dậy toàn diện của người Hy Lạp ở Wallachia và Moldavia; cùng thời gian đó, Tudor Vladimirescu cũng huy động nông dân địa phương. Hai phong trào không thể hợp nhất: trước lời kêu gọi của Ypsilanti cùng chiến đấu chống người Thổ, Vladimirescu đáp “Tôi nổi dậy chống người Hy Lạp chứ không chống người Thổ”, và chẳng bao lâu sau bị người của Ypsilanti giết. Cuộc nổi dậy bị lực lượng Ottoman dẹp vào tháng 5, nhưng chế độ voyvoda người Phanar chấm dứt và ngọn lửa khởi nghĩa lan sang Morea.", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["Nhà nước Saud thứ hai được thành lập tại Riyadh", "34dad3bd"], "d": ["Sáu năm sau khi Diriyah thất thủ năm 1818 và nhà nước Saud thứ nhất sụp đổ, Turki ibn Abdullah đã đẩy các đội đồn trú Ai Cập ra khỏi Najd và lập một tiểu vương quốc Saud mới đóng đô tại Riyadh. Thực thể mới tránh vươn sang Hejaz, chọn ở lại Najd và né đụng độ trực tiếp với lực lượng Ottoman – Ai Cập. Nhà nước thứ hai này tồn tại đến cuối thế kỷ và tạo thành mắt xích thứ hai trong chuỗi dẫn đến việc thành lập Ả Rập Xê Út ngày nay. Các điểm định cư khác bị mất cùng ngày: Diriyah (Najd).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["Hiệp ước Akkerman — Nhượng bộ cho Serbia và các công quốc", "c75f15d0"], "d": ["Bị bỏ lại không quân đội ngay sau khi giải thể Quân đoàn janissary, Đế quốc Ottoman buộc phải chấp nhận một hiệp ước với điều khoản nặng nề trước tối hậu thư của Nga. Quyền tự trị đã hứa cho Serbia được tái xác nhận, nguyên tắc không được bãi chức các voyvoda Wallachia và Moldavia nếu không có Nga chấp thuận được chấp nhận, và tàu buôn Nga được tự do hoàn toàn ở các Eo biển. Hai năm sau, khi Triều đình Cổng Cao tuyên bố không công nhận hiệp ước vì vấn đề Hy Lạp, Nga sẽ coi đó là cớ gây chiến.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["Thanh lý chế độ timar", "84d5d1d6"], "d": ["Một năm sau khi giải thể Quân đoàn janissary, khoảng 5.200 kỵ binh sipahi hưởng timar ở năm mươi ba sanjak thuộc Rumelia và Anatolia, cùng với nguồn thu timar của họ, được chuyển thành kỵ binh của quân đội Asakir-i Mansure. Như vậy chế độ timar, xương sống suốt bốn thế kỷ của trật tự đất đai, thuế khóa và quân đội Ottoman, trên thực tế đã chấm dứt. Các timar bỏ trống được chuyển cho ngân khố, mở đường cho việc chuyển sang quân đội trung ương hưởng lương và hệ thống thuế bằng tiền mặt.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["Thành lập Trường Y Hoàng gia (Tıphane-i Amire) — khởi đầu nền đào tạo y khoa hiện đại", "ac3e57c0"], "d": ["Nhằm đào tạo thầy thuốc và phẫu thuật viên cho quân đội Asakir-i Mansure mới thành lập, theo đề nghị của y trưởng Mustafa Behçet Efendi, Trường Y Hoàng gia được mở tại Şehzadebaşı. Chương trình giảng dạy được sắp xếp theo chương trình châu Âu và ban đầu dạy bằng tiếng Pháp; vài năm sau, Trường Phẫu thuật Hoàng gia cũng được lập và hai cơ sở được hợp nhất. Được coi là khởi đầu của việc giảng dạy y học hiện đại ở Thổ Nhĩ Kỳ, ngôi trường này được xem là nguồn gốc của Khoa Y Istanbul ngày nay.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["Chiến tranh Nga – Ottoman 1828–1829 bùng nổ", "9dff4e05"], "d": ["Sau việc hạm đội bị thiêu hủy tại Navarino và việc Triều đình Cổng Cao tuyên bố không công nhận Hiệp ước Akkerman, Nga khai chiến trên cả hai mặt trận. Do Quân đoàn janissary vừa mới bị giải thể còn quân đội mới đang trong giai đoạn xây dựng, hệ thống phòng thủ Ottoman yếu ngay từ đầu; quân Nga vừa vượt sông Danube vừa chiếm Kars và Akhaltsikhe ở phía đông. Trong vòng một năm, quân đội Nga tiến đến tận Edirne và sẽ áp đặt những điều khoản nặng nề của Hiệp ước Adrianople (Edirne) năm 1829 cùng nền độc lập của Hy Lạp.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["Hiệp ước đầu tiên với Hợp chúng quốc Hoa Kỳ", "d737516f"], "d": ["Theo hiệp ước thương mại và hàng hải ký sau nhiều năm tiếp xúc, Hoa Kỳ được hưởng quy chế tối huệ quốc trên lãnh thổ Ottoman và quyền qua lại thương mại ở các Eo biển. Một điều khoản mật riêng dự kiến Ottoman, khi muốn, được đặt đóng tàu tại các xưởng đóng tàu Mỹ và mua tàu đóng sẵn cùng gỗ; Thượng viện Hoa Kỳ phê chuẩn hiệp ước nhưng bác điều khoản mật này với tỷ số 18 phiếu chống 27. Tuy vậy, con đường đóng tàu vẫn không bị đóng: Henry Eckford bán cho Ottoman con tàu ông đưa đến năm 1831, và các thợ cả người Mỹ làm việc tại Aynalıkavak đã mang đến cho hải quân những loại tàu mới. Hiệp ước này trở thành văn kiện của mối quan hệ toàn diện đầu tiên mà Đế quốc Ottoman thiết lập với một quốc gia ngoài châu Âu.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["Chấm dứt sự cai trị của người Mamluk ở Baghdad", "7e1d38a3"], "d": ["Theo đuổi chính sách tập quyền, Mahmud II tuyên bố tổng đốc Baghdad Davud Pasha, người không gửi số tiền được yêu cầu và cho giết viên quan do triều đình phái đến, là kẻ phản loạn. Lực lượng dưới quyền Ali Rıza Pasha chiếm thành phố sau chín mươi ngày vây hãm, và gần như toàn bộ người Mamluk bị thanh trừng. Như vậy chính quyền Mamluk bán độc lập kéo dài từ năm 1704 chấm dứt, và Iraq lại được gắn trực tiếp với trung ương.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["Thành lập Trường Võ bị tại doanh trại Maçka", "bf31c7d9"], "d": ["Để cung cấp cho quân đội Asakir-i Mansure-i Muhammediye những sĩ quan được đào tạo theo kiểu châu Âu, Trường Khoa học Quân sự được mở tại doanh trại Maçka. Học viên được học toán, bản đồ, công sự và ngoại ngữ; chẳng bao lâu sau, đội ngũ được củng cố bằng việc gửi học viên sang Vienna và Paris. Ngôi trường này là nơi khai sinh truyền thống sĩ quan được đào tạo chính quy trong quân đội Ottoman và do đó cũng là nơi sinh ra thế hệ quân nhân – trí thức mới xuất hiện vào cuối thế kỷ 19.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["Tripoli (Libya) được đặt trực thuộc trung ương — Triều đại Karamanli chấm dứt", "faabcb96"], "d": ["Trước những cuộc tranh giành ngôi trong dòng họ Karamanli và sức ép gia tăng của châu Âu sau khi Pháp chiếm Algiers năm 1830, Triều đình Cổng Cao đã trực tiếp can thiệp vào Tripoli. Hạm đội phái từ Istanbul tiến vào thành phố, vị bey Karamanli cuối cùng bị bãi chức và đưa về Istanbul, và tỉnh được giao cho một tổng đốc do trung ương bổ nhiệm. Khi thời kỳ triều đại kéo dài 124 năm kết thúc, mảnh đất cuối cùng ở Bắc Phi do Đế quốc Ottoman trực tiếp cai quản đã được củng cố.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["Bãi bỏ chức defterdar và thành lập Bộ Tài chính", "89f8125e"], "d": ["Chức defterdar, đứng đầu trật tự tài chính Ottoman cổ điển, bị bãi bỏ; Bộ Tài chính, một bộ theo kiểu châu Âu, được thành lập và các ngân khố phân tán được tập trung vào một mối. Cùng năm, các cơ quan khác của Triều đình Cổng Cao cũng được tổ chức lại dưới danh nghĩa bộ (nezaret), chuyển sang cơ cấu hội đồng bộ trưởng hiện đại. Cải cách này là một trong những bước quan trọng nhất chuẩn bị nền tảng hành chính cho Sắc lệnh Tanzimat công bố một năm sau đó.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["Người Anh đặt chân tại Aden", "ddbd556b"], "d": ["Dựa trên hiệp định thương mại và hữu nghị ký năm 1802 với sultan Lahej là Ahmad ibn Abd al-Karim, Anh đổ quân lên cảng Aden và kiểm soát thành phố. Hải cảng trấn giữ cửa Biển Đỏ này, với tư cách trạm tiếp than trên đường sang Ấn Độ, trở thành điểm then chốt trong chiến lược đế quốc của Anh. Tuy yêu sách của Đế quốc Ottoman đối với Yemen vẫn tồn tại trên giấy tờ, quyền thống trị thực tế của họ ở bờ biển phía nam không bao giờ trở lại sau thời điểm này.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["Trở lại bờ biển Tihamah: chiếm Hodeidah, Zabid và Mocha", "353982d2"], "d": ["Trên bờ biển Yemen bị bỏ trống sau khi quân Ai Cập rút đi năm 1840, các lực lượng dưới quyền Tevfik Pasha, đặt dưới sự giám sát của sharif Mecca, đã đổ bộ và đưa các cảng Hodeidah, Zabid và Mocha vào quyền cai quản của Ottoman. Dù muốn tiến đến Sanaa, họ phải quay về Hodeidah vì sự kháng cự của dân chúng; như vậy vùng cao nguyên vẫn thuộc các imam Zaydi, và quyền thống trị của Ottoman trong hai mươi ba năm chỉ kéo dài trên dải đất Tihamah. Nội địa Yemen mãi đến năm 1872 mới được thu hồi bằng chiến dịch của Ahmed Muhtar Pasha.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Công ước Balta Liman: Ottoman và Nga cùng bảo hộ Wallachia và Moldavia", "d3bb22e9"], "d": ["Khi các cuộc cách mạng năm 1848 lan đến Wallachia và Moldavia, quân Ottoman và Nga đã cùng chiếm đóng hai công quốc. Theo công ước ký tại Balta Liman, hai bên quyết định các voyvoda không còn được bầu mà do sultan bổ nhiệm với nhiệm kỳ bảy năm, và hai nước thiết lập quyền kiểm soát chung trong vùng. Thỏa thuận giữ nguyên chủ quyền trên giấy tờ của Ottoman nhưng công nhận cho Nga quyền đồng quản trên thực tế và đẩy nhanh quá trình các công quốc sông Danube tách khỏi Ottoman.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["Vấn đề người tị nạn Hungary: Kossuth và các đồng chí lánh nạn tại Ottoman", "1c7d7ef4"], "d": ["Khi cuộc cách mạng Hungary 1848–1849 bị dập tắt bởi sự can thiệp của Nga và Áo, Lajos Kossuth cùng hàng nghìn người tị nạn Hungary và Ba Lan đã lánh sang lãnh thổ Ottoman. Áo và Nga gay gắt đòi dẫn độ người tị nạn; Triều đình Cổng Cao, được Anh và Pháp ủng hộ, từ chối dẫn độ và bố trí nhóm này ở Kütahya. Nhóm thân cận của Kossuth ở đây khoảng mười tám tháng, và hàng trăm người tị nạn cải đạo sang Hồi giáo rồi vào phục vụ Ottoman. Sự kiện được coi là một trong những thắng lợi ngoại giao hiếm hoi nâng cao uy tín của Ottoman thời Tanzimat trong dư luận châu Âu.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Thành lập Hội đồng Khoa học (Encümen-i Daniş): viện hàn lâm Ottoman đầu tiên ở Istanbul", "6fda1365"], "d": ["Được lập theo quyết định của Hội đồng Giáo dục Phổ thông, Encümen-i Daniş là viện hàn lâm khoa học Ottoman đầu tiên, được tổ chức nhằm biên soạn sách khoa học và giáo khoa bằng tiếng Thổ Nhĩ Kỳ. Viện được khai mạc trọng thể ngày 18 tháng 7 năm 1851 tại tòa nhà Darülmaarif; trong số các thành viên trong và ngoài nước có cả Ahmed Cevdet Pasha. Tuy tồn tại ngắn ngủi, những tác phẩm như bộ Lịch sử (Tarih) của Cevdet Pasha và Kavaid-i Osmaniye (Quy tắc tiếng Ottoman) là sản phẩm của cơ quan này, và nó được coi là cột mốc trong việc đưa tiếng Thổ Nhĩ Kỳ thành ngôn ngữ khoa học.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["Chiến thắng Oltenița: thành công đầu tiên của Ottoman trên mặt trận sông Danube", "a660ad2f"], "d": ["Trong giai đoạn mở đầu Chiến tranh Crimea, Tổng tư lệnh Ömer Lütfi Pasha đã vượt sông Danube và đẩy lui lực lượng Nga tại Oltenița, gây cho họ tổn thất nặng. Chiến thắng ngay đầu cuộc chiến đã chặn đà tiến của Nga và cho châu Âu thấy sức mạnh mà quân đội Ottoman đạt được nhờ huấn luyện sau Tanzimat. Thành công này chuẩn bị nền tảng tâm lý giúp Anh và Pháp dễ dàng quyết định tham chiến bên cạnh Ottoman.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["Hiệp ước liên minh với Anh và Pháp tại Istanbul", "04809278"], "d": ["Hiệp ước liên minh ký giữa Đế quốc Ottoman với Anh và Pháp chống Nga trong Chiến tranh Crimea quy định ba nước tiến hành chiến dịch chung và các đồng minh không được giảng hòa riêng trước khi chiến tranh kết thúc. Như vậy lần đầu tiên trong lịch sử, Đế quốc Ottoman tham gia một liên minh quân sự với các cường quốc châu Âu với tư cách bên bình đẳng. Hiệp ước này cũng tạo nền tảng pháp lý cho việc Ottoman được chính thức tiếp nhận vào hệ thống các nước châu Âu tại Paris hai năm sau.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["Thành lập Sở Thị chính Istanbul: tổ chức đô thị hiện đại đầu tiên", "be4af27f"], "d": ["Quân đội đồng minh đổ dồn về Istanbul trong Chiến tranh Crimea và cuộc khủng hoảng hạ tầng do dân số tăng đã phơi bày sự bất cập của nền quản lý đô thị cổ điển lấy chức kadi làm trung tâm. Với Sở Thị chính (Şehremaneti) lập theo mẫu châu Âu, việc vệ sinh, định giá, giám sát chợ búa và chỉnh trang đô thị được tập trung vào một mối; năm sau, Khu Thị chính số Sáu được lập ở Beyoğlu – Galata làm khu thí điểm. Bước đi này được coi là khởi đầu của nền quản lý đô thị hiện đại ở Ottoman.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["Hiệp ước Paris: Chiến tranh Crimea kết thúc và Ottoman được tiếp nhận vào hệ thống các nước châu Âu", "4aee0e2a"], "d": ["Hiệp ước Paris chấm dứt Chiến tranh Crimea đã tuyên bố Đế quốc Ottoman là thành viên bình đẳng của công pháp châu Âu và đặt sự toàn vẹn lãnh thổ của nó dưới sự bảo đảm chung của các cường quốc. Biển Đen được trung lập hóa, yêu sách bảo hộ thần dân Chính thống giáo mà Nga giành được kể từ Küçük Kaynarca bị vô hiệu hóa, và phần phía nam Bessarabia (các kaza Kiliya, Cahul, Izmail và Bolgrad) được trao cho Moldavia. Tuy nhiên, chính hiệp ước này lại biến Sắc lệnh Cải cách thành một cam kết quốc tế, qua đó hé mở cánh cửa cho sự can thiệp vào công việc nội bộ.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["Khánh thành cung Dolmabahçe: trung tâm cai trị rời khỏi Topkapı", "71ad26d0"], "d": ["Cung điện mà Abdülmecid đặt gia đình Balyan xây năm 1842 đã khánh thành sau mười bốn năm thi công, và trung tâm cai trị của đất nước chuyển từ Topkapı bốn thế kỷ tuổi sang bờ eo Bosphorus. Với phong cách châu Âu, cầu thang pha lê và Đại sảnh Nghi lễ, cung điện trở thành sự thể hiện bằng đá của tham vọng Tây phương hóa thời Tanzimat. Tuy nhiên, chi phí khổng lồ của nó trở thành một trong những khoản bị chỉ trích nhiều nhất trong những năm tài chính Ottoman lún vào vòng xoáy vay nợ nước ngoài.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["Wallachia và Moldavia hợp nhất dưới quyền Cuza: Romania ra đời", "baef4da5"], "d": ["Trong các cuộc bầu cử tổ chức sau Hiệp ước Paris, cả hai công quốc đều bầu Đại tá Alexandru Ioan Cuza làm voyvoda, qua đó thực hiện sự hợp nhất trên thực tế. Dù Triều đình Cổng Cao và Áo phản đối, việc đã rồi được Pháp ủng hộ buộc phải được chấp nhận. Liên hiệp này, trên giấy tờ vẫn lệ thuộc Ottoman, sẽ lấy tên Romania năm 1862 và đơn phương tuyên bố độc lập năm 1877; đây là bước ngoặt trong quá trình tan rã quyền thống trị của Ottoman dọc sông Danube.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Vụ Kuleli: âm mưu đảo chính đầu tiên chống Abdülmecid ở Istanbul", "e3653b21"], "d": ["Một hội kín gồm cả quân nhân lẫn dân sự, phản đối chính sách Tanzimat và quyền bình đẳng mà Sắc lệnh Cải cách công nhận cho người không theo Hồi giáo, đang lên kế hoạch phế truất sultan thì bị bắt quả tang khi đang họp tại thánh đường Kılıç Ali Pasha. Vì các bị cáo bị xét xử tại doanh trại Kuleli nên vụ việc được gọi theo tên này; các án tử hình được giảm thành lưu đày. Đây được coi là mưu toan đảo chính cung đình đầu tiên trong lịch sử Ottoman do một tổ chức được thành lập trên cơ sở ý thức hệ thực hiện.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["Nội chiến giữa người Druze và người Maronite ở Núi Liban và các biến loạn Damascus", "5595fdd6"], "d": ["Các cuộc đụng độ bùng phát vào tháng 5 năm 1860 sau khi hai người Druze bị giết gần Sidon đã biến thành cuộc nội chiến Druze – Maronite đẫm máu nhất trên vùng núi, đến tháng 7 lan sang Damascus và khiến hàng nghìn người Cơ Đốc giáo thiệt mạng. Khi Pháp đổ quân, Triều đình Cổng Cao phái Fuad Pasha đến vùng này với quyền hạn đặc biệt; một chiến dịch trấn áp quyết liệt được tiến hành. Các sự kiện trở thành cớ cho sự can thiệp của châu Âu và là nguyên nhân trực tiếp khiến Liban được hưởng quy chế đặc biệt.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["Tercüman-ı Ahval ra mắt: tờ báo tiếng Thổ Nhĩ Kỳ tư nhân đầu tiên ở Istanbul", "24792957"], "d": ["Tercüman-ı Ahval, do Agâh Efendi xuất bản và Şinasi đảm trách biên tập, là tờ báo tiếng Thổ Nhĩ Kỳ đầu tiên phát hành không có sự hỗ trợ của nhà nước. Lời dẫn trong số đầu tiên bênh vực quyền của dân chúng được lên tiếng về công việc của chính mình; tờ báo đăng nhiều kỳ vở “Hôn sự của thi sĩ” (Şair Evlenmesi) của Şinasi, qua đó cũng hé mở cánh cửa cho văn học Thổ Nhĩ Kỳ hiện đại. Sự ra đời của khái niệm công luận và báo chí đối lập ở Ottoman được gắn với thời điểm này.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["Quy chế Núi Liban: Liban được hưởng quy chế mutasarrıf đặc quyền", "bf375603"], "d": ["Quy chế được soạn thảo dưới sức ép của các cường quốc sau các cuộc thảm sát năm 1860 đã biến Núi Liban thành một đơn vị mutasarrıf đặc quyền, trực thuộc Triều đình Cổng Cao và được cai quản cùng một hội đồng hành chính lập theo thế cân bằng giữa các giáo phái. Quy chế quy định mutasarrıf phải là thần dân Ottoman theo Công giáo và việc bổ nhiệm phải được các cường quốc chấp thuận; mutasarrıf đầu tiên là Davud Pasha. Trật tự này kéo dài đến năm 1915 và tạo nên hạt nhân của nhà nước Liban hiện đại.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["Abdülmecid qua đời và Sultan Abdülaziz lên ngôi", "27204d7c"], "d": ["Khi Abdülmecid, người trong hai mươi hai năm trị vì đã ký Sắc lệnh Tanzimat và Sắc lệnh Cải cách, gục ngã vì bệnh lao, người em Abdülaziz lên ngôi. Trong những năm đầu, vị sultan mới mang lại hy vọng bằng các biện pháp tiết kiệm và lối sống giản dị; ông biến hải quân thành một trong những lực lượng hàng đầu thế giới. Tuy nhiên, vào cuối triều đại, nợ nước ngoài chồng chất, vụ vỡ nợ năm 1875 và các cuộc khởi nghĩa ở Balkan tích tụ lại, tạo nền cho cuộc phế truất năm 1876.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["Các công quốc hợp nhất lấy tên Romania", "d960e3fc"], "d": ["Wallachia và Moldavia, đã hợp nhất trên thực tế khi Cuza được bầu ở cả hai nơi năm 1859, đến năm 1862 gộp nghị viện và chính phủ vào một mối tại Bucharest và chính thức lấy tên Romania. Đế quốc Ottoman tuy vẫn giữ tư cách bá chủ về mặt pháp lý và khoản cống thuế hằng năm, trên thực tế đã mất quyền kiểm soát công quốc. Mốc thời gian này tượng trưng cho sự chấm dứt ảnh hưởng suốt bốn thế kỷ của Ottoman ở phía bắc sông Danube.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["Suakin, Massawa và Dahlak được sáp nhập vào Ai Cập", "a0924860"], "d": ["Massawa, nơi năm 1846 đã được Sultan Abdülmecid giao cho Muhammad Ali Pasha, người cai trị Ai Cập, cùng với Suakin dưới dạng salyane (khoán nguồn thu), đến thời khedive Ismail Pasha được đưa vào tài sản của Ai Cập cùng Dahlak và Suakin, và được tổ chức theo quy chế kaymakam (phó tỉnh). Như vậy ba hải cảng này trên bờ châu Phi của Biển Đỏ, tuy về pháp lý vẫn là lãnh thổ Ottoman, về hành chính đã chuyển từ trực thuộc Triều đình Cổng Cao sang Cairo — nhập vào cùng tầng lệ thuộc với các láng giềng Ai Cập và Sudan.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["Cuộc khởi nghĩa Crete bùng nổ (1866–1869)", "3679b861"], "d": ["Cuộc nổi dậy quy mô lớn bùng phát trên đảo với sự hỗ trợ công khai của Hy Lạp đã lần đầu tiên biến yêu sách enosis (sáp nhập vào Hy Lạp) của người Hy Lạp ở Crete thành vấn đề quốc tế. Cuộc chiến tranh du kích trên núi khốc liệt kéo dài ba năm khiến quân đội Ottoman chịu tổn thất nặng và gây tiếng vang lớn trong dư luận châu Âu. Cuộc khởi nghĩa chỉ lắng xuống khi Âli Pasha đến đảo năm 1868 và cho thi hành quy chế trao nhiều đặc quyền rộng rãi.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["Các đội đồn trú Ottoman cuối cùng rút khỏi Belgrade và các pháo đài Serbia", "b34217db"], "d": ["Trước sức ép của các cường quốc và yêu cầu kiên trì của Hoàng thân Mihailo, Triều đình Cổng Cao chấp nhận bỏ những căn cứ quân sự cuối cùng còn giữ ở Serbia; ngày 18 tháng 4 năm 1867, lá cờ Ottoman ở pháo đài Belgrade được hạ xuống và chìa khóa được trao cho hoàng thân. Như vậy sự hiện diện quân sự thực tế của Ottoman kéo dài từ năm 1521 chấm dứt, và trở ngại lớn cuối cùng trên con đường độc lập của Serbia được dỡ bỏ. Quyền bá chủ của sultan chỉ còn thu lại thành vấn đề mang tính tượng trưng về lá cờ và cống thuế.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["Trao danh hiệu khedive cho tổng đốc Ai Cập", "09e10c12"], "d": ["Nhờ cuộc vận động ráo riết và những khoản tiền đổ vào Istanbul của Ismail Pasha, thuộc thế hệ thứ ba của triều đại người Kavala, tổng đốc Ai Cập được trao danh hiệu khedive, nhấn mạnh rằng ông cao hơn các tổng đốc khác. Trong những năm đó, thể thức thừa kế cũng được đổi thành cha truyền con nối, và Ai Cập được công nhận những quyền hạn mang tính chủ quyền như vay nợ nước ngoài, ban huân chương và duy trì lãnh sự quán. Những bước này là mắt xích đầu tiên trong chuỗi đẩy nhanh sự tách rời về pháp lý của Ai Cập khỏi Ottoman.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["Quy chế Crete: trao đặc quyền hành chính rộng rãi cho hòn đảo", "12052262"], "d": ["Để chấm dứt cuộc khởi nghĩa ba năm, Đại tể tướng Âli Pasha đích thân đến đảo, và theo quy chế được công bố với sự chuẩn y của sultan, người Crete được hưởng các hội đồng hành chính hỗn hợp, tòa án địa phương, việc dùng tiếng Hy Lạp trong các thủ tục chính thức và ưu đãi thuế. Sự dàn xếp này giữ được quyền thống trị của Ottoman trên đảo thêm ba mươi năm. Tuy nhiên, các đặc quyền dành cho dân Cơ Đốc giáo đã làm suy yếu vị thế của người Crete Hồi giáo và gieo mầm cho cuộc khủng hoảng 1896–1898.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Khai mạc Hội đồng Nhà nước (Şura-yı Devlet): thành lập tòa án hành chính tối cao của Ottoman", "70b16497"], "d": ["Theo chiếu chỉ ngày 5 tháng 3 năm 1868, Hội đồng Tối cao về Pháp quy Tư pháp được tách làm hai: công việc hành chính – lập pháp giao cho Hội đồng Nhà nước, công việc xét xử giao cho Viện Pháp quy Tư pháp (Divan-ı Ahkâm-ı Adliyye); cơ quan này được khai mạc trọng thể tại Triều đình Cổng Cao và Midhat Pasha được cử làm chủ tịch đầu tiên. Cơ quan được giao soạn dự thảo luật, giải quyết tranh chấp hành chính và xét xử công chức. Với thành phần hỗn hợp gồm cả người Hồi giáo và không Hồi giáo, đây được coi là sự vận dụng mang tính thể chế đầu tiên của tư tưởng phân quyền ở Ottoman.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["Khai thông kênh đào Suez: con đường sang Ấn Độ qua Ai Cập được rút ngắn", "377ccd04"], "d": ["Công trình khởi công năm 1859 kéo dài mười năm, và con kênh dài 163 kilômét nối Địa Trung Hải với Biển Đỏ được đưa vào sử dụng trong một buổi lễ hoành tráng. Khi đường từ châu Âu sang Ấn Độ rút ngắn hàng nghìn dặm, Ai Cập bỗng trở thành điểm then chốt của thương mại thế giới. Giá trị địa chiến lược này sẽ là nguyên nhân chính khiến Anh chiếm đóng Ai Cập mười ba năm sau khi kênh khai thông; còn món nợ mà con kênh đặt lên Ai Cập sẽ đẩy chính quyền khedive đến chỗ vỡ nợ.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["Thành lập Giáo hội Exarchate Bulgaria: giáo hội Bulgaria tách khỏi Phanar", "33a8272c"], "d": ["Theo sắc lệnh firman của sultan, một giáo hội Bulgaria độc lập (exarchate) tách khỏi Tòa Thượng phụ Hy Lạp được thành lập, và việc kaza nào sẽ thuộc exarchate được để cho dân chúng bỏ phiếu quyết định. Triều đình Cổng Cao thực hiện bước này nhằm phá ảnh hưởng của người Hy Lạp, nhưng kết quả lại ngược lại: giáo hội trở thành trung tâm có tổ chức của bản sắc dân tộc Bulgaria và yêu sách của Bulgaria đối với Macedonia. Như vậy nền tảng thể chế cho cuộc cạnh tranh Bulgaria – Hy Lạp – Serbia ở Balkan và các cuộc khởi nghĩa năm 1876 đã được đặt.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["Asir được đặt dưới sự cai quản trực tiếp", "4559e099"], "d": ["Khi giá trị chiến lược của Biển Đỏ tăng lên nhờ kênh đào Suez khai thông, người ta nhận thấy không thể bỏ mặc không kiểm soát dãy núi Asir nằm giữa đường bộ đi Yemen. Lực lượng của Redif Pasha, đang trong chiến dịch Yemen, tiến vào Abha, đưa vùng này vào quyền cai quản trực tiếp của Ottoman, và sanjak Asir được lập. Do địa hình núi non và ảnh hưởng của dòng Idrisi, quyền thống trị này không bao giờ thật sự vững chắc.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Chiến dịch Najd của Midhat Pasha: tái lập quyền thống trị của Ottoman ở al-Ahsa", "7db51461"], "d": ["Lợi dụng cuộc tranh giành ngôi trong dòng họ Saud, tổng đốc Baghdad Midhat Pasha đã điều quân đến bờ tây vịnh Basra và sáp nhập vùng al-Ahsa vào tỉnh Basra với tên sanjak Najd. Abdullah ibn Faisal được bổ nhiệm làm mutasarrıf, và quyền thống trị của Ottoman được thiết lập trên giấy tờ. Chiến dịch nhằm ngăn chặn sự lan rộng ảnh hưởng của Anh ở vùng vịnh, và ngay trong năm đó dẫn đến việc Qatar cũng rơi vào sự kiểm soát của Ottoman.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["Đại tể tướng Âli Pasha qua đời: thế hệ nhân sự Tanzimat chấm dứt", "1cf0141c"], "d": ["Với cái chết của Âli Pasha, người một mình gánh vác chính sách Tanzimat sau khi Fuad Pasha mất năm 1869, thế hệ những nhà ngoại giao lão luyện điều hành chính sách đối ngoại của đất nước suốt ba mươi năm đã cạn kiệt. Sự cai trị thân Nga và tùy tiện của người kế nhiệm Mahmud Nedim Pasha đã củng cố quyền cai trị cá nhân của Abdülaziz. Trong vòng năm năm sau khi Âli Pasha qua đời, tài chính vỡ nợ, Balkan nổi dậy và việc thay đổi ngôi vua trở nên không thể tránh khỏi.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["Thiết lập sự kiểm soát của Ottoman tại Qatar", "3b453165"], "d": ["Theo lời mời của Sheikh Jassim ibn Thani, người đang chịu sức ép của Anh, lực lượng Ottoman đã đổ bộ lên bán đảo Qatar, và vào mùa thu năm 1871 sự kiểm soát của Ottoman được thiết lập trong vùng. Qatar được tổ chức thành một kaza thuộc sanjak Najd, và sheikh được bổ nhiệm làm kaymakam. Bước đi này là thành quả cụ thể nhất của chính sách tiến công mà Midhat Pasha theo đuổi chống Anh ở vùng vịnh; cờ Ottoman tung bay trên bán đảo cho đến năm 1913.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["Sắc lệnh kế vị cho Tunisia — chức bey thuộc về gia đình Mehmed Sadık Pasha", "1509ebb0"], "d": ["Theo sắc lệnh firman ban ra nhờ nỗ lực của Hayreddin Pasha, được bey Tunis Mehmed Sadık Pasha phái đến Istanbul, người lợi dụng cơ hội Pháp thất bại trước Phổ, Tunisia được trao cho Mehmed Sadık Pasha và con cháu theo chế độ cha truyền con nối, với điều kiện vẫn trực thuộc Istanbul. Nếu không được sultan cho phép thì không được đàm phán chiến tranh và hòa bình, không được nhượng bất kỳ đất đai nào của xứ cho người khác, và phải đáp ứng yêu cầu cung cấp quân của Ottoman. Pháp không công nhận sắc lệnh; mười năm sau, nước này chiếm đóng Tunisia.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["Chiếm Sanaa: tái lập quyền lực Ottoman ở Yemen", "978e20a0"], "d": ["Khi giá trị chiến lược của Biển Đỏ tăng lên nhờ kênh đào Suez khai thông, Triều đình Cổng Cao đã điều đến Yemen đạo quân Fırka-i İhtiyatiye dưới quyền Ahmed Muhtar Pasha. Với việc chiếm được Sanaa, quyền lực nhà nước được tái lập ở nội địa Yemen, nơi trên thực tế đã mất từ hai thế kỷ trước, và vùng này được tổ chức thành tỉnh. Tuy nhiên, cuộc đấu tranh với các imam Zaydi không bao giờ chấm dứt; các cuộc khởi nghĩa năm 1891, 1898 và 1904 tạo thành mặt trận nội bộ tốn kém nhất và kéo dài nhất của Ottoman. Những nơi khác được sáp nhập cùng thời điểm này: Sanaa, Taiz.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["Cuộc khởi nghĩa Herzegovina bùng nổ: Vấn đề phương Đông lại bùng cháy", "571b18ec"], "d": ["Cuộc nổi dậy của nông dân Cơ Đốc giáo quanh Nevesinje, do thuế nặng và sức ép của giới thân hào ayan, chẳng bao lâu lan ra toàn Herzegovina và được tiếp sức bởi quân tình nguyện từ Serbia và Montenegro. Cuộc khởi nghĩa, dẫn đến việc Áo và Nga áp đặt cải cách, năm sau đã châm ngòi cho các cuộc nổi dậy của người Bulgaria và các lời tuyên chiến của Serbia và Montenegro. Như vậy mắt xích đầu tiên đã bị phá vỡ trong chuỗi lớn dẫn đến Chiến tranh Nga – Ottoman 1877–78 và việc mất Balkan theo Hiệp ước Berlin.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["Tài chính Ottoman vỡ nợ: giảm một nửa các khoản trả nợ nước ngoài", "2cac2fa5"], "d": ["Các khoản vay liên tiếp từ năm 1854, chi phí Chiến tranh Crimea, việc xây cung điện và nạn đói ở Anatolia năm 1873–74 đã biến thâm hụt ngân sách thành một vực thẳm vượt quá năm triệu lira. Chính phủ Mahmud Nedim Pasha tuyên bố giảm một nửa các khoản trả lãi và gốc nợ trong thời hạn năm năm, trên thực tế là tuyên bố hoãn nợ. Quyết định gây phản ứng mạnh ở các sở giao dịch chứng khoán châu Âu này đã khởi động tiến trình mà sáu năm sau kết thúc bằng Sắc lệnh Muharrem và việc thành lập Cơ quan Quản lý Nợ công (Düyun-ı Umumiye).", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["Murad V bị phế truất và Abdülhamid II lên ngôi", "cffb2271"], "d": ["Murad V, lên ngôi sau khi Abdülaziz bị phế truất, đã không thể đảm đương nhiệm vụ vì sức khỏe tinh thần bị chấn động bởi cái chết của người bác và vụ Hasan người Circassia; trong chín mươi ba ngày trị vì, ông chỉ tỉnh táo trong bảy ngày. Ông bị phế truất theo fatwa của Sheikh al-Islam, và người em Abdülhamid II được đưa lên thay. Vị sultan mới lên ngôi sau khi hứa với Midhat Pasha sẽ ban bố nền quân chủ lập hiến; một thời đại kéo dài ba mươi ba năm bắt đầu.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["Hội nghị Tersane (Xưởng hải quân): các cường quốc áp đặt cải cách ở Balkan", "b5006a2c"], "d": ["Hội nghị do các cường quốc triệu tập tại Istanbul để giải quyết khủng hoảng Balkan đã đòi chia Bulgaria thành hai tỉnh tự trị và thực hiện cải cách dưới sự giám sát quốc tế ở Bosnia-Herzegovina. Ngay ngày khai mạc hội nghị, Triều đình Cổng Cao dùng loạt đại bác loan báo việc công bố Hiến pháp (Kanun-ı Esasi), tìm cách đáp lại sự áp đặt bằng cải cách hiến pháp. Các đại biểu coi đó là kế trì hoãn và giải tán ngày 20 tháng 1 năm 1877; bốn tháng sau, Nga tuyên chiến.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["Hạ viện (Meclis-i Mebusan) đầu tiên khai mạc tại Dolmabahçe", "429bb279"], "d": ["115 nghị viên được bầu theo Hiến pháp đã nhóm họp lần đầu ngày 19 tháng 3 năm 1877 trong buổi lễ tại Đại sảnh Nghi lễ của cung Dolmabahçe; như vậy thời kỳ nghị viện đại diện trong lịch sử Ottoman bắt đầu. Các nghị viên Hồi giáo và không Hồi giáo chất vấn chính phủ gay gắt, tranh luận về việc điều hành chiến tranh và trách nhiệm của các bộ trưởng. Sự đối lập táo bạo này sẽ là nguyên nhân chính rút ngắn tuổi thọ của nghị viện.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["Cuộc phòng thủ Plevna bắt đầu: sự kháng cự của Gazi Osman Pasha", "0e04a878"], "d": ["Trong Chiến tranh Nga – Ottoman 1877–78, Osman Pasha hành quân từ Vidin đến Plevna nhằm chặn đường đến Istanbul của quân đội Nga đã vượt sông Danube; ông củng cố thị trấn bằng các đồn lũy và chiến hào, mở đầu cuộc phòng thủ huyền thoại kéo dài năm tháng. Ba cuộc tấn công lớn liên tiếp của Nga – Romania bị đẩy lui với tổn thất nặng, và quân đội do chính Sa hoàng Alexander II chỉ đạo buộc phải chuyển sang vây hãm. Plevna đi vào lịch sử như thành tích phòng thủ rực rỡ nhất của quân đội Ottoman trong thế kỷ 19.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["Plevna thất thủ: mặt trận sông Danube sụp đổ", "185e7602"], "d": ["Hết lương thực sau năm tháng bị vây, Osman Pasha tiến hành cuộc đột phá vòng vây qua sông Vit; khi ông bị thương và bị bắt, thành phố đầu hàng. Các chỉ huy Nga trả lại thanh gươm để chào vị pasha mà họ bắt làm tù binh, và Osman Pasha được trao danh hiệu “Gazi”. Plevna thất thủ đã mở đường cho quân đội Nga; trong vòng hai tháng, Sofia, Plovdiv và Edirne thất thủ, và quân tiên phong Nga tiến đến Yeşilköy.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["Quân Nga chiếm đóng Sofia", "ef369d22"], "d": ["Quân đội Nga vượt dãy Balkan sau khi Plevna thất thủ đã tiến vào Sofia không được phòng thủ. Thành phố không bao giờ trở lại quyền cai quản của Ottoman nữa; cuối năm 1878 nó thuộc Công quốc Bulgaria tự trị, và từ năm 1879 trên thực tế là thủ đô của công quốc này. Trên bản đồ, từ thời điểm này Sofia rời quyền cai quản trực tiếp của Ottoman, chuyển sang chiếm đóng tạm thời của Nga rồi sau đó là chính quyền tự trị Bulgaria.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["Hiệp định đình chiến Edirne: tiếng súng im trong Chiến tranh Nga – Ottoman 1877–78", "1f899180"], "d": ["Trước việc Sofia, Plovdiv và Edirne nối tiếp nhau thất thủ và quân đội Nga áp sát bờ biển Marmara, Triều đình Cổng Cao buộc phải xin đình chiến. Hiệp định ngừng bắn ký tại Edirne buộc Ottoman chấp nhận các điều kiện hòa bình sơ bộ như quyền tự trị cho Bulgaria, độc lập cho Montenegro, Serbia và Romania cùng khoản bồi thường chiến phí nặng nề. Một tháng sau, những điều kiện này được chuyển thành văn bản hiệp ước tại San Stefano.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Abdülhamid II đình hoạt động Hạ viện vô thời hạn", "e770b540"], "d": ["Trước sự chỉ trích gay gắt của các nghị viên quy trách nhiệm cho chính phủ và hoàng cung về kết cục thảm họa của cuộc chiến, Abdülhamid II, dựa vào quyền hạn mà Hiến pháp trao cho mình, đã đình hoạt động nghị viện vô thời hạn. Nghị viện Ottoman đầu tiên, hoạt động khoảng mười một tháng, như vậy bị đóng cửa, và thời kỳ chuyên chế kéo dài ba mươi năm bắt đầu. Nghị viện chỉ có thể nhóm họp lại sau cuộc Cách mạng năm 1908.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["Hiệp ước San Stefano: đề án Đại Bulgaria", "2c7cc611"], "d": ["Hiệp ước San Stefano chấm dứt Chiến tranh Nga – Ottoman 1877–78 đã lập ra một Bulgaria tự trị khổng lồ trải đến biển Aegea và bao gồm cả Macedonia; công nhận độc lập của Serbia, Montenegro và Romania; nhượng Kars, Ardahan, Batumi và Doğubayazıt cho Nga, đồng thời áp đặt khoản bồi thường chiến phí không thể trả nổi. Văn bản đưa Nga xuống Địa Trung Hải này vấp phải phản ứng dữ dội của Anh và Áo. Chưa kịp thi hành, trong vòng bốn tháng nó đã bị sửa đổi tại Hội nghị Berlin; dù vậy nó vẫn là văn kiện tuyên bố hồi kết của Rumelia thuộc Ottoman.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["Kars, Ardahan và Batumi bị nhượng cho Nga — Ba tỉnh Elviye-i Selase", "99bdfad2"], "d": ["Theo Hiệp ước Berlin, Đế quốc Ottoman nhượng Kars, Ardahan và Batumi cho Nga để trừ một phần khoản bồi thường chiến phí; còn Doğubayazıt và thung lũng Eleşkirt, vốn được trao cho Nga tại San Stefano, vẫn thuộc Ottoman. Batumi được trao với quy chế cảng tự do, nhưng chỉ giữ được quy chế này đến năm 1886. Người Nga biến Kars thành một tỉnh trực thuộc phủ tổng đốc toàn quyền Ngoại Kavkaz đóng tại Tbilisi; số cư dân từ Ba tỉnh Elviye-i Selase buộc phải di cư về phía Erzurum lên đến 100.000 người. Cũng theo hiệp ước này, miền Nam Bessarabia (Kiliya, Cahul, Bolgrad) được Romania trả lại cho Nga.", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Áo-Hung chiếm đóng Bosnia-Herzegovina và Novi Pazar", "e5f901df"], "d": ["Dựa trên quyền hạn do Hiệp ước Berlin trao, quân đội Áo-Hung tiến vào Bosnia; dù chính phủ Ottoman chấp nhận không kháng cự, dân địa phương Hồi giáo và Chính thống giáo ở Sarajevo và Mostar đã cầm vũ khí và kháng cự quyết liệt suốt ba tháng. Cuộc chiếm đóng chỉ hoàn tất ngày 20 tháng 10 năm 1878. Chủ quyền pháp lý của sultan còn tồn tại trên giấy tờ đến năm 1908, nhưng xứ Bosnia thuộc Ottoman suốt bốn thế kỷ trên thực tế đã mất, và một làn sóng di cư lớn của người Hồi giáo bắt đầu. Các điểm định cư khác bị mất cùng ngày: Banja Luka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Sắc lệnh Muharrem và việc thành lập Cơ quan Quản lý Nợ công (Düyun-ı Umumiye)", "02b7cc03"], "d": ["Các cuộc đàm phán với đại diện các nước chủ nợ sau vụ vỡ nợ năm 1875 đã kết thúc bằng sắc lệnh ngày 28 Muharram 1299 (20 tháng 12 năm 1881): nợ gốc được giảm hơn một nửa, đổi lại các khoản thu béo bở nhất như thuế muối, thuốc lá, tơ lụa, tem và thuế cá được chuyển thẳng cho Cơ quan Quản lý Nợ công do các chủ nợ điều hành. Sử dụng hàng nghìn viên chức, cơ quan này trở thành một bộ máy tài chính riêng ngay trong lòng nhà nước. Đây được coi là thời điểm nền độc lập tài chính của Ottoman trên thực tế chấm dứt.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Suakin — hải cảng duy nhất không rơi vào tay Mahdi", "5a37b198"], "d": ["Từ tháng 2 năm 1884, trong khi toàn bộ các vùng miền đông Sudan ngoài Suakin rơi vào quyền thống trị của Muhammad Ahmad al-Mahdi, hải cảng vẫn trụ được nhờ sự bảo vệ quân sự của một lực lượng Anh gồm ba tiểu đoàn dưới quyền tướng Graham. Đây là khởi đầu của thời kỳ tình trạng thực tế và pháp lý tách rời nhau: tuy bờ biển trên thực tế nằm dưới sự kiểm soát quân sự của Anh, năm 1885 mối liên hệ hành chính của nó được lấy khỏi Ai Cập và gắn trực tiếp vào tỉnh Yemen, tức Triều đình Cổng Cao — trật tự này kéo dài cho đến khi chấm dứt năm 1888 với việc Pháp chiếm đóng Zeila.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Midhat Pasha bị giết trong ngục Taif", "f4562261"], "d": ["Midhat Pasha, kiến trúc sư của Hiến pháp và là nhân vật biểu tượng của Thời kỳ Lập hiến thứ nhất, bị tòa án Yıldız kết tội trong vụ cái chết của Abdülaziz, được giảm án tử hình thành lưu đày và đưa đến Taif. Theo ghi chép của TDV, ông bị bóp cổ chết trong phòng giam đêm 7–8 tháng 5 năm 1884, còn nguyên nhân chính thức được công bố là bệnh nhọt than (şirpençe). Cái chết của ông trở thành biểu tượng cho việc thanh trừng phe đối lập lập hiến dưới thời Abdülhamid II.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Nhượng quyền đường sắt Haydarpaşa – Ankara cho người Đức", "5705b163"], "d": ["Theo chiếu chỉ của sultan, quyền xây dựng và khai thác tuyến Haydarpaşa – Ankara được trao cho chủ ngân hàng Alfred von Kaulla, đại diện Deutsche Bank, và Công ty Đường sắt Anatolia được thành lập. Nhượng quyền này là bước ngoặt phá vỡ thế độc quyền Anh – Pháp trong giao thông và chính sách đối ngoại của Ottoman, đồng thời đặt nền ảnh hưởng của Đức. Cùng với nhượng quyền tuyến Baghdad trao cho chính công ty này mười một năm sau, giấc mơ “Berlin – Baghdad” ra đời và trở thành một trong những trục chính của cuộc cạnh tranh giữa các cường quốc trước Thế chiến thứ nhất.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Thành lập Hội Thống nhất Ottoman (İttihad-ı Osmani) ở Istanbul", "b7187939"], "d": ["Bốn sinh viên Trường Quân y đã lập Hội Thống nhất Ottoman làm tổ chức bí mật chống chế độ chuyên chế; chẳng bao lâu tổ chức này biến thành Ủy ban Liên hiệp và Tiến bộ, nơi tập hợp dưới mái nhà chung mọi phần tử đối lập của phong trào Thanh niên Thổ. Tổ chức theo mô hình chi bộ đã hợp nhất với những người lưu vong ở châu Âu và các sĩ quan ở Salonika. Chính đội ngũ xuất thân từ chi bộ sinh viên nhỏ bé này đã buộc ban bố Thời kỳ Lập hiến thứ hai năm 1908 và độc quyền cai trị đất nước sau năm 1913.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Vụ đột kích Ngân hàng Ottoman: hành động của các chiến binh Dashnak ở Galata", "08b3095f"], "d": ["Một nhóm vũ trang của tổ chức Armenia Dashnaktsutyun đã đột kích trụ sở chính Ngân hàng Ottoman ở Galata, bắt con tin và đe dọa cho nổ tòa nhà nhằm thu hút sự chú ý của châu Âu đến vấn đề Armenia. Nhờ các đại sứ can thiệp, cuộc khủng hoảng kết thúc với việc đổi lại các kẻ hành động được đưa ra khỏi nước trên một con tàu. Những sự kiện đẫm máu ở Istanbul trong những ngày sau vụ đột kích đã đóng vai trò quyết định trong việc biến vấn đề Armenia thành đòn bẩy can thiệp quốc tế.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["Chiến tranh Ottoman – Hy Lạp 1897 bùng nổ: mặt trận Thessaly", "33e490ab"], "d": ["Trước việc Hy Lạp đổ hải quân và binh lính lên Crete cùng các cuộc tấn công của các toán vũ trang ở biên giới Rumelia, Đế quốc Ottoman tuyên chiến. Quân đội Ottoman, được phái đoàn cải cách Đức huấn luyện, tiến nhanh ở Thessaly và trong vòng một tháng chiếm Larissa, Farsala và Domokos; quân đội Hy Lạp tan rã. Do các cường quốc can thiệp, lãnh thổ giành được bị trả lại, nhưng cuộc chiến vẫn là chiến thắng quân sự dứt khoát duy nhất dưới thời Abdülhamid II và không ngăn được việc mất Crete trên thực tế.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Nhượng quyền tuyến Konya – Baghdad cho người Đức", "fd8b6cbd"], "d": ["Sau chuyến thăm Istanbul và Damascus năm 1898 của Hoàng đế Wilhelm II, Công ty Đường sắt Anatolia được trao nhượng quyền sơ bộ cho tuyến từ Konya đến Baghdad và Basra. Dự án đường sắt Baghdad đối với Ottoman có nghĩa là củng cố sự kiểm soát trung ương đối với các tỉnh Ả Rập, còn đối với Đức là vươn đến vịnh Basra. Bị Anh và Nga phản đối kịch liệt, dự án trở thành một trong những hồ sơ gây tranh cãi nhất của cuộc cạnh tranh đế quốc dẫn đến Thế chiến thứ nhất.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Khởi công đường sắt Hejaz tại Damascus", "62f58f68"], "d": ["Tuyến đường mà Abdülhamid II ra lệnh xây theo chiếu chỉ ngày 2 tháng 5 năm 1900 đã được khởi công bằng buổi lễ chính thức tại Damascus ngày 1 tháng 9 năm 1900. Được thực hiện hoàn toàn bằng tiền quyên góp từ thế giới Hồi giáo và công sức của các kỹ sư – binh sĩ Ottoman, dự án rút ngắn hành trình Damascus – Medina của người hành hương từ bốn mươi ngày xuống năm ngày. Đây vừa là công trình uy tín củng cố quyền uy tinh thần của chức caliph, vừa là khoản đầu tư chiến lược tăng cường kiểm soát quân sự đối với Hejaz.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Chương trình Mürzsteg: giám sát quốc tế cải cách ở Macedonia", "4c7464da"], "d": ["Sau cuộc khởi nghĩa Ilinden, hoàng đế Nga và hoàng đế Áo gặp nhau tại Mürzsteg và soạn một gói cải cách mới cho Macedonia. Chương trình dự kiến đặt hai ủy viên dân sự nước ngoài bên cạnh tổng thanh tra Ottoman, cho các sĩ quan châu Âu tổ chức lại hiến binh và thay đổi ranh giới hành chính theo nguyên tắc dân tộc. Triều đình Cổng Cao kháng cự với lý do quyền chủ quyền bị xâm phạm, nhưng trước sức ép chung buộc phải chấp nhận; chương trình trở thành một trong những nhân tố chính thúc đẩy việc tổ chức của phái Liên hiệp trong giới sĩ quan trẻ.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["Murad V qua đời", "396659a7"], "d": ["Murad V, ở ngôi khoảng ba tháng năm 1876 rồi bị phế truất, sau những mưu toan đưa ông trở lại ngôi đã sống hai mươi tám năm trong cảnh giam cầm dưới sự canh giữ nghiêm ngặt và chết vì bệnh tiểu đường. Ông được an táng bên cạnh mẹ trong lăng Cedid Havatin ở thánh đường Yeni Cami. Ông đi vào lịch sử như vị sultan Ottoman ở ngôi ngắn nhất.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Sanaa rơi vào tay Imam Yahya", "e7f876cb"], "d": ["Cuộc nổi dậy do imam Zaydi Yahya Hamid al-Din phát động năm 1904 kết thúc với việc Sanaa thất thủ sau cuộc vây hãm vào tháng 4 năm 1905; thành phố thoát khỏi quyền cai quản của Ottoman, và trong suốt thời gian bị vây, nạn đói và dịch bệnh bùng phát. Địa hình núi non của Yemen, đường tiếp tế dài và tính chính danh tại chỗ của chế độ imam Zaydi khiến quyền thống trị của Ottoman ở đây mong manh ngay từ khi thiết lập. Năm tháng sau, thành phố được lấy lại với tổn thất nặng nề, nhưng vấn đề Yemen mãi đến năm 1918 mới khép lại.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Vụ ám sát Yıldız: tấn công bằng bom nhằm vào Abdülhamid II", "1ee2e1a6"], "d": ["Tổ chức Dashnaktsutyun tiến hành ám sát bằng cách cho nổ một chiếc xe ngựa landau gài bom hẹn giờ nhằm vào xe của sultan khi ông rời lễ cầu nguyện thứ Sáu có nghi thức triều đình; việc Abdülhamid trò chuyện với Sheikh al-Islam nên chậm vài phút đã cứu mạng ông. Vụ nổ làm hai mươi sáu người chết và hơn năm mươi người bị thương. Sự kiện càng làm trầm trọng thêm nỗi ám ảnh an ninh của sultan và nền cai trị chuyên chế dựa trên mạng lưới mật thám; nó cũng trở thành đề tài bài thơ “Một khoảnh khắc chậm trễ” của Tevfik Fikret.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Thu hồi Sanaa: dẹp cuộc nổi dậy của Imam Yahya", "dec3b8f9"], "d": ["Cuộc nổi dậy bắt đầu năm 1904 dưới sự lãnh đạo của imam Zaydi Yahya kết thúc với việc Sanaa thất thủ vào tháng 4 năm 1905, và nạn đói cùng dịch bệnh bùng phát trong thành phố. Các đạo quân tăng viện dưới quyền Ali Rıza Pasha và Ahmed Feyzi Pasha, bằng chiến dịch tiến hành từ ngày 15 tháng 7 đến ngày 1 tháng 9 năm 1905 với sự hỗ trợ của lực lượng ở Taiz, đã lấy lại thành phố với tổn thất nặng nề và dẹp tan cuộc nổi dậy. Chiến dịch Yemen gây cho quân đội Ottoman hàng chục nghìn tổn thất và gánh nặng tài chính khổng lồ; trong giới sĩ quan ở Rumelia, nỗi sợ “bị đày đi Yemen” là một trong những bất mãn hàng đầu nuôi dưỡng việc tổ chức của phái Liên hiệp.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Hạ viện đầu tiên của Thời kỳ Lập hiến thứ hai nhóm họp", "e7fd2716"], "d": ["Nghị viện hình thành qua cuộc bầu cử hai cấp tổ chức sau ba mươi năm gián đoạn đã khai mạc ngày 17 tháng 12 năm 1908 bằng diễn văn của sultan, và Ahmed Rıza Bey, lãnh tụ phong trào Thanh niên Thổ, được bầu làm chủ tịch. Nghị viện gồm các nghị viên Thổ, Ả Rập, Albania, Hy Lạp, Armenia và Do Thái là thử nghiệm lớn cuối cùng của lý tưởng chủ nghĩa Ottoman. Tuy nhiên, việc Bulgaria tuyên bố độc lập, Bosnia bị sáp nhập và Crete tuyên bố gia nhập Hy Lạp đã phủ bóng lên niềm lạc quan này trước cả khi nghị viện khai mạc.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Đạo quân Hành động và việc phế truất Abdülhamid II: Mehmed V Reşad lên ngôi", "6a65a704"], "d": ["Đạo quân Hành động khởi hành từ Salonika sau Sự biến ngày 31 tháng 3, đã tiến vào Istanbul theo bốn cánh trong đêm 22–23 tháng 4, và ngày 24 tháng 4 cung Yıldız đầu hàng. Ngày 27 tháng 4, Quốc hội Toàn thể quyết định phế truất Abdülhamid II; vị sultan bị đưa đến Salonika, và người em Mehmed V Reşad được đưa lên ngôi. Nền cai trị cá nhân ba mươi ba năm như vậy chấm dứt, nhưng được thay bằng một thời kỳ mới trong đó sultan chỉ còn là biểu tượng, còn Ủy ban Liên hiệp và Tiến bộ cai trị với sự hậu thuẫn của quân đội.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Cuộc nổi dậy Albania: kháng chiến vũ trang ở Kosovo và Shkodra", "93ed30c6"], "d": ["Chính sách thuế tập quyền, chiến dịch thu vũ khí và cuộc tranh cãi về bảng chữ cái Latinh của chính phủ phái Liên hiệp đã khiến các bộ tộc Albania, vốn trước đó được coi là thuộc số những thành phần trung thành nhất với nhà nước, nổi dậy. Quân đội dưới quyền Mahmud Şevket Pasha tuy đàn áp khởi nghĩa một cách quyết liệt, nhưng tình trạng bất an lại bùng lên vào các năm 1911 và 1912. Những cuộc nổi dậy này vừa làm hao mòn quân đội Ottoman ngay trước Chiến tranh Balkan, vừa đẩy nhanh sự ra đời của phong trào dân tộc Albania.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Hiệp ước Ouchy: nhượng Tripoli (Libya) và Benghazi cho Ý", "4ffa1fd2"], "d": ["Trước việc các nước Balkan chuẩn bị chiến tranh, Triều đình Cổng Cao không dám chấp nhận đụng độ trên hai mặt trận nên đã ký hòa ước bí mật với Ý tại thị trấn Ouchy của Thụy Sĩ và từ bỏ Tripoli và Benghazi. Đế quốc Ottoman như vậy mất mảnh đất cuối cùng ở châu Phi; bù lại, việc trả lại Rhodes và quần đảo Mười Hai Đảo do Ý chiếm đóng được hứa hẹn, nhưng lời hứa này không bao giờ được thực hiện. Khi hiệp ước được ký, Chiến tranh Balkan đã bùng nổ từ lâu. Với sự kiện này, Murzuk (Fezzan), Ghat, Sabha, Ubari, Traghan, Zawila và al-Qatrun (sanjak Fezzan thuộc tỉnh Tripoli) chuyển sang quyền cai quản của Ý.", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["Hy Lạp chiếm đóng Lemnos", "9555af1d"], "d": ["Trong Chiến tranh Balkan lần thứ nhất, hải quân Hy Lạp chiếm đóng Lemnos; cảng Moudros trên đảo trở thành căn cứ phong tỏa eo Dardanelles. Đảo được để cho Hy Lạp tại Lausanne (24 tháng 7 năm 1923).", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["Hy Lạp chiếm đóng Thasos", "6c03c7f0"], "d": ["Trong Chiến tranh Balkan lần thứ nhất, Hy Lạp chiếm đóng Thasos và Samothrace.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["Hy Lạp chiếm đóng Samothrace", "911e82a3"], "d": ["Trong Chiến tranh Balkan lần thứ nhất, Hy Lạp chiếm đóng Samothrace.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["Hy Lạp chiếm đóng Lesbos", "6b2b07ba"], "d": ["Hải quân Hy Lạp đổ bộ lên Lesbos; đảo bị lục quân và hải quân Hy Lạp chiếm vào cuối Chiến tranh Balkan lần thứ nhất. Hội nghị London (tháng 5 năm 1913) xác nhận tình trạng này.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["Hy Lạp đổ bộ lên Chios", "901c6539"], "d": ["Chios, bị pháo kích ngày 7 tháng 4 năm 1912, trong Chiến tranh Balkan lần thứ nhất bị quân Hy Lạp đổ bộ; đội đồn trú Ottoman đầu hàng ngày 3 tháng 1 năm 1913. Theo Hiệp ước Lausanne (24 tháng 7 năm 1923), đảo được để cho Hy Lạp.", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Đại tể tướng Mahmud Şevket Pasha bị ám sát tại Istanbul", "68e60e63"], "d": ["Mahmud Şevket Pasha, được đưa lên chức Đại tể tướng sau cuộc đột kích Triều đình Cổng Cao, bị bắn chết trong xe gần Çarşıkapı khi đang đến Bộ Chiến tranh. Ủy ban Liên hiệp và Tiến bộ đổ vụ ám sát cho phe đối lập, mở một làn sóng bắt bớ và hành quyết rộng rãi, và Đảng Tự do và Hòa hợp trên thực tế bị thanh trừng. Với sự kiện này, nền độc tài một đảng của phái Liên hiệp dựa trên bộ ba Enver – Talat – Cemal được thiết lập dứt khoát.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Chiến tranh Balkan lần thứ hai bùng nổ: cuộc tranh giành chia phần giữa các đồng minh", "48d088a2"], "d": ["Các đồng minh Balkan không chia nổi lãnh thổ lấy từ Ottoman theo Hiệp ước London đã quay sang đánh nhau; chiến tranh lần thứ hai bắt đầu khi Bulgaria tấn công các vị trí của Serbia và Hy Lạp. Khi Romania và Montenegro cũng tham chiến chống Bulgaria, quân đội Bulgaria sụp đổ. Đế quốc Ottoman tận dụng cơ hội này, vượt qua đường Midye – Enez do Hiệp ước London vạch ra và lấy lại miền Đông Thrace cùng với Edirne.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Hiệp ước Istanbul: hòa bình với Bulgaria và xác nhận Edirne", "c8c18b2d"], "d": ["Hiệp ước ký giữa Đế quốc Ottoman và Bulgaria sau Chiến tranh Balkan lần thứ hai đã lấy sông Maritsa làm biên giới và xác nhận về mặt pháp lý rằng Edirne, Kırklareli, Didymoteicho và miền Đông Thrace vẫn thuộc Ottoman. Alexandroupoli (Dedeağaç) được để cho Bulgaria (còn Kavala, sau khi bị Bulgaria chiếm đóng mùa thu năm 1912, đã chuyển sang Hy Lạp vào tháng 7 năm 1913 và được xác nhận thuộc Hy Lạp theo Hiệp ước Bucharest ngày 10 tháng 8 năm 1913); việc trao đổi dân cư giữa hai nước và quyền của người Hồi giáo ở Bulgaria được quy định. Văn bản này là bảo đảm cho mảnh đất duy nhất có thể lấy lại được sau thảm họa Balkan. Nơi khác được tính cùng ngày này: Komotini.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["Lấy lại Tenedos và Imbros — Hiệp ước Athens", "ec084d09"], "d": ["Trong số các đảo bắc Aegea bị Hy Lạp chiếm đóng trong Chiến tranh Balkan, Tenedos (Bozcaada) và Imbros, trấn giữ cửa eo biển, được coi trong cuộc đàm phán Hiệp ước Athens là không thể thiếu cho việc phòng thủ Dardanelles và được trả lại cho Ottoman. Các đảo khác ở lại với Hy Lạp. Hai đảo này là những vùng đất cuối cùng mà Đế quốc giữ được ở biển Aegea, và tại Lausanne cũng được để lại cho Thổ Nhĩ Kỳ.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Hiệp ước Athens: hòa bình với Hy Lạp và chuyển giao Salonika – Ioannina", "8e94def7"], "d": ["Hiệp ước ký giữa Đế quốc Ottoman và Hy Lạp chính thức công nhận việc Salonika, Ioannina và miền Nam Macedonia, mất trong Chiến tranh Balkan, chuyển sang Hy Lạp, và Ottoman từ bỏ các quyền đối với Crete. Quyền tôn giáo và quyền sở hữu của người Hồi giáo còn ở lại Hy Lạp, quy chế các waqf và việc bổ nhiệm các mufti được quy định chi tiết. Quy chế của các đảo Aegea thì bị bỏ ngỏ và còn là nguồn căng thẳng thường trực giữa hai nước.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Ký hiệp ước liên minh bí mật Ottoman – Đức tại Istanbul", "0472efb3"], "d": ["Ngay khi chiến tranh bùng nổ ở châu Âu, một hiệp ước liên minh bí mật giữa Đế quốc Ottoman và Đức được ký tại dinh thự của Đại tể tướng Said Halim Pasha; văn bản quy định nếu Nga tham chiến chống Đức thì Ottoman cũng đứng về phía Đức. Hiệp ước bị giấu cả nội các, chỉ có bốn người biết. Ba tháng sau, với cuộc đột kích Biển Đen, Đế quốc Ottoman trên thực tế bị lôi vào chiến tranh, và số phận của đế quốc sẽ bị gắn chặt với văn kiện này.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Đơn phương bãi bỏ các ưu đãi cho người nước ngoài (capitulations)", "ec773d18"], "d": ["Vào lúc châu Âu đang bận tâm với chiến tranh, chính phủ Ottoman tuyên bố đơn phương bãi bỏ từ ngày 1 tháng 10 năm 1914 các capitulations, vốn dành cho người nước ngoài các đặc quyền tư pháp, tài chính và hải quan. Việc chấm dứt chế độ đặc quyền bốn thế kỷ này được đón nhận trong nước với niềm phấn khích lớn về độc lập, và Istanbul tổ chức ăn mừng. Mọi nước, kể cả đồng minh Đức, đều phản đối quyết định; các capitulations mãi đến Lausanne năm 1923 mới đi vào lịch sử một cách dứt khoát.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Cuộc đột kích Biển Đen: hạm đội Ottoman pháo kích các cảng Nga", "8ad4ef61"], "d": ["Goeben và Breslau (Yavuz và Midilli), thoát khỏi Đức và gia nhập hải quân Ottoman như thể “đã được mua”, đã ra Biển Đen dưới quyền chỉ huy của Đô đốc Souchon, nã pháo vào các cảng Nga và đánh chìm tàu. Mệnh lệnh do Enver Pasha đưa ra mà giấu nội các đã chấm dứt trên thực tế thế trung lập. Trong vòng một tuần, Nga, Anh và Pháp tuyên chiến, và Đế quốc Ottoman bước vào Thế chiến thứ nhất không thể quay lại.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Lực lượng Anh – Ấn chiếm Faw — mở mặt trận Iraq", "08663813"], "d": ["Sáng ngày hôm sau ngày các nước Entente tuyên chiến với Đế quốc Ottoman, lữ đoàn Anh – Ấn đang chờ ở Bahrain đã đổ bộ lên Faw ở cửa sông Shatt al-Arab. Đơn vị Ottoman nhỏ trong pháo đài Faw đổ nát rút lui dưới hỏa lực của tàu chiến, và trạm đường dây điện báo đi Ấn Độ rơi vào tay người Anh. Mặt trận Iraq được mở ra như vậy.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Tuyên bố Đại thánh chiến: đọc fatwa jihad tại thánh đường Fatih", "2a6174e8"], "d": ["Năm fatwa do Sheikh al-Islam Ürgüplü Hayri Efendi ban ra được đọc tại thánh đường Fatih nhân danh sultan kiêm caliph, kêu gọi toàn thể người Hồi giáo thánh chiến chống các nước phe Hiệp ước (Entente). Nước đi mà Đức đặt nhiều kỳ vọng này nhằm kích động người Hồi giáo ở các thuộc địa Anh và Pháp nổi dậy. Cuộc tổng khởi nghĩa mong đợi đã không xảy ra; ngược lại, hai năm sau, việc Sharif Hussein, emir Mecca, nổi dậy với sự hỗ trợ của Anh đã cho thấy một cách cay đắng giới hạn ảnh hưởng chính trị của chức caliph.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Qurna đầu hàng quân Anh", "621d36b0"], "d": ["Lực lượng của tổng đốc Basra Subhi Bey, rút về Qurna nơi sông Tigris và sông Euphrates hợp lưu sau khi Basra thất thủ, đã đầu hàng vào sáng ngày 9 tháng 12 năm 1914 sau các trận giao tranh ngày 4–8 tháng 12.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Chiến dịch Sarıkamış: thảm họa trên mặt trận Kavkaz", "5cbde7f0"], "d": ["Nhằm lấy lại Kars, Ardahan và Batumi bị mất năm 1878 và kích động người Thổ ở Kavkaz nổi dậy, Enver Pasha đẩy Tập đoàn quân III vào một cuộc cơ động giữa mùa đông qua dãy núi Allahuekber để bao vây lực lượng Nga. Vì quân trang mùa đông thiếu thốn, tiếp tế cạn kiệt và bão tuyết ở nhiệt độ xuống tới âm ba mươi độ, quân đội tan rã trước cả khi giao chiến; hàng chục nghìn binh sĩ chết cóng. Chiến dịch trở thành một trong những thảm họa nặng nề nhất của Ottoman trong chiến tranh và khiến mặt trận phía đông bỏ ngỏ suốt hai năm.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Chiến dịch Kênh đào lần thứ nhất: tấn công Suez qua sa mạc Sinai", "02dd72f5"], "d": ["Cemal Pasha, tư lệnh Tập đoàn quân IV, đã tổ chức cuộc tấn công vượt sa mạc Sinai nhằm giải phóng Ai Cập khỏi sự chiếm đóng của Anh và phong tỏa giao thông trên kênh đào Suez. Các đơn vị Ottoman đến được bờ đông kênh đào và một phần vượt được sang bờ bên kia, nhưng trước ưu thế của Anh và việc cuộc nổi dậy của dân Ai Cập như mong đợi không xảy ra, họ phải rút lui. Chiến dịch không đạt mục tiêu, song đã tạo tác động chiến lược gián tiếp bằng việc buộc Anh phải duy trì lực lượng lớn ở Ai Cập.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Ban hành Luật Di chuyển và Tái định cư (Tehcir)", "2f2bc22c"], "d": ["Sau cuộc nổi dậy ở Van và đà tiến của Nga, chính phủ ban hành một đạo luật tạm thời cho phép các tư lệnh quân đội di chuyển đến vùng khác những cộng đồng dân cư ở hậu phương bị đánh giá là phá hoại an ninh, và sultan phê chuẩn ngày 27 tháng 5 năm 1915. Kết quả việc thi hành là phần lớn dân Armenia ở các tỉnh phía đông và phía nam Anatolia bị áp giải về hướng Syria và Mosul; trong quá trình áp giải, do bệnh tật, đói khát và các cuộc tấn công, đã xảy ra tổn thất nhân mạng cực kỳ lớn. Quyết định này vẫn là vấn đề nặng nề nhất của những năm cuối Ottoman và đến nay vẫn gây tranh cãi nhất.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["Quân Ottoman lấy lại Muş từ tay quân Nga chiếm đóng", "fb1be113"], "d": ["Sáu tháng sau khi Muş bị Nga chiếm đóng lần đầu, Quân đoàn 16 Ottoman đã tiến vào thị trấn trong cuộc phản công Bitlis – Muş.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Muş lại rơi vào tay Nga", "43ad8a03"], "d": ["Trước cuộc phản công của Nga, phân đội Ottoman rời bỏ Muş; trong khoảng 22–25 tháng 8 năm 1916, thị trấn lại bị Nga chiếm đóng và bị giữ đến mùa xuân năm 1917.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Muş được giải phóng dứt điểm khỏi sự chiếm đóng của Nga", "f0e89703"], "d": ["Muş, bị Nga chiếm đóng trong Thế chiến thứ nhất, được lực lượng Ottoman lấy lại dứt điểm ngày 1 tháng 5 năm 1917.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Abdülhamid II qua đời tại cung Beylerbeyi", "c9662582"], "d": ["Abdülhamid II, bị phế truất năm 1909, trước đưa đến Salonika, rồi khi thành phố bị mất trong Chiến tranh Balkan thì được đưa về Istanbul và bị quản thúc tại cung Beylerbeyi, đã qua đời. Trong suốt ba mươi ba năm trị vì, ông cố giữ đất nước khỏi chiến tranh để tranh thủ thời gian, nhưng cũng được nhắc đến cùng nền cai trị chuyên chế. Linh cữu ông được an táng trong lăng Mahmud I trên đại lộ Divanyolu với đám đông đông đảo; cái chết của ông trùng vào một năm chiến tranh khi trật tự do ông dựng nên đã bị xóa bỏ từ lâu.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Hiệp ước Brest-Litovsk: lấy lại Kars, Ardahan và Batumi", "da82636f"], "d": ["Hiệp ước ký giữa nước Nga, vốn rút khỏi chiến tranh sau cuộc cách mạng Bolshevik, và các nước Liên minh Trung tâm đã đóng mặt trận phía đông và trả cho Đế quốc Ottoman Kars, Ardahan và Batumi (Ba tỉnh Elviye-i Selase) đã mất theo Hiệp ước Berlin năm 1878. Đây là lần được thêm lãnh thổ duy nhất sau bốn mươi năm trong lịch sử Ottoman. Tuy nhiên, sau Hiệp định đình chiến Mudros, vùng này lại bị mất, và giải pháp dứt khoát phải đến với Hiệp ước Kars năm 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Các đơn vị Ottoman tiến vào Artvin", "ca7d1778"], "d": ["Các đơn vị Ottoman vượt biên giới năm 1914 ngày 25 tháng 3 đã tiến về Ba tỉnh Elviye-i Selase, nơi Brest-Litovsk trả lại biên giới trước năm 1878, và tiến vào Artvin ngày 28 tháng 3 năm 1918. Artvin, với tư cách một phần sanjak Batumi, đã bị nhượng cho Nga năm 1878; mục từ Artvin của TDV chỉ ghi việc trở lại là “tháng 3 năm 1918”, còn ngày cụ thể do Mustafa Sarı đưa ra.", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ardahan rơi vào tay quân Thổ Nhĩ Kỳ", "7fd9e3db"], "d": ["Trong chiến dịch Ba tỉnh Elviye-i Selase, sau Artvin, quân đội Ottoman chiếm Ardahan ngày 3 tháng 4 năm 1918; Ardahan đã thất thủ năm 1877 trong Chiến tranh Nga – Ottoman 1877–78 và bị nhượng cho Nga năm 1878. Kars sẽ được chiếm một tháng sau, ngày 25 tháng 4.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["Lấy lại Batumi", "d37a1a0d"], "d": ["Quân đội Ottoman, tiến sang phía đông sau khi Nga rút khỏi chiến tranh theo Hiệp ước Brest-Litovsk, bốn mươi năm sau đã lấy lại hải cảng Batumi bị mất năm 1878. Hải cảng ở đầu phía đông Biển Đen này là lối ra biển của dầu mỏ Baku. Thành quả chỉ kéo dài bảy tháng; sau Hiệp định đình chiến Mudros, vùng này phải được bỏ lại.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Ba tỉnh Elviye-i Selase: Kars thuộc quyền cai quản của Ottoman", "02cbf0b3"], "d": ["Tại Brest-Litovsk, hai bên quyết định trả lại ba sanjak mất theo Hiệp ước Berlin năm 1878 — Kars, Ardahan và Batumi; quân đội Ottoman tiến vào Ardahan ngày 3 tháng 4, Batumi ngày 14 tháng 4, Kars ngày 25 tháng 4 năm 1918, và chính quyền được thiết lập trên thực tế. Những vùng đất được gọi là “Elviye-i Selase” này được coi là sự bù đắp cho tổn thất kéo dài từ Chiến tranh Nga – Ottoman 1877–78. Sau đình chiến chúng lại bị mất, và mãi đến Hiệp ước Kars năm 1921 mới dứt khoát gắn vào Thổ Nhĩ Kỳ.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Chiếm Iğdır — tiến quân trong thung lũng sông Aras", "87ebf4d3"], "d": ["Trong khuôn khổ chiến dịch tiến quân bắt đầu từ tháng 2 năm 1918, các đơn vị Thổ Nhĩ Kỳ đánh bại các đơn vị Armenia tại Sardarabad ở phía bắc sông Aras và chiếm Iğdır ngày 20 tháng 5 năm 1918. Iğdır không thuộc Ba tỉnh Elviye-i Selase mà là huyện (kaza) Surmalu của tỉnh Yerevan (guberniya); khoảng 180 năm sau, chính quyền Ottoman đầu tiên được thiết lập trở lại trong vùng.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Mehmed V Reşad qua đời và Mehmed VI Vahideddin lên ngôi", "d302ba07"], "d": ["Mehmed V Reşad, người có chín năm trị vì trải qua các cuộc chiến Tripoli, Balkan và Thế chiến, qua đời vào giai đoạn then chốt nhất của chiến tranh, và người em Vahideddin lên ngôi với hiệu Mehmed VI. Vị sultan mới tìm cách thoát khỏi sự giám hộ của đội ngũ phái Liên hiệp; bốn tháng sau, khi hiệp định đình chiến được ký, ông sẽ phải điều hành việc giải thể đế quốc. Ông là sultan thứ ba mươi sáu và cuối cùng của triều đại Ottoman.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Hạm đội Entente đến trước Istanbul và thành phố bị chiếm đóng trên thực tế", "d10cb14d"], "d": ["Sau Hiệp định đình chiến Mudros, hạm đội đồng minh gồm hơn sáu mươi tàu của Anh, Pháp, Ý và Hy Lạp thả neo trước Dolmabahçe, và Istanbul trên thực tế bị chiếm đóng. Lần đầu tiên sau bốn trăm sáu mươi lăm năm, kinh đô rơi vào sự kiểm soát của binh lính nước ngoài. Câu “Họ đến thế nào thì sẽ đi thế ấy”, tương truyền do Mustafa Kemal Pasha nói ngày hôm đó khi xuống Haydarpaşa và trông thấy cảnh tượng, sẽ trở thành một trong những câu nói biểu tượng của cuộc Đấu tranh Dân tộc.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["Rút lui ở vùng sông Aras: Iğdır bị bỏ trống", "57572ab4"], "d": ["Theo điều khoản của Hiệp định đình chiến Mudros quy định rút về sau biên giới năm 1914, Yakup Şevki Pasha ra chỉ thị ngày 21 tháng 11 yêu cầu rút các đơn vị ở ngoài ranh giới Brest-Litovsk về trước ngày 4 tháng 12; Iğdır và vùng phụ cận được bỏ trống hoàn toàn vào ngày này. Sau đó, Chính quyền Thổ Aras bị người Armenia lật đổ vào cuối tháng 12 năm 1918.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["Người Anh đóng tại Artvin", "e2cb3153"], "d": ["Vì Hiệp định đình chiến Mudros ngày 30 tháng 10 năm 1918 buộc quân đội Ottoman rút về sau biên giới năm 1914, Artvin được bỏ trống và bị người Anh chiếm đóng ngày 17 tháng 12 năm 1918. Theo mục từ Artvin của TDV, cuộc chiếm đóng của Anh kéo dài đến tháng 4 năm 1920.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["Chính quyền Anh tại Batumi sau Mudros", "9dd768fc"], "d": ["Theo Hiệp định đình chiến Mudros ngày 30 tháng 10 năm 1918, Đế quốc Ottoman buộc phải rút khỏi Batumi; thành phố do các đơn vị Anh chiếm giữ ngày 24 tháng 12 năm 1918. Batumi, được làm trung tâm một sanjak độc lập vào tháng 4 năm 1918, từ thời điểm này đến tháng 7 năm 1920 nằm dưới sự kiểm soát của Anh.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Ardahan chuyển sang quyền thống trị của Gruzia", "97cf47f6"], "d": ["Ardahan, được bỏ trống sau Mudros, bị lực lượng Gruzia chiếm đóng ngày 20 tháng 4 năm 1919, vào những ngày Chính phủ Tây Nam Kavkaz bị người Anh giải tán. Quyền thống trị của Gruzia kéo dài đến ngày 23 tháng 2 năm 1921.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Preston giao quyền cai quản Kars cho thống đốc người Armenia", "efa81cb0"], "d": ["Viên chỉ huy Anh Preston, người đã giải tán Chính phủ Tây Nam Kavkaz ngày 12–13 tháng 4 năm 1919, đến ngày 30 tháng 4 năm 1919 bãi bỏ chính phủ hội đồng lâm thời và giao quyền cai quản thành phố cho người Armenia Karganov, được cử làm thống đốc Kars; thời kỳ chính quyền Armenia ở Kars bắt đầu và kéo dài đến chiến thắng của Kâzım Karabekir ngày 30 tháng 10 năm 1920.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Đại hội Erzurum: quyết định kháng chiến dân tộc của các tỉnh phía đông", "41ef0457"], "d": ["Đại hội do Hội Bảo vệ Quyền lợi Đông Anatolia triệu tập, sau khi bị hoãn vì sức ép của Anh, đã khai mạc với năm mươi sáu đại biểu, và Mustafa Kemal Pasha, khi đó đã từ chức khỏi quân đội, được bầu làm chủ tịch. Đại hội tuyên bố rằng trong phạm vi biên giới dân tộc, tổ quốc là một khối thống nhất, chế độ ủy trị và bảo hộ không thể được chấp nhận, và nếu chính phủ tan rã thì dân tộc sẽ tự nắm lấy vận mệnh của mình. Sáu tháng sau, những quyết nghị này sẽ trở thành hạt nhân của văn bản Hiệp ước Dân tộc (Misak-ı Milli).", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Đại hội Sivas: phong trào kháng chiến dân tộc hợp nhất dưới một mái nhà", "0e9ad36b"], "d": ["Đại hội, bắt đầu làm việc ngày 4 tháng 9 năm 1919 tại trường trung học Sivas, đã hợp nhất các hội bảo vệ quyền lợi trên khắp đất nước dưới tên Hội Bảo vệ Quyền lợi Anatolia và Rumelia và bầu ra Ủy ban Đại diện. Đề nghị ủy trị của Mỹ bị bác bỏ sau những cuộc tranh luận dài. Với bản tuyên cáo công bố ngày 11 tháng 9, cuộc Đấu tranh Dân tộc trở thành một phong trào chính trị hợp pháp có một trung tâm duy nhất, và cuộc đấu quyền lực công khai với chính phủ Istanbul bắt đầu.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Nghị định thư Amasya: cuộc hội đàm giữa chính phủ Istanbul và Ủy ban Đại diện", "40e6a6ab"], "d": ["Sau khi Damat Ferid đổ và chính phủ Ali Rıza Pasha được thành lập, Bộ trưởng Hải quân Salih Pasha được cử đến Amasya để hội đàm với Ủy ban Đại diện. Theo các nghị định thư đạt được, chính phủ Istanbul trên thực tế công nhận sự tồn tại của phong trào Anatolia; hai bên chấp nhận việc Hạ viện nhóm họp, bầu cử tự do và bảo vệ biên giới dân tộc. Đây là thắng lợi chính trị chính thức đầu tiên mà cuộc Đấu tranh Dân tộc giành được trước Istanbul.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Nghị viện Ottoman cuối cùng thông qua Hiệp ước Dân tộc (Misak-ı Milli)", "6322865e"], "d": ["Văn bản Lời thề Dân tộc, được 121 nghị viên Hạ viện Ottoman cuối cùng ký, đặt ra các điều kiện: sự toàn vẹn không thể chia cắt của lãnh thổ nằm trong đường ranh Mudros và có đa số dân Thổ Hồi giáo, trưng cầu dân ý ở các tỉnh Ả Rập và Tây Thrace, bãi bỏ capitulations, và độc lập hoàn toàn về chính trị – tài chính. Văn bản được nhất trí thông qua ngày 17 tháng 2 năm 1920 và công bố cho thế giới. Bản tuyên ngôn này vừa là cương lĩnh chính trị của cuộc Đấu tranh Dân tộc vừa là bản đồ các đường biên giới sẽ được bảo vệ tại Lausanne; nó trở thành nguyên nhân trực tiếp khiến các nước Entente chính thức chiếm đóng Istanbul ngày 16 tháng 3.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["Khi người Anh rút đi, Artvin ở lại với Gruzia", "6d086b06"], "d": ["Theo mục từ Artvin của TDV, cuộc chiếm đóng của Anh kéo dài đến tháng 4 năm 1920; khi rút đi, người Anh để thành phố lại cho Gruzia. Artvin nằm trong tay Gruzia đến tối hậu thư ngày 23 tháng 2 năm 1921 của Đại Quốc hội Thổ Nhĩ Kỳ.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Batumi được giao cho chính quyền Gruzia", "6523d095"], "d": ["Việc người Anh chính thức bàn giao Batumi cho người Gruzia diễn ra ngày 7 tháng 7 năm 1920 (mục từ Batumi của TDV chỉ ghi “tháng 7 năm 1920”). Ngày 25 tháng 7, chính phủ Ankara phản đối việc bàn giao, gọi đó là “chiếm đóng”.", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Hiệp ước Gyumri: hiệp ước quốc tế đầu tiên của chính phủ Đại Quốc hội Thổ Nhĩ Kỳ", "9232c690"], "d": ["Khi đạo quân mặt trận phía đông dưới quyền Kâzım Karabekir lấy lại Sarıkamış và Kars, Armenia xin giảng hòa, và theo hiệp ước ký tại Gyumri, nước này chấp nhận không công nhận Hiệp ước Sèvres và từ bỏ yêu sách lãnh thổ ở phía đông. Hiệp ước đầu tiên do chính phủ Ankara ký trở thành văn kiện quốc tế đầu tiên bác bỏ Sèvres trên thực tế và mở đường cho việc Đại Quốc hội Thổ Nhĩ Kỳ được công nhận về pháp lý. Như vậy biên giới phía đông được bảo đảm, cho phép chuyển lực lượng sang mặt trận phía tây.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["Trận İnönü lần thứ nhất: chiến thắng đầu tiên của quân đội chính quy", "4add3719"], "d": ["Quân đội chính quy mới thành lập đã chặn lực lượng Hy Lạp tiến từ hướng Bursa tại các vị trí İnönü và buộc họ phải rút lui. Thành công có quy mô hạn chế về quân sự này lại rất lớn về hệ quả chính trị: chính phủ Ankara được mời dự Hội nghị London, đường đến Hiệp ước Moscow với nước Nga Xô viết được mở, và Luật Tổ chức Căn bản được thông qua. Niềm tin của công luận trong nước vào quân đội chính quy cũng được củng cố nhờ chiến thắng này.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["Trận İnönü lần thứ hai: cuộc tấn công của Hy Lạp bị bẻ gãy lần thứ hai", "a974521c"], "d": ["Không đạt được kết quả tại Hội nghị London, quân đội Hy Lạp mở cuộc tấn công mới từ hướng Bursa và Uşak, nhưng lại bị chặn ở các sườn núi İnönü và buộc phải rút lui. Bức điện Mustafa Kemal Pasha gửi İsmet Pasha, “Ở đó ngài không chỉ đánh bại quân thù mà còn đánh bại cả vận mệnh bất hạnh của dân tộc”, được viết sau chiến thắng này. Trận đánh nâng cao uy tín quốc tế của cuộc Đấu tranh Dân tộc và đẩy nhanh quá trình Ý rút khỏi Anatolia.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Thỏa ước Ankara: hòa bình với Pháp và đóng mặt trận phía nam", "35fc32db"], "d": ["Theo thỏa ước ký với Pháp tại Ankara sau chiến thắng Sakarya, chiến tranh trên mặt trận phía nam chấm dứt; quân Pháp rút khỏi vùng Çukurova và miền Đông Nam, kể cả Adana, Antep, Maraş và Urfa, lui về biên giới Syria. Như vậy một trong các nước Entente trên thực tế đã công nhận chính phủ Ankara, và vết nứt đầu tiên xuất hiện trên mặt trận Sèvres. Vũ khí tiếp quản ở các vùng được bỏ lại và các đơn vị được giải phóng đóng vai trò then chốt trong việc chuẩn bị cho cuộc Đại Tấn công.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Hiệp định đình chiến Mudanya: Istanbul và các Eo biển được chuyển giao không cần giao chiến", "ac0d9baf"], "d": ["Khi sau cuộc Đại Tấn công, quân đội Thổ Nhĩ Kỳ đối mặt với lực lượng Anh ở Çanakkale và İzmit, hội nghị nhóm họp tại Mudanya đã kết thúc bằng hiệp định đình chiến sau mười một ngày mặc cả gay go. Hai bên chấp nhận việc Hy Lạp rút khỏi miền Đông Thrace đến tận sông Maritsa trong mười lăm ngày và giao cho chính quyền Thổ Nhĩ Kỳ, còn Istanbul và các Eo biển sẽ được trao lại theo hiệp ước hòa bình. Như vậy giai đoạn vũ trang của cuộc Đấu tranh Dân tộc khép lại bằng thắng lợi ngoại giao giành được mà không nổ một phát súng, và cánh cửa đến Lausanne được mở ra.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Mehmed VI Vahideddin rời Istanbul và Abdülmecid Efendi được bầu làm caliph", "8ab0e847"], "d": ["Vị sultan cuối cùng Mehmed VI Vahideddin, người có địa vị trở nên gây tranh cãi sau khi chế độ sultan bị bãi bỏ, sáng thứ Sáu ngày 17 tháng 11 năm 1922 đã rời Istanbul trên thiết giáp hạm Malaya của Anh đến Malta. Hai ngày sau, ngày 19 tháng 11, Đại Quốc hội Thổ Nhĩ Kỳ bầu Abdülmecid Efendi làm caliph không có quyền lực chính trị. Quyền cai trị sáu trăm hai mươi ba năm của triều đại Ottoman như vậy trên thực tế chấm dứt; chức caliph còn tồn tại mang tính tượng trưng thêm mười lăm tháng. Vahideddin sang Malta rồi sang Ý, định cư ở Villa Nobel tại San Remo; các đơn xin được một nước Hồi giáo tiếp nhận không có kết quả, và ngày 16 tháng 5 năm 1926 ông qua đời tại đó, sau khi nhắc lại rằng ông chưa bao giờ từ bỏ quyền sultan và quyền caliph của mình.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["Sultan cuối cùng Mehmed VI Vahideddin qua đời tại San Remo", "7149ed0e"], "d": ["Sultan Ottoman cuối cùng Mehmed Vahideddin, người sau khi rời Istanbul đã định cư tại thành phố San Remo của Ý, qua đời ngày 16 tháng 5 năm 1926 mà chưa nhận được tin đại hội caliph (13 tháng 5 năm 1926), nơi ông thông báo rằng mình chưa bao giờ từ bỏ quyền sultan và quyền caliph, đã nhóm họp. Ông lâm vào cảnh túng quẫn nặng nề; ông nợ các tiểu thương San Remo 60.000 lira Ý, và các chủ nợ nghe tin ông mất đã cho tịch biên đồ đạc trong nhà ông.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["Konuralp chinh phục vùng Bolu — Mudurnu, Konurapa và Bolu", "e245cd27"], "d": ["Konuralp, một trong các tướng của Orhan Gazi, hướng đến vùng núi phía đông sông Sakarya và đưa Mudurnu, Konurapa và vùng Bolu vào quyền cai quản của Ottoman; thị trấn ở đồng bằng Düzce được gọi theo tên ông. Ngày chinh phục chính xác không rõ; câu chuyện dựa theo lời thuật của Âşıkpaşazade. Khi đó vùng này là vùng biên đổi chủ giữa dòng Candar và Byzantium; cuộc chinh phục lần đầu đưa Ottoman đến gần bờ tây Biển Đen. Sau trận Ankara, vùng này sẽ lại thuộc về dòng Candar, nhưng đến thời Sultan Chinh phục sẽ được lấy lại dứt khoát.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["Chiếm các thị trấn Byzantium ở phía nam biển Marmara — Mihaliç, Kirmasti, Gölyazı", "9c61b8d4"], "d": ["Sau khi Iznik và Izmit bị chiếm, các thị trấn còn trong tay Byzantium ở phía tây đồng bằng Bursa lần lượt đi vào quyền cai quản của Ottoman. Gölyazı quanh hồ Uluabat, Kirmasti và Mihaliç dọc suối Susurluk đã hoàn tất hành lang nối bờ nam biển Marmara với lãnh thổ Karasi. Các thị trấn này không bị vây hãm lâu mà đầu hàng khi vùng xung quanh bị cắt đứt; sự hiện diện của Byzantium trong vùng như vậy bị dồn vào vịnh Gemlik.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Corinth chuyển về Lãnh địa Despot Morea", "392495eb"], "d": ["Corinth, từ năm 1358 là thái ấp của dòng họ Acciajuoli người Firenze thuộc thân vương quốc Achaea, đã rơi vào tay Theodoros, despot Byzantium ở Morea, năm 1395. Từ đó cho đến khi bị Ottoman chinh phục, thành phố nằm dưới quyền cai quản của lãnh địa despot.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["Sáp nhập công quốc Hacıemiroğulları — Ordu và Ünye", "c064f07f"], "d": ["Công quốc Turkmen do Bayram Bey lập quanh Ordu và được con trai Hacı Emir mở rộng vào những năm 1350 là một nhà nước ven biển nhỏ nhưng chiến lược, trung tâm ở Eskipazar ngày nay: đây là vùng cai trị độc lập duy nhất giữa Samsun và Trabzon. Emir Süleyman đã tỏ lòng quy phục trong chiến dịch Canik của Bayezid Sấm Sét năm 1398, và sau trận Ankara, công quốc lại được tự do. Dưới thời Murad II, trong cùng những năm dòng Taceddin bị xóa bỏ, lãnh thổ công quốc được đưa vào quyền cai quản trực tiếp của Ottoman, và bờ Biển Đen từ Samsun đến Giresun được thống nhất vào một mối.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Chinh phục Corinth", "87a2bc59"], "d": ["Trong chiến dịch Morea của Sultan Mehmed II, Nhà Chinh phục, thành Acrocorinth bị vây ba tháng và cuối cùng đầu hàng theo thỏa ước. Eo đất Corinth, được coi là cửa ngõ của Morea, nhờ đó thuộc về Ottoman.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["Montenegro được đặt dưới quyền cai quản của Ottoman — Cetinje", "7fdb7cc8"], "d": ["Khi triều đại Crnojević cai trị Zeta từ bỏ quyền thống trị năm 1496, vùng núi Montenegro, vốn như sân sau của Shkodra, được đặt dưới quyền cai quản trực tiếp của Ottoman, trước được tổ chức thành một sanjak riêng, sau là một phần sanjak Shkodra. Tu viện Cetinje được để nguyên làm trung tâm tôn giáo của vùng. Vì địa hình khắc nghiệt, bộ máy cai trị ở đây không bao giờ vận hành chặt chẽ như ở đồng bằng; hai trăm năm sau, chế độ vladika ra đời từ chính tu viện này sẽ trở thành hạt nhân của nền độc lập trên thực tế.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["Pháo đài Bayezid chấp nhận quyền thống trị của Ottoman trong Chiến dịch Hai xứ Iraq", "f29e2e17"], "d": ["Khi Đại tể tướng İbrahim Pasha đến vùng quanh Bingöl trong Chiến dịch Hai xứ Iraq, cùng với nhiều bộ lạc người Kurd trong vùng, các pháo đài Van, Toprakkale, Avnik và Bayezid đã đồng ý quy về quyền thống trị của Ottoman. Bayezid đã gia nhập Ottoman trong chiến dịch của Yavuz năm 1514, nhưng khi quân đội trở về, Safavid đã lấy lại vùng này.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Tabriz trở lại tay Safavid — trên đường về của Chiến dịch Hai xứ Iraq", "80b8b761"], "d": ["Trong Chiến dịch Hai xứ Iraq, quân đội đã vào Tabriz, nhưng vì mục tiêu chính là Baghdad nên không để lại đội đồn trú thường trực trong thành phố. Khi quân đội, sau khi qua đông ở Baghdad, quay về phía tây, Shah Tahmasp lại tiến vào Azerbaijan bị bỏ trống và lấy lại Tabriz. Đây là khuôn mẫu lặp đi lặp lại của các cuộc chiến Ottoman – Safavid: Tabriz bị chiếm năm lần, và cả năm lần đều không giữ được; mãi đến năm 1585 thành phố mới có một đội đồn trú Ottoman lâu dài.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["Van và Erciş rơi vào tay Tahmasp (vị thế của Ottoman từ 1534–35 chấm dứt)", "cb93d561"], "d": ["Tại vùng đã đưa Van vào quyền thống trị của Ottoman năm 1534, Ulama Pasha cầm cự trước cuộc vây hãm của Safavid tại pháo đài Van; pháo đài rơi vào tay Safavid, còn lực lượng Safavid vây Erciş đã phải rút lui nhờ viện trợ của Ottoman. Khi Kanunî đến Ahlat (ngày 23 tháng 9 năm 1535), Van đã nằm trong tay Tahmasp. Van thuộc Safavid đến năm 1548.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["Sanjak Bayezid chuyển sang quyền thống trị của Safavid (Van và Erciş đã thuộc Safavid từ 1535)", "806a2cf1"], "d": ["Sanjak Bayezid nằm giữa biên giới Ottoman – Safavid lại rơi vào tay Iran (Kaya 2017 nhắc đến việc này là “cùng với Van và Erciş”; tuy nhiên, theo Karataş 2025 và TDV, Van và Erciş đã trở về Safavid ngày 22 tháng 9 năm 1535 — xem mục trước); trong lần đổi chủ này, một số nơi của sanjak bị tàn phá. Cho đến quý cuối thế kỷ 16, sanjak đổi chủ nhiều lần giữa hai nước.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["Sanjak Bayezid trở lại thuộc Ottoman trong Chiến dịch Nakhchivan", "cf0171fa"], "d": ["Trong chiến dịch Iran lần thứ ba (Nakhchivan) của Kanunî, sanjak Bayezid lại được đưa vào quyền cai quản của Ottoman. Trong chiến dịch năm 1554, Bayezid trở thành căn cứ quan trọng của quân đội; sanjak đi vào chủ quyền Ottoman một cách dứt khoát năm 1578.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["Mất Yerevan vào tay Shah Abbas", "34413cf2"], "d": ["Khi mặt trận phía đông bị bỏ ngỏ trong những năm các cuộc nổi loạn Celali làm tê liệt Anatolia, Shah Abbas, người đã tổ chức lại quân đội theo kiểu châu Âu, chuyển sang tấn công. Pháo đài Yerevan do Ferhad Pasha cho xây năm 1583 đã đầu hàng sau bảy tháng bị vây. Mắt xích đầu tiên của tuyến Kavkaz giành được theo Hiệp ước Ferhad Pasha đã đứt, và trong ba năm tiếp theo toàn bộ Nam Kavkaz sẽ bị mất.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["Mất Tbilisi và Ganja", "3fb51753"], "d": ["Sau khi Yerevan thất thủ, quân đội Safavid tiến dọc thung lũng sông Kura; Ganja, trung tâm của Karabakh, và Tbilisi, thủ phủ Gruzia, lần lượt bị mất. Cùng lúc đó Đế quốc Ottoman đang tiến hành cuộc chiến dài mười ba năm trên mặt trận chống Áo và đối phó với quân Celali ở Anatolia; không có lực lượng nào để điều sang phía đông. Như vậy hệ thống các tỉnh Kavkaz rộng lớn được thiết lập bởi Hiệp ước Ferhad Pasha năm 1590 trên thực tế chấm dứt.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["Mất Shirvan — Shamakhi, Baku và Derbent", "81beab11"], "d": ["Tỉnh Shirvan bên bờ biển Caspi, giành được qua các chiến dịch 1578–1585 của Özdemiroğlu Osman Pasha, là nguồn chính của thương mại tơ lụa và đem lại nguồn thu đáng kể cho tài chính Ottoman. Chiến dịch hướng lên phía bắc của Shah Abbas lần lượt chiếm Shamakhi, Baku và Derbent, xóa bỏ tỉnh này. Tổn thất không chỉ là lãnh thổ: con đường tơ lụa Iran chảy qua đất Ottoman sang châu Âu cũng thoát khỏi sự kiểm soát, và nhà nước Safavid bắt đầu tiêu thụ tơ lụa qua Ấn Độ Dương.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["Mất Taiz", "65f20d53"], "d": ["Năm Hijri 1038 (1629), cùng với quyền thống trị ở Yemen được để lại cho chính quyền Qasimi ở Sanaa, người Ottoman cũng bỏ Taiz — bước lớn đầu tiên của tiến trình các imam Zaydi giành lại nội địa Yemen.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["Mất Yemen — quyền thống trị của các imam Qasimi", "49e83e3c"], "d": ["Yemen là một tỉnh của Ottoman từ năm 1538; tuy nhiên sự kháng cự của các imam Zaydi chưa bao giờ ngừng. Cuộc nổi dậy do Imam al-Qasim phát động lan ra toàn xứ dưới thời con trai ông là al-Mu'ayyad Muhammad, và các đội đồn trú Ottoman lần lượt bị vây. Trong những năm Murad IV tập trung vào Baghdad và Yerevan, không thể gửi viện binh; Taiz đã bị mất năm 1629, còn Mocha được di tản ngày 22 tháng 10 năm 1635 trong giai đoạn cuối của cùng cuộc sụp đổ đó. Năm 1635, các đơn vị cuối cùng ở Sanaa và Zabid cũng rút khỏi Yemen. Như vậy bờ đông Biển Đỏ nằm ngoài đế quốc suốt hai trăm ba mươi bảy năm, mãi đến năm 1872 mới được thu hồi. Theo Bách khoa toàn thư Hồi giáo TDV, Lahej (al-Hawta) nằm trong tay người Ottoman đến năm 1635; từ đó các imam Zaydi có ảnh hưởng.", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["Di tản Mocha", "c6b3061a"], "d": ["Mustafa Bey ngày 10 tháng Jumada I năm 1045 (22 tháng 10 năm 1635) đã rút khỏi Mocha cùng lực lượng và vũ khí còn lại; sau đó Hasan ibn al-Qasim, con trai Imam al-Qasim, bổ nhiệm người của mình ở Zabid và Mocha, thiết lập sự kiểm soát của phái Qasimi cả trên bờ biển Tihamah.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["Mất al-Ahsa vào tay Tiểu vương quốc Bani Khalid", "a9b6131a"], "d": ["Al-Ahsa là tỉnh được lập năm 1550 nhằm đóng bờ tây vịnh Basra đối với Bồ Đào Nha; tuy nhiên nó ở rất xa Istanbul, tại cuối một con đường sa mạc duy nhất. Trong những năm cuộc vây hãm Crete làm cạn kiệt nguồn lực, bộ lạc Bani Khalid trong vùng, dưới sự lãnh đạo của Barrak ibn Ghurayr, đã đuổi đội đồn trú Ottoman và lập tiểu vương quốc riêng. Bờ tây vùng vịnh thuộc các tiểu vương quốc bộ lạc suốt một thế kỷ rưỡi; năm 1795 chuyển cho dòng Saud, năm 1871 lại về Ottoman.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["Mất Preveza và Vonitsa vào tay Venice — bờ biển Epirus mở toang", "1201204c"], "d": ["Venice, tham gia Liên minh Thần thánh, trước khi mở chiến dịch Morea đã chiếm hai pháo đài trấn giữ cửa vịnh Ambracia: Preveza và Vonitsa ở bờ đối diện. Cùng mùa hè đó, Lefkada (Ayamavra) cũng thất thủ. Ba vị trí này cho phép hạm đội an toàn thâm nhập từ biển Ionia vào nội địa Hy Lạp và trở thành căn cứ cho chiến dịch Morea mở màn năm sau. Preveza và Vonitsa cũng được để lại cho Venice tại Passarowitz; mãi đến năm 1798 mới trở lại quyền cai quản của Ottoman.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["Mất Szolnok — phòng tuyến sông Tisza tan rã", "51c2c8ef"], "d": ["Sau khi Nové Zámky (Uyvar) thất thủ vào tháng 8, quân đội Habsburg quay xuống phía nam và chiếm đầu cầu Szolnok trên sông Tisza. Thành phố là lối đi an toàn duy nhất giữa Buda và Transylvania; mất nó nghĩa là các pháo đài Ottoman ở nửa phía đông Hungary bị cắt rời khỏi nhau. Việc đường tiếp tế đã bị cắt đóng vai trò quyết định trong cuộc vây hãm Buda năm sau.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["Mất Methoni vào tay Venice", "114c9cc0"], "d": ["Methoni ở mỏm tây nam bán đảo Morea là hải cảng mà Venice đã mất ba thế kỷ trước và từng gọi là “một trong hai con mắt của nhà nước”. Pháo đài, bị vây sau khi Koroni thất thủ, bị bắn phá cùng lúc từ đất liền và từ biển rồi được tiếp nhận. Chiến dịch Morea của Morosini như vậy chiếm toàn bộ bờ tây bán đảo và mở đường vào nội địa.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["Mất Pécs", "99d54cf4"], "d": ["Sau khi Buda thất thủ vào tháng 9, lực lượng Habsburg tiến xuống phía nam ở phía tây sông Danube và chiếm Pécs, vốn thuộc Ottoman từ thời Kanunî. Thành phố, nổi danh với thánh đường Gazi Kasım Pasha, là một trong những trung tâm sanjak phát triển nhất của tỉnh Buda. Mất nó đồng nghĩa mở con đường xuống đồng bằng Mohács; năm sau, thảm bại Mohács lần thứ hai sẽ diễn ra ngay tại đó.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["Mất Szeged", "9fbee1b2"], "d": ["Szeged, tại nơi hợp lưu của sông Tisza và sông Mureș, là cửa ngõ phía nam của đồng bằng Hungary và trấn giữ con đường đến tỉnh Temeşvar. Pháo đài, bị vây sau khi Buda và Pécs thất thủ trong cùng mùa thu, đã đầu hàng sau một thời gian ngắn. Việc mất ba pháo đài trong một mùa là dấu hiệu cho thấy cơ cấu hành chính Ottoman ở Hungary, thiết lập từ năm 1541, bắt đầu sụp đổ. Bản đồ cũng tính cùng ngày này Zenta bên sông Tisza đã chuyển từ Ottoman sang phía Habsburg (ngày đầu hàng riêng của Zenta không đọc được trong nguồn, ngày được lấy từ Szeged; TDV zenta: từ tháng 10 năm 1686 giao tranh bắt đầu giữa Ottoman và liên quân do Habsburg dẫn đầu — xấp xỉ có công bố).", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["Mất Patras (Balyabadra) — cửa ngõ phía bắc của Morea", "b9cff63c"], "d": ["Patras ở cửa vịnh Corinth là hải cảng kiểm soát lối đi giữa Morea và Rumelia. Sau khi quân Venice chiếm thành phố, các pháo đài ở hai bờ vịnh cũng lần lượt thất thủ, và bán đảo bị cô lập hoàn toàn về đường bộ. Kết thúc chiến dịch này, toàn bộ Morea thuộc về Venice; vùng này sẽ được cai trị với tên “Regno di Morea” đến năm 1715.", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Corinth được để lại cho Venice", "9a25b6b9"], "d": ["Sau khi Patras thất thủ, Corinth được giao cho người Venice theo thỏa ước và dân Hồi giáo rời thành phố. Tháng 8 năm 1687, quân đội của Morosini đang tập trung tại Corinth cho chiến dịch đánh Athens.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["Mất Eger", "983391aa"], "d": ["Eger được chiếm năm 1596 trong chiến dịch do chính Mehmed III tham gia và trở thành trung tâm một tỉnh mang tên nó. Pháo đài lớn cuối cùng này của Ottoman ở miền Bắc Hungary đã cầm cự một năm trong cảnh bị vây hoàn toàn sau thảm bại Mohács lần thứ hai, và đầu hàng vì đói. Mất nó, cánh phía bắc của Đế quốc Ottoman ở Hungary bị xóa bỏ hoàn toàn.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["Mất Székesfehérvár — thành phố đăng quang của các vua Hungary", "c6147255"], "d": ["Thành phố nơi các vua Hungary suốt nhiều thế kỷ đăng quang và được mai táng đã bị Kanunî chiếm năm 1543 và trở thành một trong những trung tâm sanjak quan trọng nhất của tỉnh Buda. Khoảng hai năm sau khi Buda thất thủ, pháo đài bị cắt đứt hoàn toàn khỏi vùng xung quanh đã đầu hàng. Với tổn thất này, sự hiện diện của Ottoman ở phía tây sông Danube bị dồn vào vùng quanh Syrmia và Osijek.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["Mất Szigetvár", "834910a7"], "d": ["Szigetvár là pháo đài nơi Sultan Süleyman Lập pháp qua đời năm 1566, trong chiến dịch thứ mười ba và cuối cùng của ông, khi cuộc vây hãm đang diễn ra; vì thế nó có vị trí biểu tượng trong ký ức Ottoman. Một trăm hai mươi ba năm sau, khi mọi pháo đài xung quanh đã thất thủ, pháo đài được đầm lầy che chở này cũng đầu hàng. Lăng chôn nội tạng của Kanunî và thị trấn quanh nó bị phá hủy sau khi chuyển sang quyền cai quản của Habsburg. Điểm định cư khác trên bản đồ chuyển từ Ottoman sang Habsburg cùng ngày: Barcs — đi theo chuỗi trung tâm chủ quản của Szigetvár (Bánlaky 0017/1449; xấp xỉ có công bố).", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["Mất Oradea (Varad)", "6cce360d"], "d": ["Oradea là pháo đài then chốt mở vào Transylvania, được Köprülü Mehmed Pasha chiếm năm 1660 và lập làm trung tâm một tỉnh mang tên nó. Bị cô lập hoàn toàn sau thảm bại Slankamen, pháo đài đã đầu hàng vì đói sau cuộc phong tỏa kéo dài gần hai năm. Mất nó, ảnh hưởng của Ottoman đối với Transylvania trên thực tế chấm dứt, và quyền thống trị của Habsburg được thiết lập ở phía đông sông Tisza.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["Mất Ineu (Yanova) — đường vào Transylvania bị đóng", "4b5e30d8"], "d": ["Ineu, được chiếm năm 1658, là pháo đài giữ mối liên lạc giữa Oradea và Temeşvar. Khi bị cắt đứt vùng xung quanh ngay sau khi Oradea thất thủ, nó cũng bị mất. Như vậy tỉnh Temeşvar bị cô lập hoàn toàn từ phía bắc và tồn tại như vùng đất Hungary duy nhất còn trong tay Ottoman cho đến Karlowitz.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["Thiết lập chế độ vladika ở Montenegro — Cetinje tách rời trên thực tế", "a924b778"], "d": ["Trong những năm cuộc chiến với Liên minh Thần thánh làm lỏng lẻo sự kiểm soát của Ottoman ở Balkan, chức tổng giám mục đứng đầu tu viện Cetinje trở thành một chức vụ cha truyền con nối trong dòng họ Petrović, và vùng này trên thực tế có được một chính quyền riêng. Nhờ núi non hiểm trở khó tiếp cận, chế độ vladika này suốt hai thế kỷ tồn tại ở vị thế không hoàn toàn độc lập cũng không hoàn toàn lệ thuộc; về pháp lý, nền độc lập của nó chỉ được công nhận theo Hiệp ước Berlin năm 1878.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Lấy lại Corinth", "26f53e3a"], "d": ["Điểm dừng lớn đầu tiên trong chiến dịch Morea của Damad Ali Pasha là Corinth; tháng 6 năm 1715, người Ottoman lấy lại thành phố từ tay người Venice và từ đây tiến vào phần còn lại của bán đảo.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Cuộc tấn công của Nadir: mất Tabriz, Nakhchivan, Hamadan, Kermanshah, Maragheh và Qasr-e Shirin", "d95efd59"], "d": ["Các thành phố miền Tây Iran chiếm trong các năm 1723–1727 nhờ lợi dụng sự sụp đổ của nhà nước Safavid đã lần lượt bị mất trước cuộc tấn công của Nadir Khan, người nắm quyền lực thực tế ở Iran. Ở Azerbaijan, Ardabil và Khalkhal cũng rơi vào tay Nadir. Việc mất Hamadan, Kermanshah và Qasr-e Shirin gây tiếng vang nặng nề ở Istanbul; việc quân đội không xuất chinh mà chờ đợi ở Üsküdar, cùng nỗ lực che đậy tổn thất, là một trong những nguyên nhân trực tiếp của cuộc nổi loạn Patrona Halil bùng nổ sáu tuần sau. Bản đồ cũng tính Kotur, nơi đi theo chuỗi của Khoy, chuyển từ Ottoman sang Safavid vào ngày này (Uluerler 2015, Turkish Studies 10/5, tr. 6; nguồn không có ngày riêng cho Kotur — xấp xỉ có công bố).", "412bd324"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["Thảm bại Baghavard (Arpaçay) — mất Kavkaz vào tay Nadir Khan", "4262f54c"], "d": ["Các tỉnh Kavkaz chiếm trong các năm 1723–1725 nhờ lợi dụng sự sụp đổ của nhà nước Safavid chỉ giữ được mười năm. Nadir Khan, người nắm quyền lực thực tế ở Iran, đã đánh bại nặng quân đội Ottoman tại Baghavard gần Yerevan; tổng chỉ huy Abdullah Köprülü Pasha tử trận. Sau thảm bại, Yerevan, Tbilisi, Ganja và Shirvan bị bỏ trong vài tháng. Biên giới phía đông trở về đường Kasr-ı Şirin năm 1639, sẽ được tái xác nhận năm 1746.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["Mất Bender vào tay Nga", "0daca453"], "d": ["Sau thảm bại trên đồng bằng Kagul, quân đội Ottoman rút về phía nam sông Danube, và các pháo đài giữa Moldavia và Ochakov bị bỏ trơ trọi. Bender, trấn giữ điểm vượt sông Dniester, bị đánh chiếm bằng tổng công kích sau hai tháng vây hãm; thành phố bị cướp phá. Mất pháo đài này làm đứt mắt xích giữa của phòng tuyến bắc Biển Đen, tiếp theo Akkerman và Kiliya cũng thất thủ. Bender sẽ được trả lại theo Küçük Kaynarca, nhưng lại bị mất lần nữa năm 1806.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["Tiểu vương quốc của dòng họ Sabah ở Kuwait đặt dưới sự bảo hộ của Ottoman", "3584dba0"], "d": ["Theo mục từ Kuwait của TDV, bến cảng này do bộ lạc Utub từ Najd đến lập ra vào đầu thế kỷ 18, còn dòng họ Sabah nắm quyền cai quản vào khoảng cuối thế kỷ. Cũng trong những năm Al-Ahsa rơi vào tay nhà Saud, trước sức ép của phái Wahhabi, tiểu vương quốc không còn lựa chọn nào khác ngoài dựa vào Basra nên đã đặt mình dưới sự bảo hộ của Ottoman. Mối liên hệ này được chính thức hóa năm 1871 qua việc Midhat Pasha tổ chức lại Basra, và Kuwait được tính là một trong ba kazâ (huyện) của sancak Basra; yêu sách lãnh thổ về sau của Iraq cũng dựa trên ghi chép này.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["Mất Mecca vào tay người Wahhabi", "2da23acd"], "d": ["Phong trào Wahhabi ra đời ở Najd, dưới thời Saud ibn Abd al-Aziz, hướng sang Hejaz; sau Taif và Medina, Mecca cũng bị tiếp quản lần thứ hai — Sharif Ghalib, emir Mecca, giao thành phố cho người Wahhabi với điều kiện được tiếp tục giữ chức emir. Các lăng mộ bị phá và đường của các đoàn hành hương từ Damascus và Cairo bị cắt; khoản surre mà sultan hằng năm gửi đến Hai Thánh địa cũng bị gián đoạn trong những năm này — ngoại lệ duy nhất của khoản cấp phát liên tục đến năm 1915 này là thời kỳ thống trị của người Wahhabi. Vì tư cách người bảo hộ Hai Thánh địa là một trong những nền tảng chính của tính chính danh của sultan, tổn thất này, vượt ra ngoài việc mất đất, là một đòn chính trị nặng nề; việc thu hồi sẽ mất bảy năm và chỉ thực hiện được nhờ quân đội của Muhammad Ali Pasha người Kavala.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Cộng hòa Dubrovnik cáo chung — quân Pháp chiếm đóng", "f8e27bf1"], "d": ["Người Pháp, sau khi đặt chân lên bờ biển Dalmatia theo Hiệp ước Campo Formio (1797), đã chiếm Dubrovnik ngày 27 tháng 5 năm 1806 và xóa bỏ nước cộng hòa thương nhân nhỏ bé này. Như vậy chấm dứt quy chế chư hầu kéo dài ba thế kỷ rưỡi của Dubrovnik, quốc gia đã giữ được quyền tự trị và đặc quyền thương mại nhờ nộp cống cho Ottoman từ năm 1458; thành phố cùng đảo Mljet của nước cộng hòa chuyển sang chịu sự cai trị trực tiếp của Pháp trên bản đồ.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Mất Sukhum vào tay Nga — bờ đông Biển Đen bị khai mở", "adc96bd4"], "d": ["Trong chiến tranh Ottoman–Nga 1806-1812, hạm đội Nga hướng về bờ đông Biển Đen và chiếm Sukhumkale, chỗ dựa của quyền thống trị Ottoman tại Abkhazia. Pháo đài này là trung tâm liên lạc với các bộ lạc Kavkaz và của việc buôn bán ven biển. Mất nó, lần đầu tiên Nga đứng chân lâu dài trên bờ đông Biển Đen; ảnh hưởng của Ottoman ở Kavkaz bị dồn lại quanh Anapa và Poti.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Parga được giao cho chính quyền Ottoman", "66e0cc5d"], "d": ["Parga nằm trong tay Venice từ năm 1401 và chưa bao giờ thuộc quyền cai trị của Ottoman; sau khi Venice sụp đổ, nơi này lần lượt chuyển sang Pháp rồi Anh. Mục từ Ali Pasha xứ Tepelenë của TDV tóm tắt tình hình như sau: thành phố đầu hàng người Anh và mãi đến năm 1819 mới được giao cho Ali Pasha cai quản. Cuộc chuyển giao dẫn đến việc phần lớn dân chúng di cư sang quần đảo Ionia. Như vậy nơi cuối cùng trong bộ ba Preveza–Parga–Vonitsa, vốn được để lại cho Venice theo hòa ước Passarowitz, cũng gia nhập đế quốc; Parga sẽ thuộc Ottoman thêm chín mươi tư năm.", "555a1119"]},
"OLAYLAR_EK6:1821-01-01:0":{"b": ["Argos rơi vào tay quân nổi dậy Hy Lạp", "be66a696"], "d": ["Trong những tháng đầu của cuộc nổi dậy ở Morea, Argos và vùng phụ cận thoát khỏi sự cai trị của Ottoman và rơi vào tay quân nổi dậy Hy Lạp; tháng 5 năm 1821, thành phố trở thành nơi diễn ra cuộc phản công của lực lượng Ottoman.", "c3ea2041"]},
"OLAYLAR_EK6:1821-05-05:0":{"b": ["Ahmed Kihaya chiếm Argos, thành phố bị cướp phá và đốt cháy", "d6d3ac7b"], "d": ["Lực lượng của Ahmed Kihaya đánh bại người Hy Lạp tại Argos, rồi cướp phá và đốt cháy thành phố; trong một thời gian ngắn, thị trấn trở lại dưới sự kiểm soát của Ottoman.", "316a51a8"]},
"OLAYLAR_EK6:1821-05-15:0":{"b": ["Tại Argos, Ahmed Kihaya hợp quân với người Hồi giáo Tripolitsa rồi tiến về Tripolitsa", "9d679fd5"], "d": ["Tại Argos, Ahmed Kihaya hợp quân với người Hồi giáo Tripolitsa rồi tiến về phía Tripolitsa; Argos lại rơi vào quyền kiểm soát của quân nổi dậy Hy Lạp.", "596502da"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Corinth rơi vào tay quân nổi dậy Hy Lạp", "892dcdc6"], "d": ["Trong chiến tranh giành độc lập Hy Lạp, Acrocorinth rơi vào tay quân nổi dậy và chỉ huy pháo đài Kâmil Bey bị bắt làm tù binh.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-07-24:0":{"b": ["Mahmud Pasha xứ Drama đặt đại bản doanh tại Argos", "c79abbfb"], "d": ["Quân đội của Mahmud Pasha xứ Drama tiến vào đồng bằng Argos và vị pasha đặt đại bản doanh tại thị trấn Argos; thị trấn lại thuộc quyền kiểm soát của Ottoman.", "d931b635"]},
"OLAYLAR_EK6:1822-08-06:0":{"b": ["Mahmud Pasha xứ Drama bắt đầu rút khỏi Argos", "5e5afb74"], "d": ["Buộc phải rút lui khi chiếm đóng Argos chưa đầy hai tuần, Mahmud Pasha xứ Drama bắt đầu rút sư đoàn đầu tiên của quân đội mình về hướng Corinth; Argos lại rơi vào tay quân nổi dậy Hy Lạp.", "9c49ab0c"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Mất Nafplio (Nauplion) vào tay quân nổi dậy", "1a67fa50"], "d": ["Nafplio, hải cảng có hệ thống phòng thủ mạnh nhất Morea, đã đầu hàng vì đói sau hơn một năm bị phong tỏa. Từ đầu cuộc nổi dậy, pháo đài này là chỗ dựa lớn cuối cùng của quyền kiểm soát Ottoman trên bán đảo; mất nó, toàn bộ Morea rơi vào tay quân nổi dậy. Không lâu sau, thành phố trở thành thủ đô đầu tiên của nhà nước Hy Lạp mới.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-30:0":{"b": ["Lepanto chuyển sang quyền cai quản của Hy Lạp", "c9d19d4b"], "d": ["Lepanto, trên bờ bắc vịnh Corinth, vẫn nằm trong tay Ottoman cho đến cuộc nổi dậy của người Hy Lạp, đã bị mất vào tháng 4 năm 1829 và chuyển sang quyền cai quản của Hy Lạp; tên thị trấn được đổi thành Naupaktos theo thời cổ đại. Dân Hồi giáo và Do Thái của thành phố biến mất hoàn toàn, và nơi đây trở thành một thị trấn nhỏ.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Pháp chiếm Algiers — Quân khu tự trị (ocak) ba trăm năm cáo chung", "0be8f568"], "d": ["Lấy cớ vụ chiếc quạt phát sinh từ một tranh chấp nợ nần, Pháp phong tỏa bờ biển Algeria suốt ba năm, rồi đổ quân lên Sidi Fredj. Kết thúc chiến dịch kéo dài ba tuần, Dey Hüseyin đầu hàng và Ocak Algiers của Ottoman, tồn tại từ năm 1516, chấm dứt. Cuộc chiếm đóng không chỉ dừng ở thủ phủ; Tlemcen, Cherchell và Médéa trong nội địa cũng bị mất ngay trong mùa hè ấy. Phải thêm hai mươi tư năm nữa toàn bộ bờ biển mới rơi vào quyền kiểm soát của Pháp.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Negroponte được giao cho Hy Lạp — cùng với cả hòn đảo (Karystos, Oreoi)", "7b524aa4"], "d": ["Negroponte, nơi diễn ra giao tranh dữ dội suốt chiến tranh giành độc lập Hy Lạp nhưng vẫn trong tay Ottoman, đã được giao cho người Hy Lạp năm 1831 sau khi hiệp ước hòa bình có hiệu lực. Dân Hồi giáo của thành phố, vốn là một căn cứ hải quân quan trọng từ năm 1470, bán hết tài sản với giá rất rẻ rồi di cư tập thể sang lãnh thổ Ottoman; thành phố bỏ trống trong thời gian dài, và năm 1842 nhà du hành người Đức Fallmerayer gọi nó là một thành phố ma.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Pháp chiếm Oran", "a8415d66"], "d": ["Oran, được Tây Ban Nha chuyển giao không qua chiến tranh năm 1792, là hải cảng lớn nhất ở miền tây Algeria. Sáu tháng sau khi thủ phủ thất thủ, quân Pháp tiến vào thành phố. Chiến dịch phía tây khởi đầu từ đây chẳng bao lâu sau đã vấp phải cuộc kháng chiến kéo dài mười lăm năm của Emir Abd al-Qadir.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Chiếm đóng Annaba (Bône)", "21f37fb1"], "d": ["Annaba, hải cảng ở miền đông Algeria gần biên giới Tunisia, bị quân Pháp chiếm và biến thành căn cứ cho cuộc tiến quân vào Constantine. Thành phố đồng thời là hải cảng châu Phi gần đảo Sardinia nhất ở phía đối diện.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["Athens được giao cho nhà nước Hy Lạp mới (ngày quân Bavaria tiếp nhận Acropolis)", "deee4d37"], "d": ["Athens, thuộc Ottoman từ năm 1456, đã đổi chủ nhiều lần trong chiến tranh giành độc lập Hy Lạp, và đội đồn trú tại Acropolis lại trở về dưới quyền kiểm soát của Ottoman năm 1827. Vì nằm ở phía bắc đường biên giới vạch ra theo Nghị định thư London, thành phố được giao cho vương quốc mới và đội đồn trú rút khỏi Acropolis. Ngày dùng trong atlas là ngày quân Bavaria tiếp nhận Acropolis; đội đồn trú Ottoman thực sự rời đi vài ngày sau đó (St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, chương 13; Finlay, Journals and Letters, tập I, tr. 67). Năm sau, Athens được tuyên bố là thủ đô của Hy Lạp thay cho Nafplio.", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Chiếm đóng Béjaïa (Bougie)", "a8927e00"], "d": ["Cảng Béjaïa, nơi dãy núi Kabylie mở ra biển, là mắt xích độc lập cuối cùng của tuyến ven biển giữa Algiers và Annaba. Cảng bị chiếm với sự yểm trợ của pháo hải quân; tuy nhiên vùng núi nội địa phía sau còn ba mươi năm nữa mới rơi vào quyền kiểm soát của Pháp. Những cuộc chiếm đóng dọc bờ biển này tạo nên quá trình Algeria thuộc Ottoman tan dần từng năm trên bản đồ.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Chiếm đóng Sétif", "2073731a"], "d": ["Một năm sau khi Constantine thất thủ, quân Pháp tiến lên cao nguyên, chiếm Sétif, thành phố La Mã cổ, và lập tại đây một đồn trú thường trực. Sétif là giao điểm của các tuyến đường lữ hành giữa bờ biển và Sahara; việc chiếm đóng nó cho thấy Pháp đã bắt đầu kiểm soát không chỉ các hải cảng mà cả mạng lưới thương mại nội địa.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Chiếm đóng Biskra — mất cửa ngõ Sahara", "d895cad0"], "d": ["Biskra, ở chân phía nam dãy Atlas, là cửa ngõ mở ra Sahara và là trung tâm các ốc đảo chà là. Khi nơi này bị chiếm vào những năm cuộc kháng chiến của Emir Abd al-Qadir bắt đầu suy sụp, quyền kiểm soát của Pháp lần đầu tiên vươn tới rìa phía bắc sa mạc. Từ đây về sau là một chiến dịch trên sa mạc tiến từng ốc đảo một.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Chiếm đóng Touggourt — mất toàn bộ Algeria", "33c056e2"], "d": ["Với việc chiếm Touggourt, thành phố ốc đảo ở phía bắc Sahara, cuộc chiếm đóng khởi đầu năm 1830 đã hoàn tất tại nửa phía bắc của Algeria ngày nay. Trong những năm này, Đế quốc Ottoman đang chiến đấu cùng phe với Pháp trong Chiến tranh Crimea; tuy không bao giờ chính thức từ bỏ yêu sách pháp lý đối với Algeria, trên thực tế họ không thể làm được một bước nào. Vùng đất duy nhất còn lại ở Bắc Phi là Tripolitania.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["El Obeid thất thủ — Kordofan rơi vào tay lực lượng Mahdi", "58299f62"], "d": ["Phong trào do Muhammad Ahmad, người tự xưng là Mahdi, khởi xướng đã lan nhanh chống lại sự cai trị của Ai Cập tại Sudan. El Obeid, trung tâm của Kordofan, thất thủ sau bốn tháng bị vây và trở thành thủ phủ của cuộc nổi dậy; ngân khố và kho vũ khí trong thành giúp phong trào tổ chức thành quân đội. Về pháp lý, Sudan vẫn là đất của Khedive Ai Cập thuộc Ottoman, nên sự mất mát này bị trừ khỏi phần thân của đế quốc trên bản đồ.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Khartoum thất thủ — mất toàn bộ Sudan", "d4b98464"], "d": ["Sau cuộc vây hãm kéo dài mười tháng, lực lượng Mahdi tiến vào Khartoum, nơi hợp lưu của sông Nin Xanh và sông Nin Trắng; tổng đốc thành phố Gordon bị giết, và cánh quân Anh được phái đến cứu viện đã chậm hai ngày. Từ đó, toàn bộ Sudan, gồm cả Sennar, Dongola và Kordofan, nằm dưới quyền cai trị của Nhà nước Mahdi trong mười bốn năm. Phải đến năm 1899, vùng này mới chuyển sang chế độ đồng quản Anh–Ai Cập, khi mối liên hệ với Ottoman đã bị cắt đứt hoàn toàn.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Ý chiếm Massawa — mất bờ tây Biển Đỏ", "c333b95b"], "d": ["Cảng Massawa, trung tâm của tỉnh Habeş (Abyssinia), bị Ý chiếm đóng nhân lúc tình hình hỗn loạn khi cuộc nổi dậy Mahdi tràn khắp Sudan; đây là hạt nhân của xứ Eritrea thuộc Ý. Suakin ở phía bắc và quần đảo Dahlak ngoài khơi cũng bị mất trong cùng tiến trình đó. Như vậy quyền thống trị của Ottoman trên bờ tây Biển Đỏ, kéo dài từ thời Selim I \"Nghiêm Khắc\", đã chấm dứt, và giờ đây biển này trở thành vùng nước mà cả hai bờ đều thuộc ngoại bang.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Ý chiếm Rhodes", "e08662c5"], "d": ["Muốn buộc Đế quốc Ottoman ngồi vào bàn đàm phán trong chiến tranh Tripolitania, Ý đưa chiến tranh ra Địa Trung Hải và đổ quân lên Rhodes. Hòn đảo bị tiếp quản chỉ trong vài ngày. Rhodes, được Suleiman Nhà Lập pháp chiếm sau một cuộc vây hãm dài năm 1522 và giữ suốt ba trăm chín mươi năm, từ đó không còn là căn cứ đảo lớn nhất của đế quốc ở Đông Địa Trung Hải; tuy Hiệp ước Ouchy coi đây là chiếm đóng tạm thời, nó không bao giờ được lấy lại.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Ý chiếm quần đảo Dodecanese", "200aacf2"], "d": ["Trong vòng vài tuần sau khi chiếm Rhodes, hạm đội Ý chiếm luôn các đảo xung quanh; về sau quần đảo này được gọi là 'Dodecanese'. Phần lớn các đảo chỉ cách bờ biển Anatolia vài hải lý và khống chế cửa ngõ đông nam của biển Aegea. Trong Hiệp ước Ouchy, cuộc chiếm đóng được coi là tạm thời để đổi lấy việc từ bỏ Tripolitania, nhưng Ý không bao giờ rút khỏi các đảo; năm 1947 chúng được chuyển giao cho Hy Lạp.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Chiếm đóng đảo Kos", "ab246c62"], "d": ["Kos, mắt xích cuối cùng của chiến dịch Dodecanese, là hòn đảo trù phú, đông dân nằm ngay đối diện bán đảo Bodrum. Với cuộc chiếm đóng này, tất cả các đảo ở góc đông nam biển Aegea đã rơi vào quyền kiểm soát của Ý, và bờ biển tây nam Anatolia bị bao quanh suốt chiều dài bởi một chuỗi đảo của ngoại bang.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Ikaria tuyên bố độc lập", "c4452033"], "d": ["Trên hòn đảo nhỏ Ikaria nằm giữa Samos và Chios, giữa bối cảnh bất định do các cuộc chiếm đóng của Ý gây ra, dân chúng nổi dậy, trục xuất hiến binh Ottoman khỏi đảo và tuyên bố một 'nhà nước tự do' với cờ, tem và nghị viện riêng, tồn tại năm tháng. Tháng 11 năm 1912, đảo sáp nhập vào Hy Lạp. Dù hòn đảo nhỏ bé, sự kiện này là dấu hiệu rõ ràng cho thấy chính quyền trung ương ở biển Aegea đã tan rã ra sao.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Samos thoát khỏi sự cai trị của Ottoman", "3a862f2b"], "d": ["Samos là một công quốc tự trị từ năm 1832, nộp thuế cho Ottoman và do một bey được Istanbul bổ nhiệm cai quản. Lợi dụng khoảng trống do chiến tranh Tripolitania tạo ra, phong trào chủ trương hợp nhất trên đảo nắm quyền cai quản và chế độ công quốc tự trị trên thực tế chấm dứt; cũng trong năm đó, đảo tuyên bố sáp nhập vào Hy Lạp. Hòn đảo cách bờ biển Anatolia hai kilômét này là một trong những vùng đất đầu tiên bị mất ở biển Aegea.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Ioannina thất thủ — mất Epirus và Parga", "d42fce18"], "d": ["Bị vây suốt năm tháng trong chiến tranh Balkan, Ioannina đầu hàng sau khi các trận địa Bizani thất thủ; cùng với thành phố, toàn bộ Epirus chuyển sang Hy Lạp. Parga thuộc sancak Ioannina cũng bị mất vào thời điểm này, và chín mươi tư năm cai trị của Ottoman chấm dứt. Mất Ioannina đồng nghĩa với việc cánh cửa sổ cuối cùng của đế quốc nhìn ra biển Adriatic đã đóng lại.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Edirne rơi vào tay người Bulgaria", "459d2e56"], "d": ["Sau cuộc vây hãm kéo dài năm tháng rưỡi, hết đạn dược và lương thực, Edirne đầu hàng; Şükrü Pasha bị bắt làm tù binh. Việc thất thủ một thành phố thuộc Ottoman từ năm 1361 và từng là thủ đô suốt chín mươi hai năm được coi là đòn nặng nhất của chiến tranh Balkan. Bốn tháng sau, trong chiến tranh Balkan lần thứ hai, Edirne được lấy lại nhờ lợi dụng việc Bulgaria sụp đổ trên các mặt trận khác.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Mất Yanbu vào tay lực lượng của Sharif Hussein", "e291c816"], "d": ["Cuộc nổi dậy do Sharif Hussein phát động hồi tháng 6 lan ra bờ Biển Đỏ; Yanbu, hải cảng của Medina, rơi vào tay quân nổi dậy với sự yểm trợ của hải quân Anh. Cảng này trở thành cửa ngõ chính cho dòng vũ khí và tiền bạc từ bên ngoài đổ vào cuộc nổi dậy. Như vậy lực lượng của Fahreddin Pasha ở Medina bị cắt đứt liên lạc với biển, và thành phố đơn độc ở đầu mút của tuyến đường sắt Hejaz.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["Trận Gaza lần thứ ba — mất Gaza và Khan Yunis", "c142a069"], "d": ["Sau hai lần thất bại, trong đợt tấn công thứ ba Allenby đã chọc thủng mặt trận bằng cách đánh vòng qua Beersheba, và phòng tuyến Gaza được giữ suốt sáu tháng đã sụp đổ. Gaza và Khan Yunis ở phía nam được bỏ lại ngay trong ngày. Cú đột phá này mở đầu cho sự tan rã của mặt trận Palestine; năm tuần sau Jerusalem sẽ thất thủ.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Chiếm đóng Komotini — mất Tây Thrace", "904d813c"], "d": ["Sau Hiệp định đình chiến Mudros, Tây Thrace trước hết đặt dưới quyền kiểm soát của quân Đồng minh Hiệp ước, rồi theo quyết định của hội nghị San Remo được để lại cho Hy Lạp, và quân đội Hy Lạp tiến vào Komotini. Vùng này, đã được lấy lại từ Bulgaria năm 1913, là mảnh đất cuối cùng đế quốc đánh mất ở Rumelia. Quy chế của cộng đồng người Thổ trong vùng được quy định ba năm sau tại Lausanne theo chế độ thiểu số. Với cuộc chiếm đóng này, các kazâ (huyện) Komotini, Xanthi, Alexandroupoli (Dedeağaç) và Soufli của Tây Thrace chuyển sang Hy Lạp.", "ef0aeba3"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["Hãn quốc Y Nhi tan rã: Abu Sa'id Bahadur Khan qua đời", "0f187469"], "d": ["Theo mục từ İlhanlılar (Ilkhanate) của Bách khoa toàn thư Hồi giáo TDV, việc Abu Sa'id qua đời không để lại người thừa kế đã khiến Hãn quốc Y Nhi, vốn thống trị Iran suốt một thế kỷ, bị chia cắt; các tướng lĩnh lợi dụng những cuộc tranh ngôi để lập nên các triều đại địa phương như Jalayirid, Qara Qoyunlu, Muzaffarid, Sarbadar ở Khorasan và nhà Eretna. Sự tan rã này chia khu vực thành một bức tranh khảm các tiểu quốc kéo dài một thế kỷ; cuối cùng nó được thống nhất lại qua các chiến dịch của Timur.", "ebf54b53"]},
"OLAYLAR_EK7:1387-01-01:0":{"b": ["Timur thâu tóm phần lớn Iran dưới quyền thống trị của mình", "1cee2b82"], "d": ["Theo mục từ Timur của Bách khoa toàn thư Hồi giáo TDV, từ đầu những năm 1380 Timur lần lượt xóa bỏ các triều đại địa phương hậu Ilkhanate như Sarbadar, Kart và Muzaffarid, và trong 'chiến dịch ba năm' 1386-1388 trên thực tế đã đặt phần lớn Iran dưới quyền thống trị của mình; còn dấu chấm hết dứt khoát cho triều đại Muzaffarid đến vào năm 1393. Như vậy, sau một thế kỷ chia cắt, khu vực lại thuộc về một chính quyền trung ương duy nhất.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["Chiến thắng sông Aras: Qara Yusuf đánh bại Abu Bakr Mirza nhà Timur", "4b61a75a"], "d": ["Sau khi Timur qua đời năm 1405, thủ lĩnh Qara Qoyunlu là Qara Yusuf trở về từ nơi lưu vong, lấy Avnik và giành lại đất đai ở Đông Anatolia, rồi tiến đánh Abu Bakr Mirza, cháu của Timur, người được coi là chủ của Azerbaijan và hai xứ Iraq, và đánh bại ông này bên bờ sông Aras. Chiến thắng này chưa đem Tabriz về cho Qara Qoyunlu: mục từ `tebriz` của TDV viết rằng năm 1408 thành phố nằm trong tay Abu Bakr Mirza; trận đánh giành được Azerbaijan là trận Sardrud ngày 13 tháng 4 năm 1408.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["Chiến thắng Sardrud: Tabriz và Azerbaijan về tay Qara Qoyunlu", "1f0a429d"], "d": ["Sau trận Aras, Qara Yusuf lần thứ hai đánh bại Abu Bakr Mirza nhà Timur tại Sardrud gần Tabriz; chiến thắng này đem Azerbaijan về cho Qara Qoyunlu. Sau đó Qara Yusuf giao cho Bistam Bey nhiệm vụ chinh phục Iraq-i Ajam;", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Dịch hạch ở Istanbul và triều đình dời sang Edirne", "70c7a163"], "d": ["Theo mục từ Istanbul của Bách khoa toàn thư Hồi giáo TDV, việc định cư nhanh và dày đặc tại thành phố đã tạo điều kiện cho dịch bệnh lan truyền theo từng đợt; trong trận dịch hạch năm 1466, triều đình và các đại thần tạm thời rút về Edirne. Dân số thành phố chịu tổn thất nghiêm trọng trong những đợt dịch như vậy.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["Uzun Hasan chấm dứt nhà nước Qara Qoyunlu", "ef68399e"], "d": ["Theo mục từ Uzun Hasan của Bách khoa toàn thư Hồi giáo TDV, quân chủ Aq Qoyunlu Uzun Hasan đánh bại và giết quân chủ Qara Qoyunlu Jahan Shah tại vùng Bingöl–Sancak ngày 12 Rabi' II 872 / 10 tháng 11 năm 1467; con trai Jahan Shah là Hasan Ali bị đánh bại tại Marand vào tháng 9 năm 1468 và bị giết trước thành Hamadan vào tháng 4-5 năm 1469, nhà nước Qara Qoyunlu bị chấm dứt hẳn. Lãnh thổ chuyển sang quyền thống trị của Aq Qoyunlu; trong thập kỷ tiếp theo, nhà nước này sẽ mở rộng vào sâu trong Iran.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Các madrasa Sahn-ı Semân khai giảng", "021f2a83"], "d": ["Theo mục từ Sahn-ı Semân của Bách khoa toàn thư Hồi giáo TDV, tám madrasa này, được lập trong quần thể Fatih, được thiết kế làm cơ sở giáo dục bậc cao nhất đương thời và là đỉnh của hệ thống thứ bậc giới học giả (ilmiye) Ottoman. Trong các thế kỷ sau, việc làm giáo sư (müderris) và tốt nghiệp tại đây được coi là bậc thang danh giá nhất trong sự nghiệp làm kadi và giáo sư.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Hoàn thành Cung điện Topkapı (Tân Cung, Saray-ı Cedîd)", "d2db6323"], "d": ["Theo mục từ Cung điện Topkapı của Bách khoa toàn thư Hồi giáo TDV, các nguồn đương thời không thống nhất về ngày khởi công và hoàn thành; theo niên đại 883 (1478) trên bia ở cổng Bâb-ı Hümâyun, công trình, có lẽ được khởi công năm 1465 theo lệnh của Sultan Mehmed II, về cơ bản đã hoàn thành đến năm này, và cung điện thay thế trung tâm nhà nước ở cung cũ. Như vậy sultan chuyển đến nơi ở mới, nơi sẽ là trái tim hành chính và nghi lễ của nhà nước suốt ba thế kỷ.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Bayezid II lên ngôi tại Istanbul", "9b686d04"], "d": ["Theo mục từ Bayezid II của Bách khoa toàn thư Hồi giáo TDV, hoàng tử Bayezid, khi đó là sancak bey của Amasya, nghe tin cha qua đời đã vội đến Istanbul và lên ngôi; nhờ sự ủng hộ của quân Janissary, ông đi trước em trai Cem, người khởi hành từ Konya. Trong lễ đăng quang, quân Janissary được phát tiền thưởng đăng quang theo lệ. Cuộc chuyển giao ngôi vị này cũng châm ngòi cho cuộc tranh giành giữa hai anh em.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Cem Sultan tự xưng sultan tại Bursa", "b355168a"], "d": ["Theo mục từ Cem Sultan của Bách khoa toàn thư Hồi giáo TDV, Cem đi qua Karaman đến Bursa, chiếm thành phố, tự xưng sultan và cho đọc khutba nhân danh mình. Triều đại ngắn ngủi này chấm dứt khi lực lượng do anh trai Bayezid II phái đến đánh bại Cem tại Yenişehir. Sau thất bại, Cem buộc phải chạy sang Ai Cập.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Gedik Ahmed Pasha bị xử tử", "6d75a58c"], "d": ["Theo mục từ Gedik Ahmed Pasha của Bách khoa toàn thư Hồi giáo TDV, vị pasha nổi tiếng với chiến dịch Otranto và chức đại tể tướng đã bị xử tử tại Edirne theo lệnh của Bayezid II, do thái độ của ông trong vụ Cem Sultan và mối lo ngại về thế lực của ông. Cái chết của một trong những tướng lĩnh dày dạn nhất thời Sultan Mehmed II gây tiếng vang lớn trong triều.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Lập nhà in đầu tiên tại Istanbul", "04475930"], "d": ["Theo mục từ Matbaa (Nhà in) của Bách khoa toàn thư Hồi giáo TDV, hai anh em David và Samuel ibn Nahmias, người Do Thái di cư từ Tây Ban Nha, đã lập tại Istanbul nhà in đầu tiên in bằng chữ Hebrew. Đây được ghi nhận là nỗ lực in ấn đầu tiên hoạt động trên lãnh thổ Ottoman; còn việc in tiếng Thổ bằng chữ Ả Rập mãi sau này, vào thế kỷ XVIII, mới thực hiện được.", "118df98b"]}
});
